window.IV=window.IV||{};IV.univ=IV.univ||{};IV.univ["u105"]={"univ":"인하대학교","reviews":[{"univ":"인하대학교","dept":"간호학과","jeonhyeong":"학생부종합(미래인재전형)","method":"2대1(면접자) 면접으로 과마다 조를 이루어 동시에 진행","notes":"자신의 아날로그 시계를 들고 가면 비교적 편할 수 있음.","qa":[{"q":"유전자 돌연변이에 대해 조사한 바가 있던데 유전자 돌연변이로 인한 질환과 증상을 얘기해주세요.","a":"유전자 돌연변이로 인한 질환으로는 다운증후군이 있습니다. 증상은 기억나지 않습니다."},{"q":"부반장으로 활동한 이력이 있는데 갈등 상황은 없었나요?","a":"저는 3학년 1학기에 부반장으로 활동하였습니다. 이 시기에 다들 학업에 열중하는 분위기라 갈등은 딱히 없었습니다. 저는 학생회로 활동한 적이 있는데 말씀드려도 되겠습니까?학생회 활동을 하며 제가 가장 기억에 남는 활동은 작년도 축제 준비였습니다. 당시 저는 그 전 기수의 학생회 선도부의 임원으로 활동하였었습니다. 하지만 다음 기수의 학생회 임원 다른 친구가 되어 축제에 대한 지식이 부족한 경우가 발생하였습니다. 그래서 그 친구를 도와 인원 배치와 갈등 관리, 질서 유지를 했던 경험이 가장 기억에 남습니다."},{"q":"가상 인터뷰를 통해 좋은 간호사가 되겠다는 다짐을 하였다고 쓰여있는데 어떤 간호사가 좋은 간호사일까요?","a":"당시에 남자 간호사에 대한 고민 때문에 이 활동하게 되었지만, 이 활동을 통해 성별은 중요하지 않고 어떤 간호사가 좋은 간호사인지 생각하였습니다. 제 생각에 좋은 간호사란 업무수행 능력을 바탕으로 환자들과 소통하며 공감하는 간호사가 좋은 간호사라고 생각하게 됐으며 앞으로 이 학교에 진학하게 된다면 위의 간호사가 되기 위해 열심히 노력하겠습니다."},{"q":"고령화와 저출산에 대해 관심이 많은 것으로 보이는데 고령화와 저출산의 원인과 해결 방안이 무엇인 것 같나요?","a":"제가 생각하기론 저출산은 예전보다 물가가 많이 올라 경제적으로 많이 부담이 되며, 높은 실업률, 청소년 범죄 등의 사회적인 불안이 요인이 되는 것으로 알고 있습니다. 이로 인해 인구피라미드가 역으로 간다고 생각합니다. 이를 대응하기 위해 지금 일본에서는 노인개인보험처럼 간병과 요양 정책을 발달시키고 있다고 알고 있습니다. 이를 본받아서 노인을 위한 정책을 통해 사회에 활기를 불어넣어야 한다고 생각합니다."},{"q":"국경없는의사회에서 일하고 싶다고 쓰여있는데 특별한 이유가 있나요?","a":"제가 간호사가 되고 싶은 이유는 단순히 사람의 안녕과 건강을 위해 힘쓰고 싶기 때문입니다. 선진국과 같은 나라들은 의료시설이 잘 되어있는 경우가 많지만 빈곤하거나 나라 상황이 좋지 않은 나라는 사람들이 의료서비스를 제대로 받기 힘들기에 그런 사람들을 돕고 싶어 봉사하고 싶습니다."}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"인하대학교","dept":"건축학부 건축학과","jeonhyeong":"학생부종합(미래인재전형)","method":"약 10분 간 진행되며 2명의 면접관과 진행","notes":"블라인드면접 교복입고가면 안 됨. 휴대폰같은 전자기기는 나눠준 팩에 넣어야 함. 대기시간 때 더 준비하려면 종이에 적어가야 함.","qa":[{"q":"지원동기","a":"전 어린 시절 우연히 다큐에서 가우디의 사그리다 파밀리아 대성당의 하늘을 찌를듯 높고 뾰족한 첨탑과 자연의 모습을 담은 듯한 벽을 보고 '나도 저렇게 멋진 건물을 만들고싶다'고 생각하게 되었습니다. 그렇게 건축사가 되기 위해 여러 대학을 알아보던 중 인하대학교가 우리나라 대학중 손에 꼽히고 건축학 교육 인증을 받은 학교이기에 지원했습니다"},{"q":"미술시간 때 그린 초현실주의작품이 뭐였는가?","a":"저는 초현실주의가 현실 세계에서의 뒤틀림이라 생각하였습니다. 그래서 밤하늘의 달을 주제로 하늘에는 호수 속에 비쳐 일렁거리는 달과 호수 속에 일반적인 달을 그렸습니다"},{"q":"2학년 자율동아리 때 무슨 활동을 했는가?","a":"저는 1학기 때 같은 동아리 친구들과 조를 짜고 자동차와 건축에 사용되는 it기술을 주제로 조사했습니다. 전 그 중에서 안전을 위한 건축it기술을 조사했습니다. 그리고 2학기에선 이와 연계해 내진 설계에 대해 조사했습니다."},{"q":"2학년 자율동아리 때 겪은 어려움과 해결방법","a":"큰 주제를 잡는데 어려움을 겪었습니다. 건축과 it.자동차와 it는 서로 연결이 되지만 건축과 자동차는 연결이 쉽지 않았습니다. 그래서 의견을 주고받던 중 건축, it, 자동차 3개를 서로 연결시키지 말고 it라는 큰 주제에 자동차와 건축이라는 주제를 연결하자는 의견을 내었고 다른 조원들의 동의를 얻어 그대로 진행하게 되었습니다."},{"q":"조사한 내진설계에 대해 설명해보세요.","a":"내진설계에는 내진, 제진, 면진, 차진 구조가 있습니다. 내진은 단순히 건물을 튼튼히 짓는 것이고, 제진은 지진의 진동과 반대 방향으로 힘을 작용해 지진을 상쇄 시킵니다. 면진은 특수한 자재를 건물 밑에 깔아 지진력 자체를 줄입니다. 마지막으로 차진은 자기장을 이용해 건물을 띄우는 것입니다. 다만 아직 연구중인 기술입니다."}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"인하대학교","dept":"경영학과","jeonhyeong":"학생부종합(미래인재전형)","method":"면접관 2명, 수험생 1명의 개별면접/ 블라인드 면접/ 10분 내외","notes":"경영학과 특성상 사람이 많아서 그런지 면접 시간이 7분 밖에 되지 않았으며, 타이머로 정확히 7분을 맞추고 시작하되 타이머가 울리면 그때 말하고 있던 것까지만 마무리 짓게 하셨음. but 이건 과마다 상이함.대기실에서 연습할 시간이 조금 있으나 전자기기 사용은 불가.","qa":[{"q":"이커머스 시장이나 온라인 플랫폼과 관련한 탐구를 많이 진행한 것 같고 이와 관련하여 온라인 플랫폼에서 조건부확률을 이용한 마케팅에 관해 탐구를 진행했는데, 이에 관해 설명해 보세요.","a":"조건부확률이란 어떤 사건이 일어난다고 가정했을 때 다른 사건이 일어날 확률을 말합니다. 저는 온라인 플랫폼에서 소비자의 구매 패턴과 관련한 데이터를 수집하여 이를 조건부확률과 접목시킨다면 소비자 맞춤형 서비스를 제공하는 마케팅이 가능할 것이라고 생각하였습니다. 예를 들어 한 소비자가 태블릿 PC를 구매한다고 가정하였을 때 펜슬을 구매할 확률은 70%, 이어폰을 구매할 확률은 40%라고 한다면 이 소비자의 온라인창에는 펜슬과 관련한 제품을 띄우는 것이 더 효과적인 것입니다."},{"q":"1학년 행동특성 및 종합의견에 학급에서 가장 온순하고 선한 학생이라고 적혀있는데, 왜 그렇게 생각하는지 얘기해 보세요.","a":"저는 초반에는 사실 낯을 조금 가리는 것도 있고 성격 자체가 제 의견을 무조건적이고 적극적으로 밀고 나가는 성격은 아니기 때문입니다. 또한 학급 분위기에 적응해 가면서 다른 사람의 의견을 경청하고 이에 공감하며 밝게 웃어주는 그런 성격이기에 선생님께서 그렇게 생각해 주신 것 같습니다."},{"q":"경영학 안에서도 많은 세부 분야가 있는데 이 중에서 자신이 가장 관심있는 분야가 있나요?","a":"제품을 생산하고 관리하는 것과 기업의 재무를 관리하는 것 등도 중요하지만 생산된 제품을 홍보하고 어떻게 하면 효과적으로 판매할 수 있을지 전략을 세우는 것 또한 정말 중요한 과정이라 생각하여 마케팅 분야에 가장 관심이 있습니다."},{"q":"마케팅 분야 외에도 경영학의 다른 세부 분야에 관해 알고 있나요?","a":"아직까지 엄청 자세히는 알고 있지 않지만, 재무 관리나 인사 관리 등과 같은 세부 분야가 있다는 것을 알고 있습니다."},{"q":"나중에 어떤 기업에 들어가고 싶나요?","a":"현재 주목받고 있는 ESG 중 E, 즉 환경적 측면이 가장 강조되고 있기도 하고 저는 환경 보호를 중요시 여기는 친환경 마케터를 꿈꾸는 만큼 각 기업들의 목표나 비전 등을 꼼꼼히 분석한 뒤 환경 보호를 적극적으로 실천하는 기업에 들어가고 싶습니다."},{"q":"그런 게 아니라 예를 들어 전자제품 기업이라던가, 의류 기업이라던가 이런 구체적인 기업 말이에요.","a":"아, 저는 자원 낭비가 가장 심한 부분이 식품과 의류 쪽이라고 생각하여 식품 기업이나 의류 기업에 들어가고 싶습니다. 의류 기업 중 하나인 파타고니아라는 기업이 있는데, 이 기업은 석유 기반 재질로 만들어지던 기존 의류 제작 방식에서 벗어나 폐플라스틱을 재활용하여 의류를 제작하여 판매한 사례를 본 적이 있습니다. 저도 이러한 기업에 들어가 환경 보호에 기여하는 마케터가 되고 싶습니다."},{"q":"아 그러면 마케팅, 재무 관리, 인사 관리 쪽에 관심이 있으면서 친환경을 실천하는 그런 기업에 들어가고 싶다는 건가요?","a":"네, 친환경을 실천하는 건강한 기업 속에서 마케터로서 저의 역할을 다하고, 재무 관리나 인사 관리 쪽도 열심히 배우며 저의 자질을 키워나가고 싶습니다."}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"인하대학교","dept":"물리학과","jeonhyeong":"학생부종합(미래인재전형)","method":"2대1 가운데 책상 있음. 처음부터 생기부 이야기 하심.","notes":"","qa":[{"q":"생기부에 보면 물리학을 사랑하고 열심히 하신다고 적혀있는데 좋아하게 된 계기나 이유 말씀해 주세요.","a":"고등학교 교육과정을 배우고 나서 자연현상에서 발견되는 것을 보고 흥미를 느꼈고 열기관에서 전자기학, 열역학 등을 사용할 수 있다는 것이 흥미로웠습니다."},{"q":"생기부에 체육 시간에 배드민턴에서 운동량 충격량을 이용하는 방법을 설명했다 하셨는데 충격량을 늘리는 방법을 설명해주세요.","a":"배드민턴 라켓 장력 조절해 충돌 시간을 달리하여 충돌시간을 변화시켜 충격량을 다르게한다 설명함."},{"q":"충격량에 대해 정확히 설명해주세요.","a":"충격력과 충돌시간의 곱으로 나타낸 물리량으로 물체의 운동을 변화시켜 운동량 변화량입니다."},{"q":"물리학 실험에서 가속도 실험을 하셨는데 뉴턴 제2법칙을 설명해주세요.","a":"힘과 가속도, 질량의 관계를 나타낸 물리량으로 실험을 통해 일정한 힘에 질량을 변화시켜 가속도를 알아낼 수 있습니다."},{"q":"탄동 진자에서 운동량 보존 법칙과 에너지 보존 법칙이 사용된다고 했는데 설명해주세요.","a":"총알이 발사되었을 때 처음 총알의 운동량과 정지되어 있는 나무토막의 운동량의 합이 충돌 후 총알이 나무토막에 박혔을 때 두 질량과 그 이후 속도를 곱한 값이 처음과 같고 그때의 운동에너지와 나무토막이 올라갔을 때 높이에 위치에너지가 같습니다."},{"q":"마지막으로 하고싶은 말씀 해주세요.","a":"이 학교에서 더 공부를 하고 싶고 좋은 시설에서 실습과 경험을 해보고 싶습니다. 경청해주셔서 감사합니다."}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"인하대학교","dept":"기계공학과","jeonhyeong":"학생부종합(미래인재전형)","method":"면접실 건물 밖에서 대기하다가 입실 시간이 되면 조별로 면접 대기실로 입장합니다. 대기 하고 있다가 순서가 되면 면접실 문 앞에서 1~2분 정도 기다렸다가 입장합니다. 한 명당 7분의 시간을 부여받으며, 7분 타이머를 재고 면접을 진행했습니다.","notes":"절대 자기 인적 사항과 관련된 것을 말하면 안됩니다. 출신학교, 이름 등은 특히 안되며, 오직 대기실에서 받은 명찰의 가번호만으로 식별됩니다.","qa":[{"q":"행발에 리더쉽 관련 내용이 있는데 구체적으로 어떤 활동을 했는지?","a":"(준비했던 내용) 1학년 때 동아리장을 맡아 활동 계획을 짰었는데, 당시 서로 모르는 친구들이 많아서 활동 초기에는 과학 영화 시청 후 흥미있는 내용에 대해 자유롭게 발표, 토론해보는 시간을 가지도록 했습니다. 또, 2학년 때는 ‘건축물 속 함수’ 주제로 하여 매 교시 반을 돌며 직접 수업을 진행하였습니다. 금문교와 같은 다리 구조물의 형상을 수학 어플을 통해 수식을 써서, 그래프로 표현해 보도록 하고 원하는 다리 모양을 함수식을 써서 마음껏 만들어 보도록 하였습니다. 학우들이 모두 수업에 참여할 수 있도록 옆에서 도와주었었는데, 그 중 저에게 와 수업 잘 짰다며, 알고 있는 함수를 총동원해서 다리를 만들어 낸 그래프를 그려 발표했던 친구도 있었는데 이때 가장 큰 보람을 느꼈던 거 같습니다."},{"q":"4행정 사이클에 대해 탐구하였다고 되어있는데 어떤 내용인지?","a":"(대답 못함) (준비했던 내용->) 4행정 사이클은 내연기관에서 동력을 생성하는 기본 과정입니다. 먼저, 공기와 연료가 실린더로 들어오는 흡입 과정을 거칩니다. 그다음 피스톤이 올라가면서 혼합기를 압축합니다. 이 상태에서 점화 플러그가 불꽃을 튀기면 폭발이 일어나고, 그 힘으로 피스톤이 내려가면서 동력이 생성됩니다. 마지막으로 연소 후의 배기가스를 실린더 밖으로 배출하며 사이클이 마무리됩니다. 이 과정이 반복되면서 엔진이 작동하게 됩니다."},{"q":"소닉붐에 대해 탐구 보고서를 작성했다고 되어있네요. 설명해주세요.","a":"소닉붐은 물체가 음속을 초과할 때 발생하는 큰 폭발음입니다. 아음속에서는 물체의 속도가 음속보다 느려 소닉붐이 발생하지 않습니다. 음속에 가까워지면 작은 충격파가 형성될 수 있습니다. 초음속을 넘으면 소닉붐이 본격적으로 발생하며, 극초음속(5마하 이상)에서는 충격파와 소음이 훨씬 강해집니다. 소닉붐은 주로 초음속 비행기나 로켓이 비행할 때 발생합니다."},{"q":"'코안다 효과와 베르누이 정리의 차이점' 이 무엇인지?","a":"우선 코안다 효과는 유체 흐름이 벽면에 붙어 가게 되는 현을 말합니다. 베르누이 효과는 유체의 속도와 압력에 관한 관계를 다루는 반면 코안다 효과는 유체와 벽면, 그리고 점성에 관한 관계를 다루고 있는 차이점이 있습니다."},{"q":"수탐에서 서스펜션 상황을 방정식으로 표현했다고 되어있는데 구체적으로 설명해주세요.","a":"(잘 생각나지 않아 다른 내용으로 대신 답변하겠다고 함.) 저는 미적분과 공학이 아주 밀접하다고 생각하여 이와 관련하여 자동차 충돌 시뮬레이션 실험을 진행한 적이 있었는데, 우선 알테어 심솔리드 툴을 다운받고, 게임 3d 모델 사이트에서 자동차 모형을 다운받아 이를 이용하여 자동차 구조 형태별로 하중을 주며 충돌 시에 운전자가 어떻게 피해를 받을지 생각해보았습니다. 이를 통해 어떤 설계가 운전자의 안전을 가장 고려할 수 있는지에 대해 생각해볼 수 있었습니다."},{"q":"(시간 끝나고 추가로 말한 포부)","a":"(마지막 한 마디 해도 되겠습니까?) 저는 3학년에 올라와 미적분을 본격적으로 공부하기 시작하면서 기계공학에 대한 관심이 정말 많이 깊어졌습니다. 수학과학 관련의 심화 탐구를 하며 이전에는 넘어갔던, 복잡해 보이던 식과 내용들(테일러 급수라던가, 제어시스템에서 쓰이는 식들)이 미적분을 배운 후부터는 하나둘 그 의미를 파악할 수 있게 되면서 진심으로 ’이런 탐구 내용들이 순수한 흥미로 다가올 수 있구나‘ 하고 정말 심장이 뛰는 경험을 했습니다. 이런 호기심이 여기서 그치지 않고 본교에 입학하는 것이 저의 궁금증들을 꼭 풀어나갈 수 있는 첫 단추가 되었으면 하고 바랍니다."}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"인하대학교","dept":"반도체시스템학과","jeonhyeong":"학생부종합(미래인재전형)","method":"","notes":"압박면접은 절대 아니고 편안한 분위기 속에서 진행됨 그리고 질문이 ‘~~를 말해보세요’가아닌 ‘~~ 활동에 대해 자유롭게 느낀 점이나 활동을 말해보세요’의 형태임6.7분정도 짧게 진행함. 그래서 답변할때 장황하게 말고 임팩트 있게 말해야 함 (시간 관계상 / 길게 말하면 면접관들의 집중이 떨어짐)꼬리 질문은 없었고 전반적으로 생기부 활동의 진위 여부를 파악하는 느낌. 꼬리 질문 준비 말고 생기부 정도만 파악하면 될 듯","qa":[{"q":"지원동기에 대해 말해 보세요.","a":"현대 산업에 있어서 반도체는 필수적인 부품이고 미래에 떠오르는 이미지로 자율주행차, 인공지능, 전자기기 등 미래산업에서도 필수적인 부품이라는 점에서 저에게 매력적으로 다가왔습니다. 따라서 반도체에 대해 직접 탐구하고 싶어 지원하게 되었습니다"},{"q":"정보시간에 머신러닝에 대해 배우셨는데 한 활동에 대해 자유롭게 서술하세요.","a":"제 얼굴을 인식시키는 머신러닝 학습을 하였고 제 친구 얼굴과 제 얼굴을 구별하는 과정에서 디지털 언어, 0.1로 이루어져 있지만 이렇게 구별한다는 것이 신기했습니다."},{"q":"트랜지스터 원리에 대해 말해보세요.","a":"npn형 반도체에 대해 설명하겠습니다. N.p.n이 결합되어 있는데 p형은 굉장히 얇습니다. 그래서 한쪽에 순방향을 연결하면 반대는 역방향이기 때문에 전류가 흐르지 않고 전압을 높여주면 p형반도체가 얇아서 전자가 튕겨 나가 전류가 흐르게 됩니다. 이로써 전류를 조절하는 원리입니다."},{"q":"반도체시스템공학과에 오게된 결정적인 계기가 있을까요?","a":"반도체와 관련하여 그래핀이 소자로 사용될 때의 장단점 그리고 현재 상용화되지 않는 한계와 앞으로의 발전 방향성에 대해 분석하며 반도체에 흥미를 느끼게 되었다."},{"q":"마지막으로 하고 싶은 말이나 자기가 한 활동이 있으면 자유롭게 말해보세요.","a":"떨리는 마음으로 1차 준비를 하며 발표를 기다렸는데 면접이라는 좋은 기회를 주셔서 감사합니다. 면접 준비를 하며 이학과에 오고 싶다는 열정을 다시 확인할 수 있었습니다. 저에게 다시 입학이라는 좋은 기회를 주시면 열정적인 모습으로 학교에 기여하겠습니다."}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"인하대학교","dept":"산업경영공학과","jeonhyeong":"학생부종합(인하미래인재)","method":"2:1 면접","notes":"","qa":[{"q":"우선, 산업경영공학과에 지원하게 된 동기와 간단하게 자기소개 해주세요.","a":"제가 산업경영공학과에 지원하게 된 가장 큰 이유는 저의 특성과 장점을 살려서 할 수 있는 일이라고 생각하기 때문입니다. 저는 중학교 때 정보 수업으로 처음 코딩을 접하며 코딩에 흥미를 가지게 되었습니다. 이후 고등학교에 올라와 빅데이터 학과 체험으로 직접 코드를 입력해서 프로그램을 만드는 활동에서 해당 분야에 더욱 큰 관심을 가지게 되었습니다. 산업경영공학과는 코딩을 기반으로 산업시스템을 설계, 분석, 운용하고 최적화하는 것을 배우는 학과라고 알고 있습니다. 코딩을 배울 수 있는 것은 물론이고, 수학, 과학, 경영 등 여러 가지 분야를 폭넓게 배울 수 있다는 것이 큰 매력으로 다가왔습니다. 저는 학과 추천 검사에서 컴퓨터 다음으로 경영이 나올 만큼 경영에도 관심을 가지고 있어서 경영도 배울 수 있다는 것이 좋았습니다. 그래서 최종적으로 산업경영공학과에 지원하게 되었습니다."},{"q":"코딩을 재미있어 한다고 했는데 어떤 언어를 사용해 봤나요?","a":"2학년 때 파이썬을 배운 적이 있습니다."},{"q":"다른 언어는 안 해봤어요?","a":"컴퓨터학원에서 C언어랑 C++을 조금 배운 적이 있습니다."},{"q":"3학년 1학기 때 수학 교과 성적을 보니 좀 떨어졌는데, 그 이유가 뭔가요?","a":"3학년에 올라가면서 미적분 과목을 배우게 되었습니다. 아무래도 제일 어려운 수학파트이기도 하고, 3학년 마지막 학기라는 압박감과 스트레스 같은 정신적 요인이 작용한 것 같습니다. 3학년이라서 여러 활동들도 많아서 상대적으로 수학에 투자하는 시간이 적었던 것 같습니다. 그래서 다른 학기에 비해 수학 성적이 낮게 나온 것 같습니다. 하지만 수학 공부를 소홀히 하지는 않았습니다. 들인 시간은 조금 적을지라도 공부하는 순간 순간 최선을 다해 집중하며 효율적으로 공부하려고 노력했습니다. 대학교에 진학하고 나서도 학과 특성상 수학 공부를 계속 해야 하는데, 3학년 1학기 성적이 떨어졌다고 해서 수학 공부에 차질이 생기지는 않을 것이라 말할 수 있습니다."},{"q":"수학2에서 2차원의 이미지를 3차원의 정보를 변환하는 과정을 탐구했다고 했는데, 이것에 대해서 간단히 설명해 주세요.","a":"그 활동은 제가 MRI에 미적분이 어떻게 쓰이고 있는지 조사하다가 푸리에 변환을 조사한 활동이었는데, 내용이 어려워서 완전히 다 이해하지는 못하였습니다. 그래서 대학에 가서 이 내용에 대해 제대로 배우고 이해하고 싶습니다."}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"인하대학교","dept":"생명과학과","jeonhyeong":"학생부종합(미래인재전형)","method":"지원자 1명, 면접관 2명, 6-8분(교수님들 엄청 밝게 웃으시고 편안한 분위기 만들어주심)교수님: 네 긴장하지 마시고, 질문에 답이 생각 안 나시면 말해주세요 다음 질문으로 넘어가겠습니다","notes":"생각보다 시간이 너무 짧고 생기부 질문은 1개정도만 함 다른 지원자들도 꼬리질문 없었던 걸로 앎 엄청 밝게 웃으시고 편안하게 말 들어주시며 전혀 긴장을 안 했어도 될 것 같았음. 교수님과 눈을 계속 마주치는게 중요하다고 생각이 들었음. 똑바로 쳐다보고 말하니 웃으면서 반응해 주심.","qa":[{"q":"3학년 1학기 때 수학 교과 성적을 보니 좀 떨어졌는데, 그 이유가 뭔가요?","a":"자기소개와 지원동기, 왜 이 과에 지원하게 되었는지 구체적으로 말해주세요.네 저는 노화에 관심이 많은 학생입니다. 어렸을 적부터 할머니와 함께 지내면서 깊은 유대감을 형성하였습니다. 이제 할머니께서 나이가 드시면서 건강에 대해서 걱정하게 되었습니다. 따라서 자연스레 퇴행성 뇌질환과 노화에 대해서 탐구하게 되었습니다. 그때 인하대학교의 노화생물학 연구팀의 기사를 유독 많이 보게 되었습니다. 인하대학교 노화생물학 연구팀은 2012년에는 고려대와 함께 조선시대 환관과 동시대 양반 남녀의 수명을 연구하고 2005년부터는 겨우살이 추출물 베툴리산이 생명을 연장시키고 노화를 늦춰준다는 사실을 발견한 것을 알게됐습니다. 저는 끊임없이 노화에 대해서 연구하는 인하대를 보고 꼭 인하대여야만 한다고 생각하여 지원하게 되었습니다.교수님들:(웃으시면서) 재밌네요 저도 몰랐던 건데 (다른 교수님꼐) 알고 계셨나요?다른 교수님: 아뇨"},{"q":"그 다음 질문할게요. 생기부에서 퇴행성 뇌질환에 대해서 탐구하였다했는데 내용 말해 주세요.","a":"네 저는 퇴행성 뇌질환 중에서 알츠하이머에 대해서 탐구하였습니다. 최근 요소회로가 알츠하이머의 원인으로 나타났는데요. 요소회로는 간에서 암모니아를 회독합니다. 이때 요소회로가 뇌 속 별세포에서도 발견이 되었습니다. 이 요소회로가 활성화되었다가 다시 회복되면 문제 없지만 알츠하이머 환자의 뇌에서 계속 활성화되고 있다 합니다.요소회로가 활성화되면 가바라는 억제성 신경전달물질이 분비됩니다. 이때 가바는..(긴장이 너무 돼서 갑자기 말이 안 나옴) 죄송합니다 잠시만요"},{"q":"괜찮아요 천천히 하세요.","a":"감사합니다. 가바는 기억력을 담당하는 해마의 도파민을 억제해 문제가 됩니다.(하고 또 말문이 막혔음)교수님들: (이번에는 바로 넘어가심) (웃으면서) 괜찮아요 긴장을 많이 했나보네요 잘 들었어요 다음 질문 넘어갈게요(더 말하고 싶었는데 넘어가셔서 아쉬웠음)"},{"q":"이젠 제가 질문하고 싶어요~ 생기부를 보니깐 1학년장, 학년부회장으로 활동을 하였는데 리더십으로 친구들을 이끈 가장 자기를 자랑할 수 있고 저 이런 사람이에요를 말할 수 있는 활동을 말해 주세요.","a":"학생회 활동 얘기함"},{"q":"앞서 자기소개에서 노화에 대해서 관심있다 하였는데 생기부에서는 노화에 대해서 퇴행성 뇌질환에 대해서 없네요. 노화에 관심 갖게 된 계기와 생기부에는 없지만 추가로 탐구한 내용이 있을까요?","a":"네 저는 모든 생명과학에 관심이 많은 학생입니다. 하지만 이제 고령화 사회가 진행되면서 노화에 대해서 연구하는 것이 가장 중요하다고 생각합니다. (이때 타이머 울려서 당황함. 교수님께서 괜찮다고 마저 말하라해서 이어감)또한 저의 할머니께서도 건강이 악화되고 계셔서 걱정되는 마음에 노화에 대해 관심이 커졌던 것 같습니다. 저는 이별을 어려워해 소중한 사람들을 이별하는 것을 맞이하는 게 쉽지 않아 수명에 대해서 더 탐구하고 싶어서 지원하게 된 것 같습니다. (시간이 없어서 노화에 대해서 추가로 탐구한 거는 말 못함)교수님: 잘 들었습니다 수고했어요~감사합니다 하고 인사 계속 하며 나옴"}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"인하대학교","dept":"생명공학과","jeonhyeong":"학생부종합(미래인재전형)","method":"생기부 기반 면접(10분 내외)/ 면접관 2명 대 학생 1명","notes":"","qa":[{"q":"반장, 전교부회장, 동아리장 등의 다양한 활동을 했는데 본인이 생각하는 리더의 자질이란 무엇일까요?","a":"1학년 때는 반장이 처음이라서 그냥 친구들을 대표해서 이끌고 앞에서 주도하는 등의 역할만 생각했는데, 점점 소외되는 친구나 의견을 내지 못하는 친구들을 뒤에서 챙겨주는 것도 리더로서의 역할이라고 생각하게 되었습니다. 그래서 나중에는 항상 어떤 행사나 활동이 있을 때 마지막으로 나가고 뒤에서 밀어주는 것이 리더로서 필요한 자질이라고 생각하게 되었습니다."},{"q":"수학2 수행평가 시간에 그래프를 활용해 DNA 이중나선, 모래시계, 비커, 원자모형 등 전교에서 가장 인상적인 작품을 만들었다고 하는데 그중에서 하나만 골라서 자세하게 설명해주세요.","a":"그래프 그리는 앱을 통해 DNA 이중나선 모형을 사인함수와 코사인 함수를 이용해 서로 엇갈리게 만든 후 상수함수로 이어지게 만들었습니다."},{"q":"생명과학 시간에 노화와 수명연장이라는 주제로 텔로미어와 관련된 내용을 탐구했다고 하는데 내용을 자세히 설명해보세요.","a":"우연히 도서관에서 읽은 책에서 가재는 텔로미어가 줄어드는 것을 막을 수 있는 텔로머레이스라는 효소가 있어서 100년 넘게 살 수 있다는 것을 알게 되었는데, 처음 알게된 내용이라서 텔로미어가 뭐고, 또 텔로머레이스라는 효소는 뭔지 좀 더 자세하게 알아보고 싶어서 탐구하게 되었습니다. 텔로미어는 염색체의 말단 부분으로 보호와 안정성 유지의 역할을 하는데 세포분열을 하게되면 점차 손실되어 줄어들게 됩니다. 그러다 일정 수준까지 줄어들게 되면 세포가 사멸하게 되고 이게 노화의 원인 중 하나로 알려져 있습니다. 그리고 가재에 있는 텔로머레이스는 이러한 텔로미어의 손실을 막을 수 있는 효소이고 특히 암세포도 텔로머레이스라는 효소를 가지고 있기 때문에 무한하게 증식할 수 있습니다. 그래서 제가 생명공학과에 입학하게 된다면, 가재에서 이 효소를 추출하거나, 암세포에서 추출한 후 인간에게 주입해 수명연장과 노화 방지에 도움이 되는 기술을 연구하거나 개발해보고 싶다는 생각까지 하게 되었습니다."},{"q":"화학 시간 주제 탐구 시간에 중합효소연쇄반응에 관해서 탐구했다고 하는데 좀 더 자세하게 설명해주세요.","a":"중합효소연쇄반응이란 소량의 DNA를 증폭시켜 주는 것으로 예전 코로나19가 유행했을 때 자가 키트도 이 중합효소연쇄반응을 이용한 것입니다. 중합효소연쇄반응은 DNA 이중가닥을 한 가닥으로 분리시키는 변형, 시발체와 결합하는 결합과 DNA를 증폭시키는 합성등의 과정을 통해 진행됩니다."},{"q":"TLC판을 이용해서 실험한 활동이 있던데 실험의 원리를 설명해보세요.","a":"우선 TLC란 얇은막 크로마토그래피로 극성과 무극성의 상호작용을 이용한 실험기법입니다. TLC판은 극성이고 전개율 액은 비교적 무극성이기 때문에 시료의 성분의 극성이 클수록 TLC판에 더 잘 흡착되어 전개율 값이 작아진다. 여기서 전개율 값이란 시료의 이동 거리/전개액의 이동 거리로 구할 수 있습니다."},{"q":"1학년 때 학과체험시간에 치위생학과를 체험한거 보니깐 1학년때는 치위생에 관심이 있었던 것 같은데?","a":"아 그때 그나마 생명공학과와 관련있는 학과가 치위생학과라서 하게 되었습니다.."},{"q":"책을 읽으면서 탐구한 경험이 많을걸 봐서 책을 많이 읽은거 같은데 그중에서 제일 인상깊게 읽은 책은?","a":"어떤 죽음이 삶에게 말했다라는 김범석이라는 의사분이 쓰신 책이 가장 인상 깊었습니다. 그래서 제가 이 책을 두 번 읽었는데 처음 읽었을 때는 그냥 죽음이라는 것에 대해서 깊게 생각해본 적이 없었는데 책을 읽고 죽음에 관해서 깊게 생각해 보고, 하나하나의 에피소드들에 공감하고 슬프다고 생각했었습니다. 그런데 두 번째 읽을 때는 암으로 돌아가시는 분들이 너무 많아서 이를 계기로 암을 완벽하게 치료할 수 있는 치료제 등을 셍명공학과에 입학해 연구하고 개발하고 싶다는 다짐을 하게 되었고, 또 수면연장을 위해 텔로머레이스 효소에 관한 연구를 해보고 싶다는 생각을 하게 되었습니다."},{"q":"왜 인하대야?","a":"우선 공대의 강세라고 불리는 인하대에서 가장 유명한 학과인 생명공학과가 저에게는 매력적으로 느껴졌으며, 생명공학과라는 이름으로 처음 생긴 최초의 학교이기 때문에 역사와 전통이 있는 학교이기 때문에 인하대에 더더욱 오고 싶었습니다. 또한 정부에서 지정한 Brain Korea 21이라는 BK21 연구팀에도 들어가서 혁신을 위한 노력을 힘쓰고 싶다고 생각했기 때문입니다."},{"q":"마지막으로 하고 싶은 말있으면 안 해도 될거 같지만 하고 싶은 말있으면 해주세요.","a":"들어왔을 때 보셨는지는 모르겠지만 저는 또래에 비해 키가 큰 편입니다. 그만큼 면접보면서 부족했던 점이나 보시면서 아쉬웠던 부분이 있었다면 엄청 빠른 성장속도로 다 따라잡을 수 있고 노력할 수 있으니깐 꼭 뽑아주신다면 열심히 하겠습니다!!!!! 꼭 뽑아주세요!!!!"}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"인하대학교","dept":"이차전지융합학과","jeonhyeong":"학생부종합(미래인재전형)","method":"면접관 2명, 면접자 1명","notes":"다른 학과들과 함께 대기함, 대기시간 최대 50분 정도, 6~7분 면접, 면접실 밖에서 타이머를 잰 후 알람 소리가 들리면 면접이 끝남","qa":[{"q":"지원 동기랑 이를 위해 3년 동안 뭐 했는지 간략히","a":""},{"q":"미적분 세특 내용 중 인공지능 학습과 미적분 활용 내용이 있는데 설명","a":""},{"q":"화학 2에서 모둠 내에서 역할을 분배했다고 돼있는데 무슨 역할을 했는지","a":""},{"q":"화학1 세특 내용 중 볼타 전지, 다니엘 전지의 차이와, 염다리를 사용한다고 되어있는데 염다리를 왜 사용하는지 설명","a":""},{"q":"지구과학1 세특 내용에 해양점액현상 내용이 있는데 설명","a":""},{"q":"동아리 시간에 수소연료전지 실험을 했는데 물분해 어떻게 했는지 설명","a":""},{"q":"행특에 기계공학 희망한다고 되어 있는데 왜 이렇게 적혀있는지 설명","a":""},{"q":"확률과 통계 이수를 안 했는데 왜 안 했는지 설명","a":""}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"인하대학교","dept":"전기전자공학부","jeonhyeong":"학생부종합(미래인재전형)","method":"선발 인원이 많아서 그런지 면접고사실이 5개정도 있었고 면접관 두 분이서 번갈아가며 질문을 함.","notes":"모든 질문이 생기부에서만 나와서 생기부 공부를 열심히 하고 가면 잘 볼 것 같습니다.","qa":[{"q":"생활기록부에 전류, 전압을 측정해 본 경험이 있던데 어떤 장치로 전류를 측정했나요","a":"멀티미터기와 전류계로 전압과 전류를 측정했습니다."},{"q":"미세먼지와 지구온난화 등 환경에도 관심을 가지고 활동한 것 같은데 소개할 내용을 말해 주세요","a":"미세먼지의 종류와 미세먼지의 발생원인 등을 이야기함."},{"q":"초기하분포와 이항분포를 조사했다고 되어있는데 설명해 주세요","a":"초기하분포는 비복원, 이항분포는 복원추출을 한다고 함."},{"q":"반도체 관련 도서 중 가장 인상깊었던 책은?","a":"‘반도체 넥스트 시나리오’ 3진법 반도체에 대해 이야기함."},{"q":"볼록거울이 도로에서 사용되는 원리를 말해보세요","a":"대답 못함"},{"q":"페로브스카이트 태양전지에 대해 설명해보세요","a":"페로브스카이트 구조를 가진 원소들을 흡수층으로 사용하는 태양전지이다."}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"인하대학교","dept":"컴퓨터공학과","jeonhyeong":"학생부종합(미래인재전형)","method":"면접관 2명과 함께 생기부 기반의 면접이 진행됩니다.(약 5분~7분)","notes":"전자시계, 이어플러그 등 전자제품 소지시 전원을 끄고 제공하는 팩에 넣어 두세요.1차 합격 발표 때 출력 가능한 수험표를 들고 가셔야 합니다. 수능 수험표는 불가능합니다.","qa":[{"q":"자기 소개와 지원동기 부탁드립니다.","a":"저는 인하대학교 컴퓨터공학과에 지원한 R10370번이고 고등학교 때 코딩동아리에 참여하면서 간단한 어플들을 만들고 개발 공부도 하면서 재미를 느끼게 되었고, 특히 컴퓨터 공학 쪽에 관심이 깊어졌습니다. 대학교에 와서 좀 더 체계적으로 기술과 이론을 깊게 배우고 싶어서 학교에 지원하게 되었습니다."},{"q":"언리얼엔진에서 게임개발에 쓰이는 함수를 공부하셨다는데 어떤 함수들을 공부하셨습니까?","a":"블루프린트에서 Actor라는 클래스에서 get player controller,event begin play식인 유저들이 게임에 영향을 미칠수 있는 함수들이 있고, character라는 클래스에서 speed,rough등 사물이나 인물에 이동이나 동작을 정할 수 있습니다."},{"q":"프로그래밍 최적화와 미적분이 연관이 있다고 하는데 어떠한 부분에서 연관성이 있다고 생각하십니까?","a":"프로그래밍을 할 때 복잡한 부분을 연산할 때 CPU 사용률이 오르게 되는데 이때 그래프의 순간 변화률을 보고 코드의 최적화할 부분을 찾을 수 있기 때문에 미적분이 연관성이 있다고 생각합니다."},{"q":"AI와 확률과 통계의 연관성이 있다고 했는데 어떠한 부분이 연관성이 있는거 같습니까?","a":"AI는 데이터를 기반으로 작동하며, 확률과 통계는 데이터의 불확실성을 다루고 패턴을 이해하는 데 핵심적인 도구를 제공합니다. 확률과 통계에 대한 깊은 이해는 AI 알고리즘 설계와 응용에 필수적입니다."},{"q":"마지막으로 1학년때 급훈으로 “오히려 좋아”라는 교훈을 만드셨는데 어떤 의미를 가지고 만드셨나요?","a":"사람은 살다 보면 좋은 경험이든 나쁜 경험이든 하게되는데 결국에는 그러한 경험들을 바탕으로 더 성장할 수 있다고 생각하기 때문에 “오히려 좋아“ 라고 정하게 되었습니다."}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"인하대학교","dept":"항공우주공학과","jeonhyeong":"학생부종합(미래인재전형)","method":"면접관 2명, 수험생 1명의 개별면접/ 10분 내외","notes":"타이머 울려도 무시하고 질문 계속 하심. (10분 좀 넘어도 계속 하심. 12분? 13분? 정도 한 듯) 꼬리 질문 많았음.인공지능은 진로랑 관련된 부분이 아닌데도 질문을 많이 하심. 생기부에 특이한 활동이 있다면 그 부분을 자세히 알아둬야 할 것 같음.","qa":[{"q":"우리 학교에 왜 지원했나요?","a":"저는 고등학교 1학년 때 누리호의 엔진 시험 영상을 보고 우주발사체에 관심을 갖게 되었습니다. 인하대학교는 항공우주캠퍼스를 따로 지을 만큼 항공우주공학에 많은 지원을 해 주는 것 같았고, 로켓으로 유명한 인하대에서 제 관심사인 우주발사체에 대해 깊이 있게 배우고 싶어 지원하게 되었습니다."},{"q":"연소불안정이 고등학생이 하긴 어려운 주제인데 어떻게 탐구했나요?","a":"2학년 때 누리호의 엔진에 대해 탐구하다가 액체 엔진의 연소불안정에 대해 알게 되어 탐구했습니다. 인터넷 검색이나 일반 도서로는 정보를 찾는 데 한계가 있어서 추진공학회지에 실린 글을 참고했습니다."},{"q":"그럼 연소불안정에 대해서 아는 대로 설명해보세요.","a":"연소불안정은 연소 도중 연소실의 압력과 유동이 급격하게 요동치며 안정적인 연소를 방해하는 현상입니다. 연소실 내부의 열 방출 진동과 소리 진동이 서로 간섭하며 커지는 게 발생 원인입니다."},{"q":"연소불안정이 발생하면 불이 꺼지는 건가요?","a":"아닙니다. 원래 로켓 엔진은 일정한 추력을 내야 하는데 연소불안정이 발생하면 추력이 일정하지 않고 울렁울렁 거리면서 발생하게 됩니다. (요동친다는 단어가 생각이 안 나서 이렇게 표현함...)"},{"q":"우주쓰레기에 대해 탐구했는데 어떤 내용이었나요?","a":"환경 시간에 우주쓰레기에 대해 배우고 흥미를 가지게 되어서 탐구했습니다. 우주궤도상 위성서비스를 이용해 궤도상 위성에 급유를 해주면 위성의 수명을 늘려서 우주쓰레기를 줄일 수 있다는 내용이었습니다."},{"q":"우리가 보통 생각하는 우주쓰레기는 공중에 멈춰있지 않나요?","a":"제가 알기로는 궤도를 도는 인공위성 같은 것에서 떨어져나온 조각들도 우주쓰레기이기 때문에 우주쓰레기도 궤도를 돌고 있다고 알고 있습니다."},{"q":"그럼 그 쓰레기에는 어떤 힘이 작용할까요? 일단 중력이 작용하겠죠?","a":"네. 지구의 중력이 작용하고, 처음 가해졌던 지구 밖으로 나가려는 힘도 동시에 작용하는데 이 힘 두개가 평형을 이루어서 날아가지도 떨어지지도 않게 됩니다."},{"q":"그런 경우에 어떤 궤도로 돌까요?","a":"원형 궤도로 돌 것 같습니다."},{"q":"(기억 잘 안나는데 생기부에 수업 참여가 좋다? 태도가 좋다? 고 쓰여 있는데 어떻게 수업을 들었길래 이런 내용이 쓰였냐는 질문이었음)","a":"기하가 제가 좋아하는 과목이었고, 앞자리에 앉아서 선생님을 계속 바라보고 수업에 열심히 참여했기 때문에 그렇게 써 주신 것 같습니다."},{"q":"종이접기로 이차곡선을 만들었다고 했는데 설명해주세요.","a":"종이 중앙에 점을 찍고, 종이의 아랫면이 그 점을 지나가도록 접으면 선들이 이렇게(말로 설명 못해서 팔로 모양을 표현함) 생기는데, 그 선들에 모두 접하도록 곡선을 그리면 포물선을 그릴 수 있습니다."},{"q":"인공지능 시간에 은하를 분류하는 활동을 했는데 이 활동을 왜 했고 어떻게 했는지 설명해보세요.","a":"지구과학 시간에 은하에 대해 배웠는데 마침 인공지능 시간에 뭔가 분류하는 프로그램을 만들어 보라고 하셔서, 은하를 형태에 따라 분류하면 좋을 것 같다고 생각했습니다. 그래서 서포트 벡터 머신을 이용해 은하를 타원, 나선, 막대 나선으로 분류했습니다."},{"q":"굳이 서포트 벡터 머신을 사용한 이유는?","a":"여러 가지 방법을 사용했는데 서포트 벡터 머신이 가장 성능이 좋았습니다. (이 답변 하자마자 타이머 울렸던 것 같음)"},{"q":"다른 방법으로는 뭐 썼어요?","a":"랜덤 포레스트랑... 이름이 잘 기억이 안 납니다."},{"q":"(잘 기억 안 나는데 인공지능이랑 기계학습 이런 내용이 좀 많은데 컴퓨터공학과 안가냐는 느낌의 질문)","a":"저는 1학년 때부터 로켓이 너무 좋았기 때문에 컴퓨터공학과는 안 썼습니다."},{"q":"마지막으로 하고 싶은 말 있으면 해 보세요.","a":"저는 고등학교 3년동안 우주공학에 대해 탐구하면서 탐구심을 키웠고, 학생회 활동을 하며 협동과 소통 능력도 키웠습니다. 제가 인하대학교의 학생이 된다면 이런 능력을 바탕으로 우리나라 항공우주산업을 이끌어나가는 인재가 되도록 노력하겠습니다. 감사합니다."}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"인하대학교","dept":"미디어커뮤니케이션","jeonhyeong":"인하미래인재","method":"서류 확인 면접(생활기록부) 1인당 8분, 앞 순서 면접자가 면접을 보는 동안 다음번 면접자가 면접실 앞에서 / 대기.","notes":"가족 관계, 지역, 부모님 등 인적 사항 발설 금지","qa":[{"q":"우리 학교에 입학하고 하고 싶은 활동이 무엇인가요?","a":"면접 준비를 하면서 인하대학교 미디어커뮤니케이션학과의 다양한 커리큘럼을 보았습니다. 그중에 학과 내 동아리가 가장 인상 깊었습니다. 저는 인하대학교 미디어커뮤니케이션학과에 들어오게 된다면 동아리에 들어가 선배, 동기, 후배들과 직접 영상을 제작하여 실전 경험을 쌓고 싶습니다."},{"q":"많이 긴장되시죠?","a":"네."},{"q":"2학년 때 영어 동아리에서 가장 기억에 남는 활동이 무엇인가요?","a":"영어 동아리에서 난민에 대한 책을 읽었습니다. 책을 읽을 때 해석하기 어려운 단어나 문장을 동아리원들과 서로 도움을 주어 어려움을 극복했습니다. 그리고 이후 영상 제작에 관심이 있는 친구들을 모아 짧게 난민에 대한 영상을 제작하였습니다."},{"q":"OTT의 약자와 OTT쿼터제 뜻이 무엇인가요?","a":"OTT쿼터제란 해외 OTT서비스가 국내에 들어올 때 일정비율 이상 자국의 콘텐츠가 있어애 한다는 법입니다. OTT쿼터제의 장점은 자국의 콘텐츠를 보호할 수 있다는 점이고, 단점은 국가가 민간기업의 법적제재를 가함으로써 자유 시장 체제에 어긋난다는 것입니다. OTT의 약자는 잘 모르겠습니다."},{"q":"NIE활동을 했다고 쓰여있는데 약자가 뭐고, 무슨 활동인지 설명해 주세요.","a":"NIE활동은 선생님께서 주신 뉴스 기사를 요약하고, 기사에 대한 제 생각을 적는 활동입니다.특이점교과세특에서 질문을 하나도 안함.합/불 분석불합격아쉬운 점면접을 볼 때 너무 긴장해서 준비한 답변을 제대로 하지 못했음."}],"naesin":"2.78","result":"불합격","resultNote":"후보 29 순위","suneung":"최저기준없음","type":"일괄합산( ) 단계형( O ) 【1단계】 성적70%, 생기부30% 【2단계】 생기부기반","src":"경상남도교육청 「2026 대입 면접 전략 자료집(학생부 기반)」","year":"2025학년도"},{"univ":"인하대학교","dept":"사회교육과","jeonhyeong":"학생부종합/인하미래인재","method":"학생부면접 대기실에서 면접 준비. 앞 순서 지원자가 면접장에 들어가면 대기실에서 면접실 / 앞 의자로 이동해서 바구니에 짐을 두고 대기. 8-10분간 면접.","notes":"수험표/신분증 필수 지참. 전자기기 전원 종료 후 개인 보관.","qa":[{"q":"자기소개 해보세요.","a":"저는 1학년 때 사회문제연구부 동아리 가입하여 다양한 주제로 토론하며 사회문제에 관심을 가지고 사회적 시각을 넓혀갔습니다. 뉴스나 자료의 정보를 그냥 수용하는 것이 아니라 제가 직접 찾아내는 즐거움을 경험하였습니다. 저의 이런 경험을 통해 다음 세대의 학생들이 교육현장에서 제가 느낀 즐거움을 경험하면 좋겠다고 생각하였습니다. 멘토멘티 활동을 하며 교사가 되어 학생들에게 전달할 수 있겠다고 생각하였습니다. 이 점이 제가 사회교사를 꿈꾸게 된 가장 큰 계기입니다."},{"q":"지원자가 멘토멘티 활동을 3년동안 하였는데, 자신만의 노하우가 있다면 무엇이 있을까요?","a":"제가 멘토멘티 활동을 수학, 영어, 사회 과목으로 총 세 명의 친구와 멘토멘티 활동을 하였습니다. 세 명의 친구와 멘토링 활동을 하면서 느낀 하나의 공통점이 있습니다. 그것은 바로 예시를 들어 설명하는 것이 학습자의 이해를 돕는다는 것입니다. 수학 과목을 예시로 들면, 학습자가 최단거리 문제를 어려워한다는 것을 인식하였습니다. 학습자의 흥미를 불러일으키기 위해 ‘학교에서 집까지 어떤 길로 가는 것이 가장 빠를까?’라는 상황을 예시를 들어 설명하였고, 학습자가 잘 이해할 수 있었고 문제를 푸는 데도 어려움이 없었습니다."},{"q":"2학년 때 사회문화 시간에 한 탐구활동 기억이 나나요? 지원자가 학습 결손을 주제로 ‘학생이 교사와의 관계가 우호적일수록 성적이 높을 것이다.’라는 가설을 세웠는데, 개념의 조작적 정의를 어떻게 했는지 알 수 있을까요?","a":"저는 학습결손의 요인이 무엇인지 조사를 하는 과정에서 한 교장선생님께서 학습부진아의 주요원인 중 하나가 교사와의 관계라는 자료를 접하였습니다. 이후 ‘교사와의 관계가 우호적일수록 학생의 성적이 높을 것이다’라는 가설을 세웠습니다. ‘교사와의 관계’는 학생과 교사와의 대화 빈도와 대화 시간으로 조작적 정의하였고, 학생의 성적은 학교 기말성적과 모의고사 성적으로 조작적 정의하였습니다."},{"q":"‘교사와의 관계‘를 대화 빈도와 시간으로 조작적 정의하였다고요?","a":"네. 한 교장선생님께서 하신 말씀에서 대화 경험도 학습부진아의 주요 원인으로 언급하셨습니다. 그래서 교사와의 관계를 교사와의 대화 빈도와 대화 시간으로 조작적 정의하였습니다."},{"q":"3년 동안 동아리를 사회문제연구부에서 활동하였는데 가장 크게 얻은 것은 무엇인가요?","a":"저는 넓은 사회적 시각을 얻었습니다. 동아리 활동 이전에는 사회문제에 대해 많이 알지 못했는데 동아리 활동을 하면서 다양한 사회문제에 관심을 가졌고, 찬반 토론을 하면서 윤리적 관점에서는 어떨까, 경제적 관점에서는 어떨까 생각하면서 사회적 시각을 넓힐 수 있었습니다."},{"q":"그러면 이 질문은 넘어가서, 타일러의 교육모형에 대해서 조사했던데 타일러와 반대되는 교육학자에 대해서 알고 있나요?","a":"죄송합니다. 그 부분은 숙지하지 못했습니다."},{"q":"네, 그러면 타일러는 교육이 뭐라고 하던가요?","a":"타일러 모형은 체계적인 교육과정을 꾸려 학습목표를 이룰 수 있다고 하였습니다. 저는 타일러를 조사하면서 학교목표를 세울 때, 학교 안뿐만 아니라 학교 밖의 사회의 흐름과 관련하여 실질적인 교육 목표를 제시하는 것이 중요하다고 한 점이 흥미롭게 다가왔습니다. 문열고 들어가면 교수 두 분이 긴 책상에 앉아계시고 노트북을 보고 계심. 책상 중간에는 녹화?를 할려고 무언가를 둔 거 같음. 들어가면 교수님께서 “편한 자세로 앉아주시면 됩니다. 준비됐나요? 그럼 시작하겠습니다”라고 말하시는 순간 녹화랑 타이머를 시작하특이사항심. (녹화..인지는 사실 잘모르는데 뭔가를 누르긴 하심) 두 분이서 번갈아서 질문하심. 생각보다 딱딱한 분위기는 아니었음. 시간이 다 되면 타이머가 울리고 답변하고 있던 질문이 마지막 질문이 됨. 중간에 끊지는 않음. 합/불 분석면접 시간내에 2-3개 활동에 관해서만 질문할 수 있을 정도로 굉장히 시간이 짧음. 시간이 짧다보니 질문 하나하나가 소중함. 그렇기 때문에 처음 자기소개, 지원동기에서부터 잘 준비해야한다고 느낌. 자기소개에서 언급했던 멘토멘티와 동아리에 대해 몇 번의 질문을 하신 것을 보면 자기소개에서 자신의 주요 활동을 언급하면 그 활동에 더 질문이 들어올 수 있아쉬운 점으니, 주요 활동과 관련하여 더 구체적이고 더 깊이 있는 내용과 활동으로 답변을 뻗어나가면 자신에게 유리한 면접을 만들어 낼 수 있을듯. 예상했던 질문에 3개 정도 있어서 답변을 하긴 했지만, 나의 수학 역량과 리더십 등 나의 장점을 나타내지 못해서 매우 아쉬움. 확실히 교육과 관련하여 탐구나 조사가 부족했음."}],"naesin":"2.34","result":"불합격","resultNote":"후보순위","suneung":"최저기준없음","type":"일괄합산( ) 단계형( O ) 【1단계】 서류 100 (3.5배수) 【2단계】 서류 70 + 면접 30","src":"경상남도교육청 「2026 대입 면접 전략 자료집(학생부 기반)」","year":"2025학년도"},{"univ":"인하대학교","dept":"아동심리학과","jeonhyeong":"학생부종합/인하미래인재","method":"생기부 기반 면접","notes":"","qa":[{"q":"1학년때 뚜렛증후군 아이를 만난 경험에 대해 작성하였던데 그것에 대해 구체적으로 얘기해주세요","a":"저랑 친한 언니의 동생이 뚜렛증후군을 가진 친구였습니다. 제가 친구들과 놀고있으면 계속 주변을 맴돌고 우리의 물건을 만지는 등 우리의 관심을 끌려고 하였습니다. 저랑 친구들은 일부러 피해다니기도 하고 모른척하기도 하였습니다. 하지만 장애 이해 교육 이후 우리와 같은 사람인데 표현방법은 조금 다르다는 것을 알게 되었습니다. 그 뒤로 그 아이가 보이면 먼저 다가가서 말을 걸기도 하고 같이 놀려고 하였습니다."},{"q":"그때 같이 놀던 친구들의 반응은 어떠하였나요?","a":"처음에 제 친구들은 왜 우리가 같이 놀아야하냐 우리들끼리 놀자라는 반응이였습니다. 그때 저는 너무 편견을 가지지말고 같이 놀아보자 우리들끼리 놀 기회는 많지 않으니까 이 친구랑 같이 놀다가 가면 그때 우리끼리 놀자라고 하며 설득시킬려고 하였습니다."},{"q":"수학 점수가 높던데 왜 이공계열을 선택하지 않고 인문계열을 선택하였는지","a":"저는 수학을 혼자서 꾸준히 여러 문제집을 풀고 하다 보니 좋은 성적을 받을 수 있었습니다. 하지만 다양한 언어에도 흥미를 느꼈고 사람들에 대한 관심도 많고 심리라는 분야에 관심이 있었기에 인문계열을 선택하였습니다."},{"q":"어머니의 애착유형이 아동의 성장에 영향을 미친다는 내용을 탐구하였는데 그거에 대해 설명해 주세요.","a":"저는 아이들의 성장에 엄마라는 존재는 어떠한 영향을 미칠지 궁금해하던 중 어머니의 애착유형과 관련된 논문을 찾게 되어 이를 주제로 탐구하게 되었습니다. 어머니의 행동이 아이들에게 영향을 미친다는 것은 예상하였지만 어머니가 엄마라는 역할에 대한 만족도가 높을수록 그 아이도 긍정적이게 성장할 수 있다는 것을 새롭게 알게되었습니다."},{"q":"친구들과 있었던 갈등 상황과 어떻게 해결했는지 얘기해 주세요.","a":"체육대회를 준비하는 과정에서 반 애들과 갈등을 겪었습니다. 출전할 애들을 선정할때 학생들 간의 의견대립이 있었고 연습하는 과정에서 실수를 하는 친구에게 질타하는 경우도 있었습니다. 그때 친구들 각각의 얘기를 들어보고 체육부장한테 가서 의견을 맞춰나가며 서로 상한 마음이 있다면 그걸 풀어서 체육 대회를 준비할 수 있도록 노력하였습니다."},{"q":"개인적인 친구들 사이에서의 갈등은 없었나요 있었다면 그 상황과 어떻게 해결하였는지 얘기해주세요","a":"친구들 무리가 홀수인 경우에 갈등을 자주 겪었습니다. 친구가 셋인 경우 두명이 친하게 지내다보면 한 사람이 서운해하는 상황이 많았습니다. 그때 서운해하는 친구에게 우리는 널 따돌리거나 할 의도가 없었다고 설명해주고 우리가 서운하게 했다면 미안하다고 얘기하며 그 친구의 마음을 풀어줄려고 노력하였습니다.특이점편안한 분위기였음합/불 분석아쉬운 점"}],"naesin":"","result":"최초합격","resultNote":"후보순위","suneung":"최저기준없음","type":"일괄합산( ) 단계형(O) 【1단계】 (3.5배수)서류100 【2단계】 면접 30 + 서류70","src":"경상남도교육청 「2026 대입 면접 전략 자료집(학생부 기반)」","year":"2025학년도"},{"univ":"인하대학교","dept":"컴퓨터공학과","jeonhyeong":"학생부종합/인하미래인재","method":"서류 기반 면접 / 단계별 전형","notes":"면접관 2 대 면접자 1, 10분","qa":[{"q":"자기소개 해보세요.","a":"저는 게임 개발자의 꿈을 가지고 인하대학교 컴퓨터 공학과에 지원하였습니다. 저는 고등학교 1, 2학년 동아리 시간 때 게임 개발 및 총괄의 경험이 있었습니다. 이 경험을 바탕으로 게임 개발자라는 꿈을 가졌으며, 인하대학교 컴퓨터공학과에서 리더인 게임 개발자로서 배워야할 것들을 배워나가고 싶습니다."},{"q":"평균변화율과 순간변화율의 차이에 대해 말씀해 보세요.","a":"평균변화율은 한 점에서 다른 점 간을 이은 선의 기울기이며, 순간 변화율은 한 점에서의 기울기를 말합니다."},{"q":"진로현장체험활동으로 과학관에서 모바일 게임을 만든 활동에 대해 무엇을 배웠는지 느낀점은 있는지 설명해 보세요.","a":"구글에서 모바일 게임 개발을 체험하는 프로그램을 사용하는 활동을 했습니다. 버튼을 누르면 점프하고 아이템을 먹으면 점수가 오르는 등의 활동을 하였으며 추가로 저는 버튼을 누를때마다 랜덤으로 능력치가 바뀌는 것도 만들었습니다. 다만 이 활동에서 아쉬운 점이 있었는데요, 이에 대해 말씀드려도 될까요? (네 말씀해보세요) 블럭 코딩과 굉장히 간단히 C 언어를 사용하며 했어서 제대로 게임 개발을 못 했다는게 아쉬웠습니다. 이 때문에 활동 후 집에 와서는 모바일 게임 개발에 관심이 생겨 관련 강의를 찾아보고, 이를 바탕으로 유니티로 2D 모바일 점프맵 게임을 개발하기도 하였습니다."},{"q":"진로활동에서 몬테 카를로 트리 서치 알고리즘을 경로탐색에 사용하셨다는데, 이에 대해 설명해 주시겠어요?","a":"게임 ai에 관한 책을 읽고 경로 탐색 ai에 A스타 알고리즘이 사용된다는 것을 알게 되었습니다. 간단히 설명드리면 매쉬로 이뤄진 맵에서 첫 꼭짓점부터 끝 꼭짓점까지 모든 경로를 한 번씩 가봄으로써 최적의 경로를 찾는 알고리즘인데요, 여기서 저는 확률과 통계 시간에 배웠던 몬테 카를로 트리 서치 알고리즘을 여기에 사용할 수 없을까라는 궁금증을 가지고 탐구를 시작하게 되었습니다. 몬테 카를로 트리 서치 알고리즘은 바둑이나 체스와 같이 매우 경우의 수가 많은 게임에서 임의의 수로만 전개를 하면서 최적의 수를 찾는 알고리즘인데요, 이것이 기존의 A스타 알고리즘보다 효율적으로 활용할 수 있으려면 경우의 수가 굉장히 많고 파라미터가 굉장히 많은 매우 복잡한 경로여야 한다고 생각하였습니다. 비록 이를 실제로 적용해보진 못했지만, 인하대학교 컴퓨터공학과에서 알고리즘에 대한 수업을 듣고 몬테카를로트리서치 알고리즘을 구현할 수 있게 된다면 이를 유니티의 경로탐색에 A스타 알고리즘 대신에 사용하여 실제로 더 효율적으로 작동할 수 있는지 탐구해보고 싶습니다."},{"q":"3년간 임원생활을 하면서 인상 깊었던 점 말씀해보세요","a":"제가 3년간 임원생활을 하면서 정말 많은 활동들을 하였지만, 가장 인상 깊었던 점은 가장 어려웠던 점에서 얻은 것입니다. 이에 대해 말씀드리도록 하겠습니다. (면접관님들 끄덕 끄덕) 저는 임원생활을 3년간 하면서 가장 중요하게 생각한 것이 학습 분위기 조성입니다. 이를 위해 수업시간 종이 쳐도 떠드는 아이들이 있으면 조용히 시키는 등의 활동을 하였습니다. 다만 여기서 많은 반발이 있었습니다. 저는 여기서 단순히 규율만을 내세우기만 했습니다. 하지만 나중에 돌아보니 규율만 내세우는 것이 문제라는 것을..(타이머 울림)계속 말씀드려도 될까요? (10초 안에 짧게 해주세요) 넵 답변드리겠습니다. 여기서 깨달은 것이 리더로서 규율만을 내세우는 것보다 신뢰관계를 바탕으로 이끄는 것이 중요하다는 것을 깨닫게 되었습니다.특이점굉장히 말씀이 느리고 부드러우심, 학생에 대한 배려가 크게 느껴짐합/불 분석?아쉬운 점인사할 때 허리 숙인 뒤 “안녕하십니까” 빼먹고 바로 가번호 R뭐뭐뭐뭐뭐 입니다라고 함."}],"naesin":"1.81","result":"","resultNote":"후보순위","suneung":"최저기준없음","type":"일괄합산( ) 단계형(O ) 【1단계】 서류 100% 【2단계】 면접 30% 서류 70%","src":"경상남도교육청 「2026 대입 면접 전략 자료집(학생부 기반)」","year":"2025학년도"},{"univ":"인하대학교","dept":"디자인테크놀로지학과","jeonhyeong":"학생부종합(인하미래인재)","method":"자기소개 → 학생부 질문 / 면접시간 8분 / 면접위원 2명","notes":"친절하십니다. · 모의 면접 많이 하면 할수록 좋습니다. · 생기부 면접 전에 최소 6번은 정독하는게 편합니다. · 마음 편하게 가지고 면접을 가는 연습을 하면 더 편하고 당황하지 않을 수 있습니다. · 정말 솔직히 말하자면 학교에서 면접 관련해서 해준다고 하는 활동들에 모두 참여 하시는게 편하고 안정감을 기르는데 도움이 매우 많이 됩니다.","qa":[{"q":"자기소개 해주세요. (입학사정관)","a":"안녕하십니까. 저는 어릴 때부터 컴퓨터와 게임을 좋아하여 게임개발자의 꿈을 가지고 지원하게 되었습니다. 게임개발자가 되기 위해서 저는 개발 분야와 컴퓨터에 대한 기초를 다지는 활동들을 하였습니다. 미래 사회를 창조적으로 선도할 수 게임 개발자로서 성장하고자 저의 과학적 기초와 컴퓨팅 사고를 기반으로 저의 장점인 도전정신과 끈기와 함께 제 꿈을 이루고 싶습니다."},{"q":"건축에 관한 내용도 있는데요 게임개발자로 전향하게된 계기가 있나요? (입학사정관)","a":"1학년 때 정보 시간에 처음으로 코딩에 대해 배우고 코딩을 직접하며 제가 코딩을 좋아하고 흥미를 느낀다는 사실을 알게 되어 개발자의 꿈을 가지게 되었습니다. 게임개발자로 정하게 된 이유는 제가 건축에 흥미를 느끼게 된 계기가 게임이나 영화 속에 등장하는 멋진 건축물들 때문인데 게임개발자가 된다면 이런 매체들 속의 건축물 뿐만 아니라 세계를 만들 수 있다고 생각했습니다."},{"q":"그럼 직접 게임을 제작해본 경험이 있나요? (입학사정관)","a":"3학년 전공트래킹 활동에서 혼자서 게임을 제작해본 경험이 있습니다. 유니티 3D엔진을 이용하여 쿼터뷰 액션 게임을 제작하였습니다. 스테이지 형식의 게임으로 각 스테이지에 들어가기 전에 장비를 구입하고 정비하는 거점형식도 구현하였습니다. 이 활동을 하면서 게임을 제작하는법을 배울 수 있었습니다."},{"q":"디자인적 사고를 따로 생각해본적 있나요? (교수님)","a":"잠시 생각할 시간을 주시겠습니까? -> (5초 뒤에 교수님) 이걸 가지고 점수에 반영을 할건 아니고요. 학생이 생각해봤는지 궁금해서 물어봤어요."},{"q":"그럼 디자인적 사고를 이용해 활동해본 경험이 있을까요?(교수님)","a":"2학년 정보 과학 시간에 친구와 같이 아케이드 게임과 게임기를 제작하는 활동을 했었습니다. 그때 내부 하드웨어와 조작 그리고 사용자가 사용함에 있어 3가지를 모두 고려해 제가 생각한 최고의 디자인으로 설계하여 제작한 경험이 있습니다."},{"q":"시간이 다 되어서 (아마 8분 때에 벨이 울렸음) 마지막으로 하고싶은 말이 있나요.","a":"저는 프로그래밍과 관련된 학과에서는 공동체 역량이 중요하다고 생각합니다. 저는 팀장을 맡아 팀을 이끌거나 팀원들끼리 조화를 이룰수 있도록 하는데 자신이 있습니다. 디자인테크놀로지학과에서 팀을 이뤄 진행하는 활동이나 실습 과정에서 제 능력이 빛을 발할 것으로 생각합니다."}],"src":"세종특별자치시교육청 「보인다! 5.0 면접지도 길라잡이」","year":"2024학년도"},{"univ":"인하대학교","dept":"식품영양학과","jeonhyeong":"학생부종합(인하미래인재)","method":"대기실 → 면접실 앞 대기 → 면접실 / 면접시간 10분 내 / 면접위원 2명","notes":"","qa":[{"q":"친한 친구에게는 냉철한 판단력으로 따끔한 조언도 해주는 어른스러운 면도 있다고 써있는데 어떤 상황에서 이런 면모를 보이셨나요?","a":"반 친구들과 함께 업사이클링 활동을 통한 학교 뒤뜰을 같이 꾸몄는데 이때 추운 날씨에 부반장만 일을 하고 나머지 친구들은 반에서 쉬고 있었습니다. 저는 단합 활동은 모두가 함께 해야 가치가 있다고 생각하였고 따라서 친구들에게 부반장만 일하는 것이 옳지 않다며 친구들에게 따끔한 조언을 해주었습니다."},{"q":"친구들의 반응은 어땠나요? 기분 나빠하는 친구들도 있을 것 같았는데..","a":"대부분의 친구들은 수긍하며 같이 일을 했지만 일부 친구들이 기분 나빠하기도 했습니다. 제가 장난기가 많은 성격이여서 친구들에게 먼저 다가가서 웃으며 장난치며 관계를 회복했습니다."},{"q":"먼저 다가가는 스타일이신가요?","a":"네!"},{"q":"언제 이 학과를 오겠다고 생각했어요?","a":"저는 3학년 1학기 기말고사 끝나고 결정했습니다. (침묵 후 지원 동기 말할 시간인 것 같아서,,,)저는 2학년 때 미생물과 관련한 탐구를 많이 진행하였고, 탐구를 진행하면서 미생물과 식품이 밀접하게 연관되어 있다는 것을 알고 식품 개발을 해보고 싶다고 생각해 진로를 바꾸게 되었고 3학년때 발효와 미생물과 관련된 실험으로 이를 구체화하였습니다. 따라서 저는 식품에 흥미를 느껴 건강하고 맛있는 식품을 개발하는 식품 연구원이 되고 싶습니다!"},{"q":"건강하고 맛있는 식품 생각해둔 거 있어요?","a":"친구들과 함께 건두부를 깔고 그 위에 치즈와 파프리카와 같은 채소를 올려 건강한 피자를 만든 경험이 있는데 이를 더욱 개발하면 좋을 것 같습니다."},{"q":"화법과 작문 시간에 제로슈가에 대해 탐구했는데 주제 선정을 어떻게 하셨나요?","a":"화법과 작문 발표를 준비하면서 뉴스 기사를 찾아보면서 발표 준비 하기 전 주에 WHO가 제로 슈가에 대한 권고지침을 발표했다는 뉴스 기사를 보고 주제를 선정하게 되었습니다."},{"q":"평소에 뉴스 기사를 많이 찾아보는 편이세요?","a":"네!"},{"q":"식탁 위의 과학, 분자요리라는 책을 읽었는데 이 책에서 화학과 관련한 어떤 전공 지식을 배우셨나요?","a":"저는 책을 통해 총 3가지의 식품과 화학의 반응을 배웠습니다. 첫 번째는 물입니다. 물 분자는 수소 결합을 하고 있는 결합수와 수소 결합을 하고 있지 않은 자유수가 있으며 결합수는 미생물이 번식하기에 어렵지만 자유수는 미생물이 결합하기 쉬우므로 식품 개발 시 자유수와 결합수의 비율이 중요합니다. 두 번째는 당질입니다. 당질은 단당류, 이당류, 다당류가 있으며 단당류는 조리에 의해 변하는 입자이므로 바로 먹으면 단맛이 나지 않지만 다당류와 이당류는 바로 단맛을 느낄 수 있습니다. 세 번째는 단백질입니다. 단백질은 우리 몸 속에서 독특한 입체 구조를 가지고 있으므로 육류나 생선을 구우면 단단해지는 현상, 우유와 요구르트를 만드는 과정 모두 단백질 구조 변화에 의한 것입니다."},{"q":"화학을 적용해서 어떤 연구를 해보고싶어요?","a":"화학을 통해서요,,? 아! 저는 발암물질 없는 식품을 개발하고 싶습니다."},{"q":"영양사 선생님과 식단 짜기 활동을 김치나 멸치 조림이 버려진다는 것을 알고 이를 대체하기 위해 식단을 여러 번 교체했다고 되어있는데 어떤 걸로 바꾸셨나요?","a":"학생들과 설문 조사와 대화를 통해 김치나 멸치 조림이 버려진다는 사실을 알고 이를 메밀국수로 바꾸려고 했으나 메밀이 알레르기 반응 식품이라는 사실을 알고 김치는 두부리또로 멸치 조림은 파프리카를 다져 큐브 조각으로 만들어 바꾸어 대체하였습니다."},{"q":"이후 학생들의 반응은 어떤 가요? 좋았나요? 이를 실제로 적용해본거죠?","a":"네! 이후에 따로 설문조사를 하지는 못했지만 학생부 친구들과 대화해 본 결과 친구들이 급식이 더 맛있어졌다고 이야기했습니다."},{"q":"이제부터 이 학과를 4년동안 다닐건데 배우고 싶은 거 있어요?","a":"제가 자극적인 음식을 매우 좋아해서 부모님께서 걱정이 많으십니다. 따라서 저는 조리학 실습을 통해 건강하고 맛있는 식품을 만들고 싶습니다. (타이머 울려서 바로 퇴장)"}],"src":"세종특별자치시교육청 「보인다! 5.0 면접지도 길라잡이」","year":"2024학년도"},{"univ":"인하대학교","dept":"아태물류학과","jeonhyeong":"학생부종합(인하미래인재)","method":"면접시간 7분 / 면접위원 2명","notes":"","qa":[{"q":"확률과 통계 성적이 다른 수학 과목에 비해 좋았던 이유는 무엇인가요?","a":"다른 수학 과목들에 비해 확률과 통계가 관심 영역이었던 마케팅과 관련이 있어 흥미를 갖게 되었고, 3학년 때 진로에 대해 명확히 설정하여 동기부여가 되어 열심히 노력했습니다."},{"q":"고등학교 생활 중 기억에 남는 활동과 느낀점은 무엇인가요?","a":"3학년 동아리 활동 중에 우수 동아리로 선정되어 전교생 앞에서 발표를 한 것이 가장 기억에 남습니다."},{"q":"한국 지리 과목에서 생태 지향 국토 건설에 대한 보고서를 작성하였는데, 자신의 주장은 무엇이었나요?","a":"국토 개발로 인해 동물이 피해받지 않도록 동물들과 함께 살 수 있게 생태 지향적인 국토 건설을 주장했습니다."},{"q":"2학년 때는 영어, 마게팅에 관심이 있었는데, 물류로 바뀌게 된 이유는?","a":"확률과 통계 시간에 수행평가를 하던 중 물류와 유통의 중요성을 알게 되었고, 재화를 필요로 하는 기업이나 개인에게 원활히 제공하는 일을 하고 싶다는 생각이 들었습니다."},{"q":"‘나는 일본의 무역상이다’라는 책을 읽고 기억에 남는 것 하나만 말해주세요.","a":"자신의 목표를 달성하기 위해 끊임없이 연구하고 노력하여 자신이 종사하는 분야에서 최고의 자리에 올라간 저자의 모습을 통해 현실에 안주하고 나태하기 보다 진취적인 도전과 노력을 기울여야겠다고 결심하게 되었습니다."}],"src":"세종특별자치시교육청 「보인다! 5.0 면접지도 길라잡이」","year":"2024학년도"},{"univ":"인하대학교","dept":"영어교육과","jeonhyeong":"학생부종합(인하미래인재)","method":"면접시간 10분 / 면접위원 2명","notes":"대기실 입실 후 원형 테이블에서 다른 학과 친구들과 같이 대기, 테이블 순서대로 한 명씩 입장함. · 데이블이 앞 강당과 멀리 있을수록 대기 시간이 늘어나며, 대기 시간 동안 생기부 다시 확인이 필요. 전자 기기는 사용할 수 없음. · 예상과 달리 압박 면접이 없었으며 생기부 확인용 질문이 많음.","qa":[{"q":"3학년 자율활동 때 영어지기 역할을 하셨는데, 소개했던 영어문장 예시로 몇 가지만 말해주시고 학습계획실천에 대해서도 말해주세요.","a":"저는 ‘better late than never’ 이라는 문장을 소개하면서 공부를 늦게 시작한 친구들도 할 수 있다고, 아직 늦지 않았다고 이야기해주며 공부를 아예 안 한 친구들도 지금이라도 하는 게 낫다는 식으로 동기 부여를 해준 기억이 있습니다. 그리고 친구들과 학습계획을 서로 점검해주고 서로의 계획에 대해 피드백을 주며 공부를 해나갔습니다."},{"q":"예시는 한가지만 든거죠? (더 대답 안하냐는 식으로 다시 기회 주심)","a":"하나 더 있는데, ‘Everyday is not happy day, but everyday has happy moments’입니다. (중간에 버벅댔는데 끄덕이시면서 긴장 풀어주심) 항상 행복한 날일 수는 없지만 모든 날들에 행복한 순간들은 있다는 말로, 힘들어하는 친구들에게 동기부여를 해주었습니다."},{"q":"그럼, 이어지는 질문인데 동기부여를 위해 1학년 동아리 시간에 영어를 배워야 하는 이유에 대해 언급했는데 몇 가지 얘기해주시고 3학년이 된 지금도 그 생각이 유효한지에 대해 말해주세요","a":"네. 저는 사실 친구들이 영어를 시험과목으로만 여기는 것이 되게 안타까워서 영어를 배워야 하는 이유에 대해 조사했었는데, 영어를 배워야 하는 이유 몇 가지 중에 첫 번째로는 삶의 질이 올라가고 인간관계가 넓어진다는 것입니다. 다른 경험을 가지고 있는 다른 나라 사람들을 통해 경험하지 못한 것들을 접하고 다양한 문화를 공유할 수 있다고 생각해서 중요하다고 생각했습니다.그리고 제가 가장 중요하다고 생각했던 이유는, 영어를 배우면 다양한 분야로 나아가도 영어로 된 자료가 많아서 어떤 분야로 나아가든지간에 영어가 필요하다는 것을 알게 되었고, 그래서 영어교육을 한다면 누구에게나 좋은 영향을 주는 사람이 될 수 있지 않을까라는 생각에 영어 교사를 꿈꾸게 된 계기가 되었던 것 같습니다."},{"q":"언어학습에 낮잠이 주는 긍정적인 영향에 대해 보도문 2가지를 작성했다고 하는데 이에 대해서 말해주실 수 있나요?","a":"낮잠이 언어학습에 도움을 주는 효과에 대해 조사했을 때, 먼저 뇌의 활성화를 돕는다는 내용이였는데, 낮잠을 자고 휴식을 취하면 뇌가 활성화 되는 것에 도움이 된다는 것을 작성했고, 2번째로는, 이것도 뇌에 대한 이야기인데, 낮잠을 자는동안 단기기억에서 장기기억으로 저장하는 역할을 한다고 배웠습니다. 사실 밤에 잠을 잘 때 뇌가 장기기억을 저장한다는 것을 알고 있었는데 낮잠을 잘 때도 장기기억으로 저장된다고 하니 그 부분이 언어학습에 도움이 될 것 같다고 생각했습니다. 사실, 언어도 뇌를 거치고 의사소통을 하는 영역이기 때문에 낮잠을 자고 휴식을 취하는 것이 꼭 필요하다고 생각했습니다."},{"q":"영어 수업시간에 배웠던 내용을 문단별로 정리하거나 구조화하고 지문 문단마다 핵심문장분석했다고 하는데 지문을 공부한 방법에 대해 설명해주세요.","a":"네 저는 문장마다 꼼꼼하게 보고 가는 성격인데, 어떨 때는 너무 꼼꼼하게 읽는 게 단점이지만 동시에 장점이라고 생각합니다. 지문을 읽고 문단마다 핵심이 되는 내용을 1~2문장으로 요약해서 옆에 정리해놓고 시험 기간에 정리해둔 문장을 읽고 글의 흐름을 위주로 정리하면서 공부했던 것 같습니다. 사실 전에는 문장을 너무 꼼꼼히 분석하고 넘어가서 효율적이지 않았는데 글의 흐름에 따라 핵심 내용만 정리하니 올해 원점수가 더 잘 나온 것 같습니다."},{"q":"학교 공간 재구조화에 대한 내용이 있는데 학교 공간 획일화와 재구조화에 대해 어떻게 생각하는지와 자료 조사했던 내용을 소개해주세요","a":"저는 학교 공간이 교도소와 같다고 소개했었는데, 좀 극단적으로 표현했지만, 교도소와 학교공간이 닮은 점이 항상 똑같은 환경에서 똑같은 옷을 입고 매일 같은 시간에 정해진 것을 한다는 점이 닮았다고 생각했습니다. 많은 학생들이 네모난 책상과 네모난 의자로 된 교실을 답답해하는 것이 안타깝고 저 역시도 그렇게 생각했습니다. 인지신경학자에 따르면 인간은 자연을 추구하고 곡선을 추구한다고 합니다. 그래서 네모난 책상과 네모난 의자가 아닌 곡선형의 다양한 책상과 수업기구를 마련해야 한다고 생각했습니다. 그래야 아이들이 학교에 주인의식을 가지게 되어서 적극적으로 수업에 참여할 수 있을 것이라고 생각합니다."},{"q":"3학년 진로활동에 교수매체 개발에 관심을 보였는데 멀티미디어 활용 영어교육 연구 동향 분석을 통해 어떤 교수매체를 개발하고 싶은지 말해주세요","a":"제가 디지털 활용 교수매체 개발에 대해 조사하면서 4차산업혁명시대에 맞는 인재를 기르기 위해서는 창의력과, 비판적인 사고력과 다문화..그니까 다양한 문화에 대한 이해 능력이 필요하다고 해서 이런 미래의 인재상을 위한 교수매체 제작을 해야겠다고 생각했습니다. 그래서 영어와 다른 지식을 결합해서 창의성을 높이고 사고력과 다양한 문화에 대한 이해를 할 수 있게 하고 싶다고 생각했습니다. 그리고 아까 미디어 활용 교육이라고 하셔서 덧붙이자면, 메타버스를 활용한 교수매체를 제작하고 싶습니다. 전에 수업 시간에 메타버스는 현실 세계와 가상세계의 벽을 허무는 기술이라고 배웠습니다. 메타버스 기술로 가상의 캐릭터를 제작해서, 아이들이 귀여운 캐릭터를 좋아하고 저도 그런 캐릭터를 좋아하기 때문에, 그냥 캐릭터가 아닌 수업 목적에 맞는 캐릭터를 제작해서 아이들이 관심을 보이고 적극적으로 수업에 참여할 수 있게 하는 교수매체를 만들어서 융복합적 학습환경을 마련하고 싶다고 생각했습니다."}],"src":"세종특별자치시교육청 「보인다! 5.0 면접지도 길라잡이」","year":"2024학년도"},{"univ":"인하대학교","dept":"항공우주공학과","jeonhyeong":"학생부종합(인하미래인재)","method":"대기실입실(과별로 앉아서 대기) / 면접시간 10분이내 / 면접위원 2명","notes":"학생부 기반 면접이기에 어렵지 않은 난이도의 가벼운 질문들이 주로 출제 · 처음에 너무 긴장하면 편안한 분위기를 조성해 주시니, 지나치게 긴장하지 않아도 된다. 조금 횡설수설하더라도 면접관 분들이 알아 들어 주시니 문장에 너무 집착하지 않아도 괜찮다.","qa":[{"q":"2학년 때 동아리 활동에 대해 설명해 줄 수 있나요?","a":"질산칼륨과 솔비톨을 이용해 고체연료 로켓을 만들었습니다. 설계팀, 연료팀, 3D 모델링 팀으로 나누어 진행했고요. 3D 모델링을 통해 엔진 마운팅을 하고, 연료는 처음 비율이 26:72, 총 10명으로 진행했고, 물을 넣어 진행했지만 잘 되지 않아 연료의 비율을 바꾸고 물을 넣지 않았습니다. 총 3번의 발사를 진행했는데 마지막에는 노즐 마운팅 부분이 바뀌어서 아쉽게 실패했고, 나버지는 연료..(시간문제로 잘림)"},{"q":"동아리 때 추력방정식을 이용했다고 써 있는데, 어떻게 한건지 말해 줄 수 있나요?","a":"저희가 직접 이용했다기 보다는 추력 방정식이라는 이론에 대해 공부했고, 나머지는 SRM이라는 엑셀 시트에 값을 대입해 발사 준비를 했습니다."},{"q":"그러면 로켓이 쏘아올리면 포물선 운동을 할 텐데 왜 포물선을 그리며 운동 할까요?","a":"어.. 아무래도 중력의 영향을 받는 비스듬히 쏘아올린 물체니까 포물선을 그리며 떨어지겠죠..?(제대로 대답하지 못함)"},{"q":"UAM에 대해 써있는데 실현가능성이 있다고 생각하나요?","a":"솔직히 아직까지는 파일럿 없는 자율 비행에 대한 사람들의 거부감, 소음문데 증 해결해야할 문제가 많아서 오래 걸릴 것 같아요. (이 부분도 시간 문제로 중간에 잘림)"},{"q":"음...네 혹시 마지막으로 하고 싶은 말 있나요?","a":"얼마전에 항공 우주 캠프 건설했다고 들었는데, 꼭 거기에서 공부하고 싶습니다. 뽑아주셔서 학교에서 공부하고 싶습니다."}],"src":"세종특별자치시교육청 「보인다! 5.0 면접지도 길라잡이」","year":"2024학년도"},{"univ":"인하대학교","dept":"해양과학과","jeonhyeong":"학생부종합(인하미래인재)","method":"생기부 기반 면접, 1시간 단위로 대기조 나눔, 5분전에 면접실 문 앞에서 대기 / 면접시간 10분 / 면접위원 2명","notes":"","qa":[{"q":"2학년 때 과학 성적이 낮은데 이를 위해서 뭘 노력했는지","a":"스터디나 노트정리 위주로 협동진행했다는 식으로 대답"},{"q":"AMOC 관련해서 탐구 진행한 내용 말해주세요.","a":"AMOC란 ~ AMOC가 멈출 가능성이 크다는 논문을 읽고~ 탐구를 진행하였다. Q2-1: 언제 발행된 논문인지 기억하는지 이번년도 7월에 나온 논문이라 대답"},{"q":"딥러닝 기술을 이용한 해양 시뮬레이션 제작에 대해 어떤 활동을 했는지","a":"합성곱 신경망, 신경성 적대 신경망, 장단기 메모리 모델에 대해서 알아보고,~Q3-1: 각 모델에 대해서 말씀해주세요.합성곱 신경망은 ~"},{"q":"수학시간에 해양 시뮬레이션을 만들기 위한 수학에 대해 탐구한 내용 말해주세요.","a":"흐르는 유체의 속도를 전미분하면 유체의 가속도가 나오는데,~ 고교수준에서 이해할 수 있는 정도로 진행했다고 대답"},{"q":"물리 시간에 충격파와 통가 해저 화산 폭발 탐구 진행한거 말씀해주세요.","a":"통가 해저 화산 폭발로 인해 발생한 쓰나미가 일반적인 지진해일로 인한 쓰나미와 달리 충격파에 의해 발생~"},{"q":"탐구를 많이 진행했는데 혹시 어느 분야에 가장 흥미가 있는지","a":"해양 미생물 관련해서 흥미가 있습니다.Q6-1: 관련해서 어떤 탐구 진행하셨나요? 탄소 중립 관련해서 NA1 탐구를 동아리 시간에 진행~Q6-2: 통계자료는 어떤 걸 인용하셨는지한국 해양과학기술원에서 제공한 ~(아마 정확한 수치와 달랐던 거 같은데...일단은 기억하던대로 대답함)"},{"q":"행특 내용 관련해서 인성 질문","a":""}],"src":"세종특별자치시교육청 「보인다! 5.0 면접지도 길라잡이」","year":"2024학년도"},{"univ":"인하대학교","dept":"경영학과","jeonhyeong":"학생부종합(인하미래인재전형)","method":"- 지원동기- 활동 중심으로 생기부 기반 질문- 마지막으로 하고픈 말입학사정관님과 교수님께서 웃으면서 들어주시고 긴장된 분위기가 아니라 준","notes":"비한 대로 편안하게 답하면 좋을 것 같습니다. 책과 관련된 내용을 많이 물어보시니 생기부에 적혀있는 책에 대해선 숙지하고 가는게 좋을 것 같습니다.","qa":[{"q":"자기소개 및 지원동기 말씀해주세요.","a":"경영학과에서 마케팅, 재무 등 다양한 분야에서 경력을 쌓아 전문적인 마케터가 되고 싶어 지원하게 된 지원자입니다. 고등학교 2학년 때, 학교 축제에서 동아리 부스를 운영하며 의류를 제작하고 판매한 경험이 있습니다. 그 과정에서 구매를 망설이는 학생들에게 제품의 장점을 적극적으로 설명하며, 결국 구매로 이어진 경험은 저에게 큰 의미가 있었습니다. 이 경험을 통해 마케팅의 본질인 구매자와의 소통의 중요성을 깨달았고, 고객이 망설이는 이유를 이해하고 그에 맞춰 제품의 장점을 강조하는 과정에서 고객의 니즈를 파악하는 능력이 얼마나 중요한지를 배웠습니다. 이러한 경험은 성공적인 경영에 필수적인 요소임을 깊이 깨닫게 해주었고, 경영학에 대한 흥미가 더욱 커졌습니다. 저는 이곳에서 더 깊이 있는 지식과 경험을 쌓아, 미래의 전문 마케터로 성장하고 싶어 인하대학교 경영학과에 지원하게 되었습니다."},{"q":"마지막 생존코드, 디지털 트랜스포메이션이라는 책을 읽었다고 하는데 이 책을 읽고 느낀점 말해주세요.","a":"마지막 생존코드, 디지털 트랜스포메이션은 디지털 시대에 기업이 생존하고 성장하기 위해 반드시 필요한 디지털 혁신의 중요성을 강조하고 있습니다. 이 책은 아마존, 넷플릭스와 같은 성공 사례를 통해 기업들이 디지털 환경에서 지속 가능한 성장을 이루기 위해 디지털 혁신의 통합, 유연한 조직 문화 등 어떤 전략을 세워야 하는지 논의합니다. 이 책을 통해 변화에 대한 두려움보다 적극적으로 수용해야 한다는 메시지를 통해 변화의 필요성을 깨달았습니다. 또한 고객 중심의 접근 방식이 얼마나 중요한지 이해하게 되었습니다. 고객의 요구와 행동을 분석하여 맞춤형 서비스를 제공하는 것이 성공의 열쇠라는 사실을 알게 되었습니다. 대학에 진학한 후, 저는 이 책에서 배운 내용을 바탕으로 지속적인 학습과 경험을 쌓아 나갈 계획입니다."},{"q":"경제 시간에 그린워싱과 관련된 활동을 했다고 하는데 무슨 활동인가요?","a":"스타벅스 리유저블컵 증정 행사가 그린워싱에 불과하다는 지적을 접한 후, 그린워싱이 소비자 혼동을 초래하고 친환경 기업에 피해를 줄 수 있다고 생각하게 되었습니다. 이를 해결하기 위해 그린워싱의 문제점과 친환경 기업의 제품 홍보를 담은 영상을 제작하기로 결정했습니다. 학생들이 화장품에 관심이 많다는 점에 착안하여, 채소 등 자연에서 얻는 성분을 사용하여 화학 성분을 최소화하는 기업인 스킨푸드를 선정했습니다. 영상에서 플라스틱 용기를 종이로 감싼 페이퍼 보틀을 친환경 제품으로 홍보한 사례와 함꼐 그린워싱의 문제점을 밝힌 후 재활용 가능한 용기와 생분해성 포장재를 사용하는 스킨푸드를 홍보하여 구매를 유도하는 장면을 담았습니다. 이 프로젝트를 진행하면서 기업의 책임에 대해 깊이 생각하게 되었습니다. 기업이 친환경 제품을 홍보할 때 진정성과 투명성이 중요하다는 것을 다시 한 번 확인했습니다. 이러한 경험을 통해 기업의 사회적 책임과 지속 가능한 경영에 대해 깊이 탐구하고 싶다는 열망이 생겼습니다."},{"q":"<디지털 마케터로 일하고 있습니다>라는 책에 대해 설명해주세요.","a":"이 책은 디지털 마케팅의 빠르게 변화하는 환경을 다루며, 기업과 브랜드가 직면하는 다양한 이슈와 트렌드를 분석합니다. 디지털이 중요시되는 상황에서 디지털 마케팅의 중요성을 강조합니다. (기억이 안 나서 제대로 답을 못함.)"},{"q":"시간이 다 되었네요. 마지막으로 하고싶은 말 있나요?","a":"인하대학교에서의 경험이 저를 더욱 큰 꿈으로 이끌어 줄 것이라고 확신합니다. 이곳에서 배움과 성장을 함께할 수 있는 기회를 주신다면 윤리적 비전과 글로벌 마인드를 겸비한 인재로서 기대에 부응하며 긍정적인 변화를 만들어가는 일원이 되도록 최선을 다하겠습니다. 감사합니다.후배들을 위한 조언 책과 관련된 질문이 들어올 수 있으니 자신이 읽었던 책에 대한 내용은 숙지하고 가는 게 좋을 듯. 면접의 분위기가 무겁다기 보다는 편안함에 가까우므로 긴장하지 말고 준비한 대로만 답하는 게 좋을 듯. 자신의 학생부 내용은 무조건 숙지해야함."}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(1권)」","year":"2025학년도"},{"univ":"인하대학교","dept":"경영학과","jeonhyeong":"학생부종합(인하미래인재전형- 대기실 입장 -> 전자기기는 가방에 보관- 가번호표 목걸이 착용 후 대기 -> 면접실 앞 복도에서 대기)","method":"- 면접실 입장 -> 가번호 말하고 타이머 시작(10분 면접 진행)-> 인사 및 타이머 시작 -> 확률과 통계 -> 꼬리질문 -> 사회문화-> 꼬리질문 -> 자율활동 -> 타이머 울림 및 면접 마무리- 타이머 알림 울리면 면접 마무리 후 퇴장- 전자기기 사용이 대기실에서 불가, 자료는 미리 프린트해갈 것.","notes":"- 대기실에서 꽤 오래 대기할 수 있으므로 물, 음료 챙겨가면 좋음.- 전자기기를 소지할 가방 챙겨가면 좋음.","qa":[{"q":"확률과 통계에서 선형회귀, 공분산, 최소제곱법 등 다양한 데이터 관련 수학 탐구를 하셨다고 되어있네요. 그렇다면 최소제곱법을 이용해서 도출할 수 있는 결과가 무엇인가요?","a":"최소제곱법을 활용해서 선형회귀를 구할 수 있습니다. 가상의 회귀식을 가정하고 잔차라는 개념을 활용해서 각 데이터와의 차이점을 구하면 가장 데이터의 연관관계를 잘 반영하는 회귀식을 구할 수 있다고 배웠습니다."},{"q":"그런 선형회귀, 최소제곱법 탐구하면서 (기억은 안나는데 또 다른 수학 개념 포함) 공부했는지?","a":"그 개념은 따로 탐구 안 하고 공분산, 회귀, 상관계수 부분만 탐구했습니다."},{"q":"그럼 선형회귀같은 개념을 탐구하면서 기업에게 이 개념이 어떻게 활용될 수 있다고 생각했나요?","a":"기업들이 이를 통해 고객의 니즈를 파악할 수 있다고 생각합니다. 고객들의 데이터를 구해서 니즈를 파악할 수 있습니다."},{"q":"그럼 좀 더 통계학에서 넓게 질문을 하자면, 만약 자신이 이런 통계학 관련 전문가가 되었다고 생각하고 필요한 소양이 뭐라고 생각하세요?","a":"저는 인문학적 소양과 수학적 소양이 모두 필요하다고 생각합니다. 먼저 데이터를 활용해서 그 고객의 니즈를 파악하려면 각 데이터의 인문적인 특징이라던가 요소를 인문학적으로 이해할 수 있어야하고, 수학적으로 그 데이터를 분석할 줄 알아야 한다고 생각합니다. (그 인문학적 소양만 말씀하셨어요.) 네, 인문학적 소양으로는 고객의 니즈를 파악하고 (네 그 인문학만 지금 얘기하셨는데) (이어서 수학적 소양도 얘기하려고 했는데 말 두 번 끊겨서 당황) 네..... 수학적 소양이 필요하다고 그럼 말씀 드릴 수 있겠습니다. ㅎㅎ(웃으면서 넘어감)"},{"q":"사회문화 정의 단원을 배우고 넛지에서 얻은 아이디어로 기아문제 해결을 위해 카드 뉴스를 만들었다고 되어있는데 자세히 설명해주세요.","a":"1학년 때 넛지라는 책을 읽었었습니다. 넛지라는 책 중 ‘단순히 정보를 제공하는 것만으로도 사람들을 움직일 수 있게 하는 힘이 있다’라는 구절을 인상 깊게 읽어서 이를 활용해서 활동을 시작했습니다. 그래서 기아와 관련된 정보를 제공하는 것만으로도 학우들이 조금이라도 관심을 가지지 않을까 해서 기아 문제를 담은 카드 뉴스를 업로드했습니다."},{"q":"그럼 이 활동을 통해서 학우들의 반응을 좀 이끌어냈나요?","a":"해당 활동에서 카드 뉴스는 개인 SNS에 업로드해서 많은 학우들에게 전파하기 어려웠고, 3학년 때 개인적으로 기아와 경제적 원인과 관련해 발표를 진행했었습니다. 곡물 투기 시장과 관련된 발표를 진행했는데, 많은 학우들이 몰랐던 사실에 대해 알 수 있었다고 하며 반응을 끌어낸 경험은 있습니다."},{"q":"기아 문제 탐구하면서 결국 기아자동차 기업이 먼저 뜨는 포털 사이트 문제와 관련해 메일을 작성해서 보냈나요?(생활기록부에는 메일 작성 계획을 했다고 기재되어 있음)","a":"네, 해당 사이트에 문의 메일을 작성해 보냈습니다. (답변은?) 아쉽게도 답변은 받지 못했습니다. (아하 그랬군요.)"},{"q":"학교생활을 하면서 단체로 활동을 하고 소통할 일이 많았을 텐데, 그 소통의 문제를 어떻게 해결했는지, 그 해결을 통해 얻은 교훈이 뭔지, 그리고 마지막으로 자신의 소통 노하우 팁이 있다면?","a":"네 2학년 때 저는 학교에서 실패하기라는 프로젝트에 참여했습니다. 학우들이 모여 약 6개월 동안의 장기간 사업 프로젝트를 진행하는 것이었습니다. 제가 팀의 리더를 맡다 보니 팀원들의 주체적인 활동을 이끌어내면서 어려움을 겪었습니다. 아무래도 학생들이다 보니 각자 스케줄이 많이 다르기도 하고 장기간 진행하며 어려움이 있었는데, 저는 학우들의 주체적인 활동을 이끌어내기 위해 주체적으로 제가 회의를 운영하기보다 각 팀원들이 주체적으로 회의를 진행하는 방식으로 해결했습니다. 좀 더 각자의 역할을 잘 이해하고 이끌도록 진행을 했고, 이를 통해 얻은 교훈은 리더십에서 소통이 아주 중요한 요소라는 점을 깨달았습니다. 마지막으로 저만의 노하우는 진솔하게 말하기라고 생각합니다 (타이머 울림으로 뒤이어 말하지 못함), (딱 맞춰서 답변 끝내셨네요. 면접은 이상 마무리됩니다. 수고하셨어요.)후배들을 위한 조언 답을 하는 것도 중요하지만 교수님의 질문을 이해하고 그 의도에 맞는 대답을 할 줄 아는 게 중요한 것 같습니다. 특히 한 질문씩이 아니라 여러 개의 질문을 듣고 답할 줄 알아야 합니다. 마지막 질문 참고하시면 좋을 것 같아요.그리고 면접 분위기가 좋았다고 생각은 하는데, 위에 대화 형식으로 진행하다 보니 말이 끊긴 적이 있었는데 이럴 때 당황하지 말고 하려던 말 마무리는 했으면 좋겠습니다. 긴장하면 아는 것도 대답 못하니 모의면접 때 이런 상황에 대비해 보는 것도 좋겠습니다.답변 중 내가 무엇이 부족했다거나 실천하지 못한 경우 그대로 말하면서 끝에 그래도 다른 탐구에서는 이렇게 해본 적 있다거나 앞으로 더 탐구하거나 실천할 것이다로 마무리하면 좋을 것 같습니다. 위에 메일을 작성해서 보냈으나 답변은 받지 못했다고 답변한 것이 좀 후회되는 답변이라 다른 활동에서 메일 작성 후 해당 기관과 상의했던 활동이라도 언급할 걸 하는 미련이 남습니다.최대한 자신을 어필할 수 있게, 자신의 강점인 활동들을 정리해서 대답 못하거나 부족한 상황에 활용할 줄 알면 좋으니 그것도 같이 정리해 보세요."}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(1권)」","year":"2025학년도"},{"univ":"인하대학교","dept":"경영학과","jeonhyeong":"학생부종합(인하미래인재전형- 지원 동기)","method":"- 전공 질문- 행발 질문- 성격 장단점- 마지막 할 말","notes":"면접 준비 자료 대기실에서 볼 수 있고, 폰은 전원을 꺼서 제공해 주는 비닐에 담아 가방에 넣어둬야 함.","qa":[{"q":"경영학과 지원하게 된 동기를 말해보세요.","a":"먼저 저는 고등학교 진학 중 진로에 대한 고민을 많이 했습니다. 여러 탐구 활동을 하는 도중 게임이론이나 테마파크 시뮬레이션 활동을 통해서 경영학과에 대한 관심을 가지게 되었습니다. 하지만, 고등학교의 환경적 요인의 한계로 인해 더 깊이 있는 학습이 불가하여 경영학과 진학을 결심하게 되었습니다. 마지막으로 인하대학교만의 해외 프로그램과 실무 중심의 현장 교육에 참여하여 비즈니스에 필요한 문제해결 능력을 키우고자 지원하게 되었습니다."},{"q":"서브프라임 모기지 사태를 실물경제와 엮어 설명했다고 하는데 이를 자세히 설명해보세요.","a":"서브프라임 모기지 사태란 신용등급이 낮은 사람들에게 은행이 부동산 담보 대출을 해줬는데, 부동산 가격이 하락하였기에. 은행이 서브 프라임 등급의 채권을 2차, 3차, 4차 파생상품으로 만들어 판매하였고, 이에 따라 부채가 눈덩이처럼 부풀어 자본 시장에 위기가 온 것입니다. 서브프라임 모기지 사태로 실물경제에 미친 영향은 먼저 주택 가격이 하락하여 1인당 소비지출 역시 하락하였습니다. 또한 수출 기업의 생산 감소로 고용 감소 현상이 일어나 노동시장에 영향을 주는 등 다양한 영향을 미쳤습니다."},{"q":"분식회계에 관한 기사를 정리하고 느낀 점을 서술했다고 하는데 이 활동을 통해 알게 된 것을 말해보세요.","a":"해당 탐구활동을 통해 분식회계란 무엇이며 어떤 영향을 주는지 알게 되었습니다. 분식회계란 기업의 재정상태를 왜곡해 신용등급을 부풀리거나 주가를 인위적으로 조작한 행위를 의미함을 알게 되었고, 또한 분식회계는 국가의 경제 신뢰도를 하락시킨다는 것을 알게 되었습니다."},{"q":"회계사와의 인터뷰를 진행했다고 하는데 어떤 질문을 했는지 말해보세요.","a":"회계사 인터뷰 당시에 CPA 시험이나 준비 과정 중에서 힘들었을 때 견뎌냈던 방법 등, 4차 산업 시대에 사라질 직업이라고 분류되는 회계사가 대체 불가능한 인재가 될 수 있는 방법 등에 대해 질문했습니다."},{"q":"1학년 때 반장선거에서 떨어졌지만 의기소침해지지 않고 선거 공약을 실천했다고 하는데 본인의 이런 실패에도 다시 일어날 수 있었던 이유는 무엇이고 본인의 성격을 말해보세요.","a":"먼저 저는 실패한다고 해서 낙담하지 않는 성격을 가졌습니다. 실패는 또 다른 성공을 낳을 수 있는 기반이라고 여기기 때문에 다시 일어날 수 있었다고 생각합니다. 저는 실패를 두려워하지 않고 빨리 회복하여 다시 시도하는 도전하는 성격을 가졌다고 생각합니다."},{"q":"그런 장점이 있다면 단점도 있을까요? 있으면 무엇인지 말해보세요.","a":"저는 좋은 인간관계를 맺지만 쉽게 신뢰를 주어 손해를 보는 것이 단점입니다. 저는 이런 저의 성격을 보완하기 위해 늘 신중하게 생각하고 타인의 의견도 듣되, 제 의견을 명확히 주장할 수 있도록 노력하고 있습니다."},{"q":"마지막 할 말 해주세요.","a":"먼저 좋은 기회 주셔서 감사합니다. 제가 면접에서 강조하고 싶었던 저의 강점은 도전 정신, 창의역량과 이를 이끌어 줄 수 있는 실천력이었습니다. 감사합니다. 후배들을 위한 조언 면접 시간은 짧으면 6분, 길면 10분 정도 하는 것 같고 보통 8분에서 끝나는 거 같아요. 면접관분들께서 친절했고 전반적으로 압박 면접 분위기는 아니니까 편한 마음으로 하세요. 그리고 생기부 질문은 정말 그 활동했는지 안 했는지 물어보는 거 같고, 생기부에 나와있지 않은 기타 전공에 대한 지식을 요구하는 편은 아닌 것 같아요."}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(1권)」","year":"2025학년도"},{"univ":"인하대학교","dept":"국제통상학과","jeonhyeong":"학생부종합(인하미래인재전형- 아이스브레이킹(행특 부분에서 리더십, 학교생활 중 힘들었던 점 등))","method":"- 전공 질문- 지원 동기- 마지막 할 말면접 시간 : 약 8분","notes":"면접위원수 : 2명유의 사항 : 한 건물에서 전체 학과가 면접 보기 때문에 혼잡하므로 미리 가 있기.","qa":[{"q":"고민되고 어려운 일이라도 금방 쉽게 극복하는 성향을 지녔다고 하는데 어떤 활동에서 이런 성향이 나타났나요?","a":"저는 청소시간에 친구들이 각자 자리에서 책임감 없는 모습을 보여 이 문제를 극복해나가고자 하였습니다. 따라서 저는 주기적으로 열리는 학급회의에서 이 문제를 건의했고 청소 우수팀을 선정해 소정의 상품을 전달하는 규칙을 만들었습니다. 이 규칙을 도입한 후 친구들이 책임감 있게 청소구역을 관리하는 긍정적인 방향으로 흘러갔고 이 활동에서 저의 성향이 나타났다고 생각합니다."},{"q":"인공지능을 사용하여 무역 예측 모델을 조사했다고 하는데 어떤 모델이었나요?","a":"저는 회귀분석 모델과 시계열 분석 모델을 조사했습니다. 회귀분석은 ~이고 시계열 분석은 ~입니다. 하지만 회귀분석과 시계열 분석에는 ~라는 한계가 있습니다. 저는 머신러닝과 딥러닝의 순환 신경망을 통해 이 한계점을 보완하고자 하였습니다. 머신러닝과 딥러닝은 ~특성이 있어 회귀분석과 시계열 분석의 한계를 보완할 수 있습니다."},{"q":"산업 내 무역이 무엇이고 장점과 단점을 말해주세요.","a":"산업 내 무역은 같은 산업 내에서 유사한 제품을 교역하는 것입니다. 예를 들어 자동차 산업에서 독일이 고급차를 수출하고 일본이 대중형 차량을 수출하는 경우가 있습니다. 산업 내 무역의 장점으로는 소비자의 선택이 확대된다는 점이 있습니다. 소비자들은 산업 내 무역으로 더 다양한 제품을 선택할 수 있어 만족도가 높아집니다. 반면에 비슷한 제품이 많아지면서 시장 내에서 과잉경쟁이 발생할 수 있다는 단점도 있습니다."},{"q":"기준금리가 상승하면 나타나는 현상에 대해 말해주세요.","a":"기준금리가 상승하면 사람들이 은행에 돈을 예치하게 되고 물가가 안정될 가능성이 있습니다. 이렇게 긍정적인 측면이 있는 반면에 국내총생산이 낮아진다는 부정적 측면도 있습니다. 국내총생산은 일정 기간 동안 한 국가에서 발생하는 모든 경제적 지표를 말합니다. 이런 국내총생산은 소비, 투자, 정부 지출, 순수출로 구성이 되고 이 중 가장 많은 비중을 차지하는 것이 소비와 투자입니다. 그런데 기준금리가 상승하면 소비와 투자가 줄어들어 경제성장을 나타내는 국내총생산이 줄어드는 것입니다. 따라서 기준금리 상승은 양면적인 모습이 있습니다."},{"q":"중국 제조 2025가 무엇이고 한국에 어떤 영향을 미치나요?","a":"중국 제조 2025는 중국이 경쟁력 강화를 위해 고급 기술 산업을 주도하는 목표를 설정해 산업 혁신을 시행한 프로젝트입니다. 이런 중국의 산업 구조 혁명으로 인해 한국과 겹치는 품목인 반도체나 바이오 약품 등의 품목 수출이 줄어들어 한국 수출에 부정적 영향을 가져올 수 있습니다. 또한 중국이 중간재나 부품을 자급자족하기 때문에 한국의 중간재나 부품의 수출이 줄어들 가능성이 큽니다. 이를 해결하기 위해 한국은 한국만의 핵심 기술을 개발하고 경쟁력을 강화하는 것이 필요하다고 생각합니다."},{"q":"경영학과에 관심이 조금 있는 것 같은데 왜 국제통상학과에 지원했나요?","a":"제가 국제통상학과에 지원한 이유는 아시아 시장에 대한 관심에서 출발했습니다. 아시아는 세계 경제의 핵심축으로 자리잡고 있습니다. 특히 급성장하는 신흥국과 기술 혁신을 주도하는 선진국이 자리하는 이런 역동적인 지역에서의 통상에 매력을 느꼈습니다. 저는 이런 관심을 바탕으로 중국의 희토류, 일본의 화이트리스트, 미중 무역 분쟁 등의 탐구활동을 하면서 저의 꿈에 대해 한층 더 깊어졌습니다. 따라서 저는 한국, 그리고 아시아가 급변하는 시장에서 성공적으로 진출할 수 있는 전략을 고안하고 설계할 수 있는 아시아 통상 전문가가 되고 싶어 국제통상학과에 지원하게 되었습니다."},{"q":"마지막으로 할 말 있나요?","a":"변화하는 상황 속에서 매일매일 변하는 국제통상 환경에는 명확한 정답이 없다고 생각합니다. 저는 인하대학교 국제통상학과에서 저만의 해답을 찾아나가는 사람이 되고 싶습니다. 감사합니다.후배들을 위한 조언 인사 90도로 하기, 목소리 크게 하기.(첫인상 중요함)두괄식으로 말하기.모의면접 최대한 많이 해보기.(실전에서 덜 떨림)활동을 말할 때 왜 활동을 하게 되었는지, 어떻게 활동을 했는지, 어느 것을 얻었는지 포함."}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(1권)」","year":"2025학년도"},{"univ":"인하대학교","dept":"문화콘텐츠문화경영학과","jeonhyeong":"학생부종합(인하미래인재전형)","method":"학과별로 따로 모여 대기하다가 순번대로 면접 진행함","notes":"면접 시간 8분이 생각보다 굉장히 짧기 때문에 이 점 유의 하길 바람.","qa":[{"q":"학과 지원 동기","a":"제가 인하대학교 문화콘텐츠문화경영학과에 지원하게 된 이유는 제가 미래에 다양한 콘텐츠를 만드는 기자가 되고 싶기 때문입니다. 제가 생각하는 기자의 역할은 사람들이 향유하는 문화가 무엇인지 탐구하고 그것에 맞춰 다양한 콘텐츠를 제작하는 것이라고 생각합니다. 그러한 기자가 되기 위해서는 먼저 콘텐츠가 무엇인지 알아보는 것이 가장 중요하다고 생각합니다. 관련 지식을 쌓기 위해서는 인하대학교에서 공부하는 것이 가장 좋은 선택지라고 판단했기에 고민없이 지원하였습니다."},{"q":"퓰리처 활동에 대해 설명","a":"퓰리처 활동은 퓰리처라는 언론계에 지대한 영향을 미친 인물에 대한 탐구를 진행한 활동입니다. 퓰리처는 다양한 기사를 작성하며 많은 사람들의 관심을 끌었고 이를 통해 자신만의 신문사를 만들어 언론의 왕이라고 불린 사람입니다. 하지만 그 과정에서 황색 얼론이라고 하는 자극적인 기사들을 작성하며 아쉬운 평가 또한 받고있는 인물입니다. 아쉬운 평가 또한 받고있는 인물입니다. 제가 생각하는 퓰리처는 언론의 부흥기를 이끌었고 다양한 사람들이 언론을 쉽게 접할 수 있도록 하였기에, 이러한 점에서는 굉장히 존경 할 만한 인물이라고 생각합니다. 다만 황색언론이라는 부정적인 타이틀도 만들었기 때문에 복합적인 평가가 존재하고 이러한 명과 암을 친구들에게 알릴 수 있었기에 굉장히 의미있는 활동이었습니다."},{"q":"신문 제작 활동에 대해 설명","a":"신문 제작 활동은 이학년 동아리 때 하였던 학교 신문 제작 활동이었습니다. 학교의 공식적인 지원을 받아 우리 학교에서 어떤 활동을 하는지에 대해 많은 사람들에게 홍보 하기 위하여 제작하는 신문이었습니다. 저는 편집장 역할을 맡으면서 부원들이 어떠한 활동을 맡아야 하는지 배정해주고 서로의 글을 평가할 수 있는 시간도 마련하면서 제 능력과 글쓰기 능력을 모두 향상시킬 수 있도록 하였습니다. 그리고 결과적으로 신문 또한 좋은 결과물을 내어서 우리 학교를 알리는데 큰 역할을 한 것 같기 때문에 가장 기억에 남습니다."},{"q":"트루먼 쇼를 보고 느낀 소감","a":"트루먼 쇼를 시작하는 과정에서 트루먼이라는 사람이 받았던 엄청난 인권 침해에 대하여 탐구해 봤던 활동이었습니다. 트루먼쇼라는 프로그램은 영화 안의 세계에서 국민 프로그램이라고 불릴 만큼 있기 있는 방송이었습니다. 다만 프로그램을 촬영하는 과정에서 트루먼이라는 사람의 인생을 빼앗고 인간으로서 살아갈 수 있는 권리도 파괴시켰습니다. 인기가 굉장한 프로그램을 만든 것은 콘텐츠 제작자로서 엄청난 업적을 쌓은 것이지만 한 사람의 인생을 무너뜨리는 것은 윤리적으로 옳지 않은 행동을 한 것이기에 비난받아 마땅하고 그 사실 자체로 트루먼쇼는 잘못된 것이라고 생각합니다.후배들을 위한 조언 면접자들이 많다 보니 8분 안에 모든 것을 해결해야 한다. 마지막 질문에 대한 답변을 하는 도중에 시간이 종료 된다면 답변 까지는 하게 해준다. 마지막 한마디는 묻지 않고 시간 안에 모든 답변을 처리할 수 있도록 하는 연습이 필요하다."}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(1권)」","year":"2025학년도"},{"univ":"인하대학교","dept":"문화콘텐츠문화경영학과","jeonhyeong":"학생부종합(인하미래인재전형)","method":"대기실 입성 -> 면접실 앞 대기 -> 수험번호 및 인사 -> 지원동기 -> 생기부 질문 -> 마지막 한마디","notes":"대기실에서 전자기기빼고 다 사용가능","qa":[{"q":"긴장하지말고 편하게 준비한거 말씀하시면 됩니다.","a":"넵 알겠습니다!"},{"q":"지원동기 먼저 말해볼까요?","a":"저는 사회문제에 관심이 많은 학생입니다. 사회문제에 관심이 많다보니 왜 사회문제가 심각해지고 있는지 그 근본적인 원인에 집중하기 시작했습니다. 제가 찾은 근본적인 원인은 갈등이었습니다. 이러한 근본적인 원인인 갈등을 해결하기에 가장 좋은것이 마케팅하고 문화콘텐츠라고 생각하는데 위 학교에 학과에서 문화 콘텐츠와 마케팅을 한번에 배울 수 있다는 점에 매력을 느껴 지원하게 되었습니다. 또 저는 마케팅과 문화콘텐츠는 실습으로 배우는 것이 효과가 가장 크다고 생각하는데 위 학과의 교육과정을 보고 실습이 많은 것도 큰 매력으로 느껴져 지원하였습니다."},{"q":"3학년 진로 활동에서 소비로 인한 환경 파괴에 비관적인 시선을 담은 영상을 만드셨다고 하는데 무슨 내용인가요?","a":"주된 내용은 스마트폰이나 태블릿 같은 스마트기기를 계속해서 바꾸는 것에 대한 심각성을 알리기 위한 영상이었습니다. 스마트기기에 대한 과소비를 영상으로 만들면 모든 사람들이 공감하기 쉽고 직접적으로 느껴질 것 같았습니다. 영상에서 한 학생이 새로운 휴대폰을 구매해 자랑하기 시작했고 그로 인해 많은 학생들이 휴대폰을 바꾸며 과소비하는 것을 영상으로 표현했습니다. 이뿐만 아니라 ebs 영상처럼 뒤에 과소비의 심각성을 알려 재미뿐만 아니라 교육적으로 심화된 영상을 만들었습니다."},{"q":"왜 라디오 공익광고를 만드셨고 어떻게 만들었는지?","a":"제가 2학년때 슬기로운 미디어 생활이라는 책을 읽은 적이 있습니다. 이 책에서 청각이 사람들에게 주는 영향에 대해 자세하게 설명을 해줍니다. 이로 인해 평소에 시각 정보가 가장 중요하다고 생각한 저의 마인드를 변화시켜 주었습니다. 그래서 과소비로 인한 영상을 만들었으니 소리만을 이용한 라디오를 만들어야겠다는 게 제 생각이었습니다. 라디오는 소리만 들리기 때문에 내용에 집중하기 위해서는 귀를 기울여야 합니다. 그로 인해 소비자가 정보를 더 정확하고 자세하게 파악한다고 생각합니다. 라디오는 최근 심각한 문제가 되고 있고 모두가 이 문제를 심화시키고 있다고 생각하는 패스트 패션에 대한 심각을 알리는 라디오를 만들었습니다. 패스트 패션에 대한 조사를 진행하고 라디오 공익광고는 어떻게 만들어지는지 조사해 보았는데 라디오 공익광고에는 비유적표현을 많이 쓰는 것을 보고 저도 활용했습니다."},{"q":"오 그럼 라디오 공익광고 내용이 무엇인가요?","a":"‘우리가 옷을 입을수록 지구는 옷을 벗게 됩니다‘ 라는 내용이었습니다."},{"q":"3학년 동아리활동에서 알고리즘 체제의 변화를 말씀하셨는데 어떻게 변화시키는 것을 말한 것인가요?","a":"현재 유튜버들이 욕설이나 부정적인 언어를 사용하는 이유는 그것이 사람들의 관심을 끌기 좋기 때문이라고 생각합니다. 조회수는 유튜버의 생계와 직접적으로 연결되기 때문에 모든 유튜버들은 알고리즘을 중요하게 생각합니다. 현재 알고리즘 체제는 정확하지는 않지만 인기가 많은 영상이면 알고리즘에 많이 뜨게 됩니다. 이러한 알고리즘 방식을 착한 언어 즉 긍정적 언어를 많이 사용하는 영상은 알고리즘에 유리하게 해주고 부정적 언어를 사용하면 알고리즘에 불리하게 작동하는 방식으로 변화시키는 것을 말했습니다. 그럼 긍정적 언어만을 활용하는 유튜버들이 생길 것이고 최소 부정적 언어를 줄이려는 노력이 발생할 것입니다."},{"q":"오 저는 이 생기부에서 초코곰과 젤리곰이라는 동화책이 굉장히 흥미가 생기는데 무슨 내용인지 말씀해주실수 있을까요?","a":"초코곰과 젤리곰 동화책은 쉽게 생각하면 과거 흑인과 백인 세상이라고 할 수 있습니다. 초코곰과 젤리곰은 서로 절대 대화도 해서는 안 되고 버스에서 따로 좌석이 있을 정도로 서로 철저히 외면합니다. 이때 한 초코곰과 젤리곰은 사랑에 빠지게 되고 주변 곰들에게 무시당하고 비판받습니다. 그때 이들에게 모두가 친하게 지내는 과자나라가 존재한다는 소식을 듣고 과자 나라를 찾아 떠납니다. 결국 과자 나라를 찾아 결혼해 초코와 젤리가 섞인 아기들 낳고 이야기 종료됩니다."},{"q":"수고했습니다. 마지막으로 하고싶은 이야기 있나요?","a":"저는 제 장점을 말해보겠습니다. 저는 지금까지 살면서 누구랑도 불화를 일으킨 적이 없습니다. 모두랑 친하게 지내고 어른분들이랑도 존중하며 잘 지냅니다. 제가 왜 이런지 생각을 해보니 저는 평소에 각각의 사람들마다 기준을 만듭니다. 이 사람에게는 이정도 말은 괜찮고 이 부분은 조심해야 된다라는 기준입니다. 이 습관은 요즘같이 급변하는 세상에서 중요한 능력이라고 생각합니다. 특히 마케팅 분야나 문화콘텐츠 분야에서는 빠질 수 없습니다. 뭐든 선을 지키는 게 중요한 세상이 되어가고 있는데 저는 이 선을 지키는 것에 최적화되어 있고 그로 인해 마케팅 분야의 강자라고 생각합니다. 저를 꼭 뽑아주세요!!!후배들을 위한 조언 인하대는 압박 면접이 아니었습니다. 편하게 말할 수 있도록 처음에 따뜻하게 웃으면서 대해주시는데 다른 학과는 그렇지 않은 경우도 있더라고요. 압박 면접도 준비하는 게 좋을 것 같습니다. 대기실에서는 면접 준비한 거 볼 수 있으니 프린트해 가시길 바랍니다"}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(1권)」","year":"2025학년도"},{"univ":"인하대학교","dept":"문화콘텐츠문화경영학과","jeonhyeong":"학생부종합(인하미래인재전형)","method":"리더쉽 질문->전공 질문->전공 질문->전공 질문->전공 질문","notes":"자기소개 지원동기 등 공통질문을 하지 않음, 전공 질문을 많이 함.","qa":[{"q":"반장으로 활동하며 리더쉽을 보여준 사례에 대해서 말씀해주세요.","a":"저는 체육대회 전 반 티를 정하는 과정에서 각각 다른 개성을 가진 다양한 친구들이 모여있기 때문에 의견 조율이 어려웠던 경험이 있습니다. 저는 이 문제를 해결하기 위해 반 아이들의 의견을 모아 들어보며 각각 의견의 장단점을 함께 이야기하고 합의점을 찾기 위해 의논하여 모두가 만족하는 반 티를 함께 정했었습니다."},{"q":"스토리텔링과 콘텐츠 산업의 연관성에 관해서 설명해주세요.","a":"스토리텔링은 상대방에게 전달하고자 하는 정보를 이야기를 통해 전달하는 것을 말합니다. 사람들이 공감하거나 관심을 가지는 요소를 이야기 속에 담아 상대방에게 몰입감 있게 정보를 전달할 수 있는 특징이 있습니다. 스토리텔링을 이용한 콘텐츠는 그렇지 않은 콘텐츠보다 사람들에게 더 많은 관심을 끌 수 있으므로 스토리텔링은 콘텐츠 산업에서 경쟁력을 확보하기 위한 중요한 요소입니다."},{"q":"스토리텔링을 이용하여 제작한 지역 홍보 콘텐츠에 관해서 설명해주세요.","a":"제가 선택한 장소는 드라마 촬영지로 유명해 카페가 들어서 관광객이 많이 찾던 장소입니다. 하지만 드라마의 인기가 줄어들며 관광객은 줄어들게 되었고 카페도 하나둘씩 문을 닫게 되었습니다. 저는 이문제를 해결하기 위해서 기존의 홍보방식이 아닌 새로운 홍보방식이 필요하다고 생각했습니다. 그래서 장소를 조사하던 중 그 장소가 드라마 촬영지이기 이전에 한국전쟁 이후 피난민들의 안식처이자 지역의 삶을 담은 벽화가 그려진 벽화마을이었다는 것을 알게 되었습니다. 그래서 저는 그 장소를 역사적 공간으로써 스토리텔링 하여 홍보 콘텐츠를 기획하고 제작하였습니다."},{"q":"콘텐츠 수출 시장별 콘텐츠 개발 전략에 관해서 탐구하셨는데 활동에 관해서 설명해주세요","a":"저는 OTT 플랫폼이 성장하며 국가별 콘텐츠를 소비할 수 있는 환경이 조성되어 국가 간 콘텐츠 수출이 증가해 각 수출 시장별 특징을 조사하고 콘텐츠 제작 전략에 대해서 분석하는 활동을 했습니다."},{"q":"핵심시장의 특징과 수출 전략에 관해서 설명해주세요.","a":"핵심시장은 시장성이 높고 k 콘텐츠의 경쟁력이 높은 시장을 말합니다. 핵심시장은 지속적인 투자로 팬덤을 유지한다면 안정적인 수익을 창출할 수 있는 특징이 있습니다. 저는 이러한 특징을 가진 핵심시장에서 OSMU 전략을 활용하는 것을 제안했습니다. OSMU는 원 소스 멀티 유즈를 말하는 것으로 하나의 작품을 다양한 콘텐츠로 재창작하는 것을 말합니다. OSMU 전략은 원작을 다양한 관점으로 바라볼 수 있게 해준다는 점과 원작의 팬덤이 존재하기 때문에 흥행이 보장되고 새로운 콘텐츠를 제작하는 것보다 상대적으로 제작 비용이 적다는 경제적 이점도 가지고 있습니다. 그래서 저는 지속적인 투자로 팬덤을 유지해야 하는 핵심시장에서 유리한 전략이라고 생각했습니다.후배들을 위한 조언 전공 관련 질문을 많이 하니깐 전공 관련 활동과 개념에 대해서 자세하게 외워야 합니다.생활기록부에서 주로 질문을 하니 생활기록부에 작성된 활동에 대해서 꼼꼼하게 예상 질문을준비해간다면 큰 어려움 없이 잘할 수 있을 것입니다."}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(1권)」","year":"2025학년도"},{"univ":"인하대학교","dept":"고분자공학과","jeonhyeong":"학생부종합(인하미래인재)","method":"자기소개 -> 활동 내용 질문 -> 꼬리 질문 -> 활동 내용 질문 -> 행동 특성 질문 -> 활동 내용 질문 -> 마지막으로 하고 싶은 말1. 교수님 두 분과 면접이 진행됨2. 이동 인솔부터 대기실 안내까지 인하대학교 재학생분들이 매우 친절하게 도와주시기 때문에 다른 대학에 비해서 대기실과 면접실","notes":"모두 편안한 분위기였음.3. 면접 타임 간격이 타이트하게 구성되어있는지 아직 전 타임 면접자 들이 대기 중인데 다음 타임 면접자들이 대기실로 계속 들어와서 대기실이 어수선했음. 따라서 대기실에서 나머지 공부할 생각은 하면 안 될 듯함.","qa":[{"q":"안녕하세요~ 준비하신 자기소개 해주세요","a":"(준비한대로 답변했음. 장래희망 및 관심분야 -> 꿈을 가지게 된 계기 -> 인하대학교 고분자공학과에 지원하게 된 계기 순으로 준비했음.)"},{"q":"자율활동에서 ‘페로브스카이트 혁명’에 대해서 탐구했던 적이 있어요~ 페로브스카이트를 활용해서 탐구했던 내용을 간단하게 말씀해보실래요?","a":"영어1 단원을 학습하면서, 에너지 불균형이 환경오염에 큰 영향을 끼친다는 것을 알게 되어서 페로브스카이트라는 신소재를 통해 이를 해결하고자 했습니다. 페로브스카이트라는 신소재는 높은 광전효율을 자랑하기에 태양전지에 사용하기에 적합합니다. 이 점을 이용해서 스마트그리드라는 시스템을 이용해서 에너지를 균등하게 분배해 에너지 불평등을 해결하는 시스템을 구축해보았습니다."},{"q":"페로브스카이트가 왜 높은 광전효율을 나타내는지 설명해보실래요?","a":"일단 페로브스카이트는 ABX3의 구조로 이루어져 있습니다. A와B에는 양이온이, X에는 음이온이 배치됩니다. 이 구조적 특성으로 인해서 높은 광전효율을 가지고, 태양전지의 광흡수층에 사용됐을 때 높은 효율을 낼 수 있습니다."},{"q":"고급물리학 과목을 수강하셨네요? 펠티에 효과에 대해 자세하게 조사하셨는데, 펠티에 효과에 대해 설명해주시겠어요?","a":"펠티에 효과와 제벡 효과는 모두 열전발전에 사용되는 효과입니다. 먼저, 제벡 효과는 도선의 온도차로 인한 전위차로 인해 열에너지가 전기에너지로 바뀌는 효과이고 펠티에 효과는 같은 원리로 전기에너지가 열에너지로 바뀌는 효과입니다."},{"q":"지금까지 활동하면서, 아쉬웠던 거나 다시 해보고 싶은 실험이 있었나요?","a":"2학년 때 진행했던 염료감응형 태양전지의 염료의 효율을 비교했던 실험이 있었습니다. 시금치와 블루베리의 효율을 비교했는데 둘 사이에 유의미한 차이가 발생하지 않아서 아쉬웠고, 재실험을 통해 이 이유를 알아보고자 했습니다. 앞으로 이러한 염료감응형 태양전지에 대해 더 연구하고 싶습니다."},{"q":"행동 특성 사항을 보니까 자율동아리 활동도 했고 텃밭가꾸기 활동도 하고, 활동을 굉장히 많이 하셨네요? 가장 기억에 남는 활동이 무엇인가요?","a":"저는 댄스동아리 활동을 했던 것이 가장 기억에 남습니다. 댄스동아리 활동을 하면서, 학급축제를 준비하며 학급 친구들에게 춤을 알려주고 따라하기 힘들어하는 학생들에게는 춤을 쉽게 만들어주어, 한 학급을 진두지휘하여 학급 무대를 성공적으로 이끈 경험이 있습니다. 친구들과 협동해서 무언가를 해내는 행동에 큰 보람을 느꼈고, 앞으로도 이러한 리더로 성장하고자 합니다."},{"q":"음.. 이건 좀 어려운 건데, 화학2에서 밀러지수와 법선벡터에 대해 탐구하셨네요? 이에 대해서 설명해주시겠어요?","a":"밀러지수는 단위셀에서 면적면을 나타내는 지수입니다. 이때, 밀러지수는 그 면의 법선벡터를 나타내기 때문에 중요합니다. 법선벡터는 어떠한 면에서 수직으로 나오는 벡터를 의미합니다."},{"q":"극성과 무극성에 대해서 탐구를 하셨네요. 극성과 무극성에 대한 정의를 설명해주세요.","a":"네, 극성은..(갑자기 ‘전하’라는 말이 생각 안 남) 잠시 생각할 시간을 주시겠습니까? (“습니까?”를 말하자마자 생각났음) 말씀드리겠습니다! 극성은 분자 내 전하의 분포가 고르지 않아서 쌍극자 모멘트가 0이 아닌 분자를 극성분자라고 하고, 무극성은 분자 내의 전하 분포가 고르게 분포되어 있어서 쌍극자 모멘트가 0인 분자를 무극성 분자라고 합니다."},{"q":"이제 시간이 거의 다 되었네요, 마지막으로 하고싶은 말 있으면 해주세요.","a":"(준비한대로 대답했음. 준비한 답변은 끝났는데 교수님이 대답을 안 하셔서... “멋진...!! 인하인으로 성장하겠습니다!!!!” 크게 외치고 미소지었더니 교수님 두 분 다 크게 웃으셨음.)"},{"q":"(웃으시는 거 끝나자마자 타이머 울림.) 앗, 시간이 딱 끝났네요! 네~ 수고하셨습니다 나가셔도 좋습니다","a":"넵!!! 감사합니다! (꾸벅꾸벅 여러 번 인사함.)후배들을 위한 조언 인하대학교 면접은 다른 대학교 면접보다 대기장부터 면접장까지 편안한 분위기니까 너무 긴장하지 말고 분위기 타서 편안하게 전부 답변하면 좋겠음.정말로 이 활동을 했는지, 이 활동에 대해서 이해하고 있는지에 대한 내용 확인 질문이 주로 질문되니 활동 내용을 정확하게 파악해야 함. 그리고 정의를 설명하라는 질문과 행동특성 질문까지 받았으니, 생기부를 넓게 공부해야 할 듯함. 화이팅!"}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(2권)」","year":"2025학년도"},{"univ":"인하대학교","dept":"기계공학과","jeonhyeong":"학생부종합(인하미래인재)","method":"다른 학과도 있는데 왜 기계공학과에 지원했는지 -> 아이스브레이킹 같은 질문 -> 미적분 세특 질문 -> 출결 관련 질문 -> 과학개념 질문 -> 성적 관련 질문","notes":"면접 보고 난 후 잘 기억이 안 나지만 최대한 기억나는 대로 적었습니다. 그때 상황과 똑같진 않고 비슷할 것입니다.","qa":[{"q":"지원동기 물은 후 고교 생활하면서 기억에 남는 활동같은 거 있는지 여쭤보심","a":"고등학교 3학년 동아리 시간에 제작한 얼굴인식 자동차 카 도어를 만든 것이 가장 기억에 남습니다. 허스키 렌즈를 이용해서 사용자의 얼굴을 인식 시킨 후에 자동차의 문이 자동으로 열리는 형식으로 제작하였습니다. ~~ 그 다음에 뭐라고 답변했는데 자세히 기억이 안 남..."},{"q":"그러면 그 주제를 고르게 된 이유가 있는지?","a":"고등학교 2학년 때 과학과제연구에서(과학융합이라고 잘 못 말할 뻔 어버법) 얼굴인식이 가능한 스마트 미러를 만드려다가 실패한 이후 얼굴인식을 이용해서 다른 무엇을 할 수 있을 지 생각하다가 얼굴 인식이 가능한 자동차 자동문을 만들기로 결정하였습니다.( 이런 식으로 말했던 것 같음)"},{"q":"미적분 시간에 푸리에 급수랑 ~~~~~~~~테일러 급수 ~~~ 유도과정을 정리했다고 했는데 ~~~해주시겠어요?","a":"네. 푸리에 급수는 주기함수를 무한 합으로 표현한 것으로, 사운드 처리 과정에 사용됩니다. 예를 들어, 푸리에 급수는 음성, 음악 기타 사운드 신호를 주파수 신호를 분해하는데 사용됩니다. 테일러 급수는 어떤 함수 f(x)를 어떤 점에서의 값과 여러 도함수들을 사용해서 초월함수를 다항식으로 만들어 (끄덕끄덕하심) 간단하게 만드는 수학적 방법입니다. 예를들면 sinx를 x로 바꿀 수 있습니다."},{"q":"그러면 푸리에 급수의 예시에 대해 설명하셨는데 테일러 급수의 예시는 뭐가 있나요?","a":"(약간 머뭇거리다가) 네 테일러 급수는 물리학에서 양자역학이나 상대론적식에 사용됩니다.(어버법ㅂ) 양자역학에선 파동함수식을 간단히 하기 위해 근사할 때 사용됩니다. 또 단진자 운동의 주기를 구할 때 사용할 수 있습니다."},{"q":"입학사정관님께서)미인정 지각과 질병관련 결석이 있는데 뭐 특별한 사유가 있나요?","a":"네. 고등학교 1학년에서 2학년으로 올라가면서 물리,화학,지구,생명 관련 과목이 늘어나다 보니까 학업적 부담으로 인해서 밤을 샌 적이 (어버버)많아졌습니다. 하지만 이 점이 성적에 악영향을(어버버) 끼친다는 것을 알고 고등학교 3학년으로 올라기전 방학에 이러한 습관을 고쳐서 현재까지 미인정 지각이 없도록 노력하였습니다."},{"q":"유체역학에 대해 학습하고 ~~~~했는데 유체의 정의가 뭐고 무엇을 학습했는지(?? 잘 기억이 안 남) 설명해주실 수 있나요?","a":"네. 유체는 담기는 통이나 공간의 부피에 따라 모양이 달라지는 것을 의미합니다. 제가 유체역학을 학습할 때 유체역학의 가장 대표적인 베르누이 법칙을 학습하였는데 베르누이 법칙은 유체의 압력과 퍼텐셜 에너지 더하기 운동에너지의 합이 일정하다는 것을 보여주는 법칙입니다( 끄덕끄덕하심) 이러한 베르누이 법칙을 통해서 유체의 속도가 빨라질 수록 압력이 낮아지고 유체의 속도가 느려질수록 압력이 높아집니다."},{"q":"보니까 영어 성적이 높은데 (약간 웃으시시면서) 자기 자신만의 영어 공부 비법 이런게 있을까요?","a":"아..하하(웃으면서,,,,) 우선 중학교 때 영어를 정말 못하는 학생이여서 이점..? 핸디캡같은 걸 받는 학생이였습니다. (끄덕끄덕 하심) 하지만 고등학교에 올라가기 전에 영어 점수를 올리고자 방학에 아침에 일어났을 때부터 잠들기 전까지 영어를 공부하고 영어 문법에 대한 기초를 바탕으로 해석하는 방법을 연습하였습니다. 결국 고등학교 1학년 때 선생님께 너는 정말 영어에 소질이 있구나라는 칭찬을 듣고 고등학교 3학년 때까지 영어에 대해서는 학업적 걱정이 없이 공부할 수 있었습니다. (마지막 답변 내용은 잘 기억 안 나는데 이런 식으로 말함. 이 답변 말하다가 시간이 삐삡빕비비빅 울려서 잠깐 멈칫했더니 교수님께서 아 계속 말씀하셔도 됩니다. 하셔서 계속 말했음...그래서 마지막으로 할 말 있는지 여쭤보시지 않았음!)후배들을 위한 조언 인하대 기계공학과 면접이 꼬리질문 같은 거 안 하는 것 같고 과학이나 미적분 개념 위주로 질문하는 것 같아. 그리고 성적 부분에서 교수님께서 진짜 궁금하신 게 있으면 물어보시는 것 같고 (성적이 일관되지 않고 하향하거나 상향하는 것처럼 특이점이 있을 때??) 그리고 그렇게 빡세지 않았던 것 같아서 긴장 풀어도 좋을 것같아...."}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(2권)」","year":"2025학년도"},{"univ":"인하대학교","dept":"식품영양학과","jeonhyeong":"학생부종합(인하미래인재)","method":"면접은 7분~8분동안 진행","notes":"","qa":[{"q":"학과에 지원한 동기 말해보세요.","a":"발효식품을 좋아하고 관심이 많아 발효식품이 우리몸에 미치는 영향에 대해서 탐구해봄->발효식품 속 프로바이오틱스가 장내에서 단쇄지방산을 분비하여 ph를 낮춤->유해균 억제+장내 미생물을 튼튼하게 해준다는 것을 탐구를 통해 알게됨->직접 프로바이오틱스 유산균을 먹어보며 효과를 몸으로 느낄 수 있었음->약으로도 치료가 힘든 것이 식품을 통해 치료가 되는 것을 보고 만성적인 질환을 치료하는 식품에 대해 연구하여 인류에 건강에 기여하고 싶어 인하대학교 식영과에 지원하게 됨"},{"q":"장점 및 자기소개 해보세요.","a":"성실함이 장점이라 이를 바탕으로 항상 노력하는 사람입니다."},{"q":"고령친화식품에 대해 관심이 많은 것 같아요 2학년 진로에 적혀있는 메디푸드가 뭔지,고령친화식품은 뭔지 자세하게 말해주세요","a":"메디푸드란 ~이고 종류에는 ~가 있다. 제 주위에는 크론병 걸린 친구가 있는데 소화후 장내 찌꺼기가 남지 않는 파우더와 물을 섞어 마시는 것을 보고 메디푸드가 우리 생활속에 생각보다 많다는 것을 느끼게 되었습니다. 대한민국은 고령화 사회로 접어들고 있어 고령친화 식품이 중요해졌습니다. 고령친화식품은 ~고 종류에는 연화식과 영양강화식이 있다 연화식에는 ~가 있고 영양강화식에는 ~가 있습니다."},{"q":"1학년 진로시간에 gmo에 대해 탐구했던데 gmo가 뭔지와 장단점에 대해 알려주세요.","a":"gmo는 생명공학기술을 통해 유전자를 변형한 생물을 뜻하며 장점은 ~ 이고 단점은 ~입니다."},{"q":"2학년 화학시간에 신소재를 통해 식품포장 방법에 대해 탐구했다고 하는데 무슨 활동인가요? 자세하게 말씀해주세요","a":"바이오플라스틱이라는 신소재를 탐구함 바이오플라스틱은 기존의 석유기반 플라스틱에 비해 ~점이 좋고 이를 이용해 식품포장재를 만든다면 지속가능한 식품산업에 일조할 수 있을 것 같습니다.(말하다가 타이머 울림)"},{"q":"마지막으로 하고 싶은 말 해보세요.","a":"학과에 입학하고자 하는 열정이 큰 인재이다.후배들을 위한 조언 -면접을 준비할 때 다른 사례들을 베끼기 보단 본인의 스토리를 녹이는 것이 중요함 그래야 외우기 쉽고 면접관들도 좋게 보실 것-본인 생기부 여러번 읽으면서 생기부에 있는 개념들+실험원리 모든 것 다 알고 있어야 면접때 어떤 질문이 나오더라도 대비하기 좋음"}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(2권)」","year":"2025학년도"},{"univ":"인하대학교","dept":"인공지능공학과","jeonhyeong":"학생부종합(인하미래인재)","method":"대기실 입장 -> 대기하면서 내 자료 보기-> 내 가번호 호출 -> 면접장 입장 -> 1학년 행발 질문 -> 물1질문-> 2학년 자율 질문 -> 1학년수학,2학년수학 질문 -> 2학년 행발 질문 -> 끝.지원동기, 마지막 말, 진로 바뀐이유 안물어보심, 7~8분간 진행..너무","notes":"빨리끝난느낌. 책상이 없으니 자세와 손 움직임 주의. 딱히 늦은 번호가 아니었는데도 빨리 끝내고 싶어하시는게 보임.","qa":[{"q":"1학년 행발에 축제 진행요원했었는데 다같이 하는 활동의 어려운 점, 극복 사례","a":"다같이 하는 활동의 경우 물론 장점도 단점도 있습니다. 학교에서 3년간 단체활동을 하며 여러 경우를 보았고, 장점을 극대화시키고 단점을 최소화시키는 방법을 배울 수 있었다고 생각합니다. 저는 모두의 참여를 적극적으로 만드는 것이 가장 어려웠습니다. 실제로 학급프로젝트를 진행할 때, 조장으로서 모두가 참여하게 만들기 위해 계속해서 커뮤니케이션하고 의견을 묻고 각각의 장점을 파악하려하였으며, 각자가 잘 할 수 있고 재밌게 할 수 있는 역할을 줌으로써 다같이 좋은 목표에 다가갈 수 있게 하였던거같습니다."},{"q":"물리학1 GPS원리에서 상대성 이론을 설명해보세요","a":"(다시 공부를 안해서 대답을 잘 못함) GPS가 지구상에 있는 저희와 달리 우주에 있기 때문에 중력의 영향을 받아 시간이 다르게 흐릅니다. 하지만 시간 별 위치를 정확히 측정해 알려야하는 GPS의 경우, 시간 오차가 치명적이기 때문에 상대성원리에 의해 발생한 시간 오차를 바로잡아야했습니다. 여기서 상대성 원리란 속도가 빛의 속도에 가까워질수록 시간이 느리게 흐르는것을 말합니다."},{"q":"2학년 자율 BCI기술 탐구를 하게 된 계기가?","a":"학교에서 했던 탐구활동 중 장애인을 위한 기술을 탐구한 적이 있습니다. 그때 팀원들과 의논끝에 시각장애인을 위한 ALT태그를 조사하였습니다. 탐구 주제 선정과정에서 다양한 기술들을 보았고 장애인분들을 위한 기술이 다양하다라는 생각을 하였습니다. 또한 그들의 삶에 많은 영향을 미칠 수 있을 것이라고 생각하였습니다. 때문에 이후 있었던 학술제에서 제가 탐구하며 느낀 점들을 전달하고 다같이 장애인분들을 위한 기술에 관심을 가져주었으면 하는 마음에 탐구를 진행하게 되었습니다."},{"q":"1학년 수학 순열조합 설명","a":"죄송합니다. 지금은 기억이 나지 않지만 이후 다시 공부해보록 하겠습니다."},{"q":"2학년 삼각함수 sin.cos 차이. 식. 공통점. 기억나는거 전부 말해봐라~","a":"싸인제곱 더하기 코싸인제곱은 1이다 라는 식이 문제를 풀 때 가장 많이 사용되는 것으로 알고 있고, 싸인함수는 원점대칭이고 코싸인함수가 y축대칭입니다. 싸인함수는 대각선분의 높이..코싸인함수는 대각선분의 밑변입니다.. 등"},{"q":"2학년 행발에 자신을 도전하는 사람이라고 설명. 구체적인 사례 있나요?","a":"저는 항상 새로운 분야에 도전하는 것을 좋아합니다. 때문에 1학년때부터 생명분야, 화학, 그리고 인공지능까지 여러 분야에 대해 알게 되었습니다. 어떻게 보면 쉽게 마음을 바꾸는 사람처럼 보일 수 있지만 이러한 성향덕분에 이 자리까지 올 수 있었고 여러 분야에 대한 정보와 경험을 가지고 인공지능 분야에서 활약할 수 있을 것이라고 생각합니다. (구체적인 사례가 기억이 안나서 나를 어필 할 수 있는 쪽으로 말함…)후배들을 위한 조언 생기부 공부를 꾸준히 하고 학과와 관련이 없어 보이는 물리 교과, 1-2학년 수학 내용까지 전부 숙지하세요. 면접은 내가 한 준비와 면접장에서의 기세에 걸려있다고 생각하고 자신을 믿으세요! 꼭 종이 자료 뽑아가기. 인하대에 일찍 가서 준비하고 싶으면 확실하게 일찍 가시길.. 주변 카페가 전부 면접보는 학생과 가족분들로 차 있음. 지원동기 안 물어보시면 다른 답변에서라도 엮어보려고 노력하세요! 화이팅 침착하고 떨리면 청심환먹으세요."}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(2권)」","year":"2025학년도"},{"univ":"인하대학교","dept":"전기전자공학부","jeonhyeong":"학생부종합(인하미래인재전형)","method":"-진로와 상관 없는 생기부 질문, 전공 관련 활동 질문을 번갈아가며 물어보심.-시간 끝나면 마지막으로 할 말*면접관 두 분1) 왼쪽 면접관님: 전공 관련 질문을 해줌.-미적분: 테일러급수 개념과 코딩 구현법, 나이브 베이즈 알고리즘 개념과 스팸메시지 분류기 제작 방법, 여러 프로젝트를 진행하면서 어떠한 어려움이 있었는지?, 해결한 방안은 무엇인지?","notes":"2) 오른쪽 면접관님 -진로 영어 발표 나는 누구인가에 대해 소개해주세오, 영어 1 iot와 smart city에 관한 발표에 대해 소개해주세요, 장점인 진취적인 성격이 학교생활에서 드러났거나 보여진 경험이 있나요?, 마지막으로 할 말 무엇인지?*생각보다 면접관과의 거리가 김. 교실 중간과 앞 문 정도","qa":[{"q":"진로영어 시간에 나는 누구인가에 대해 발표했다 했는데 소개좀 해주세요.","a":"저의 장단점과 공학자로서 어떠한 면모를 가졌는지 발표하였습니다 해당 발표에서 저는 강한 탐구력과 진취적인 성격을 가졌으며, 이를 통해 생기부엔 어떠한 활동을 했는지를 소개했으며 공학도로서도 좋은 면모를 가졌다는 것을 영어로 발표하였습니다. (당황하여 말을 좀 절고 횡설수설함)"},{"q":"미적분 시간에 테일러 급수에 대해 탐구하였다고 했는데 무엇인지, 이를 어떻게 코딩으로 구현했는지 설명해주세요.","a":"테일러 급수란 특정함수를 특정구간에서 다항함수로써 근사시킨 급수를 말합니다. 저는 그 중에서도 x=0 에서 테일러 급수인 매클로린 급수의 일반화 공식을 활용하여 sin, cos에 대해 시그마 팩토리얼 등을 적절히 코딩으로 구현하여 제작하였습니다."},{"q":"영어 시간에 스마트시티와 아이오티에 관한 발표를 했다고 했는데 소개 좀 해주세요.","a":"영어 교과시간에 스마트시티와 아이오티에 관한 내용이 담긴 지문이 나와 해당 개념들에 대해 소개하고 스마트시티의 예전 용어인 유비쿼터스 시티(컴퓨팅 빼먹음)에 대해 소개하였습니다."},{"q":"스팸메시지를 분류하는 기기를 제작했다고 했는데 여기서 사용된 나이브 베이즈 알고리즘이란 무엇이고 어떻게 활용했는지 설명해주세요.","a":"나이브 베이즈 알고리즘이란 베이즈 정리의 한 종류로 나이브한 가정을 하고 있다하여 나이브한 가정이란 모든 사건이 독립적이다라는 가정으로 이때문에 나이브 베이즈 알고리즘이라 불립니다. 저는 해당 탐구에서 파이썬과 오렌지3라는 데이터 마이닝 프로그램 두가지를 활용해 두가지 분류기를 제작해보았는데요. 데이터 전처리 방법인 TF-IDF 방식을 활용해 단어를 토큰화한 후에 나이브 베이즈 알고리즘에 대입하여 스팸을 분류할 수 있도록 하였습니다."},{"q":"앞서 장점이 진취적인 성격이라 하셨는데 이러한 성격이 학교 생활 내에서 드러나거나 했던 경험이 있나요?","a":"학교에서 리모컨이 자주 분실되는 사건에 대해서 진취적으로 실생활 문제를 해결해보고자 리모컨을 제작하는 활동을 해보았습니다 해당 활동을 통해 리모컨을 각 학급에 배치하였고 선생님들에게도 큰 호응을 얻었던 경험이 있습니다."},{"q":"여러 프로젝트를 진행하셨는데.. 어려웠던 경험이나 이를 해결하기 위해 했던 노력이 있다면 소개해주세요.","a":"앞써 말씀드린 리모컨 제작활동 중 실제 리모컨의 헥스코드를 수신받는 과정에서 어려움이 있었습니다. 제대로 수신받지 못하는 어려움이었는데요. 이를 해결하고자 리더로서 모둠원들에게 토론을 주도하여 여러 가설들을 세우게 하였고, 가설들 중 하나인 실제 리모컨의 제작연도와 아두이노 소프트웨어 라이브러리의 제작연도가 상충하여 호환성 문제가 생긴다는 것이 실제 문제 원인이라고 파악할 수 있었고, 라이브러리를 구버전으로 바꿈으로써 문제를 해결할 수 있었습니다."},{"q":"한 10~20초 정도 남았는데 마지막 할 말 있으면 하세요.","a":"저는 인하대학교 미래인재전형이 전문성, 창의성 미래지향적인 도전정신을 두루갖춘 인재를 선호한다고 알고있습니다. 저는 주행 충전이 가능한 자율주행모빌리티라는 미래지향적 목표를 가지고 여러 전문적이고 창의적인 탐구를 진행하며 제가 이러한 인재상에 적합한 인재라는 것을 뒷받침하였다고 생각합니다. 이에 저의 성장가능성을 충분히 고려해주시고 꼭 뽑아주셨으면 좋겠습니다. 감사합니다.후배들을 위한 조언 -꼬리 질문이 별로 없었지만 면접관에 따라 집요한 분들도 계신다고 한다. 면접이 수능 직후라 준비가 쉽지 않겠지만, 생기부에 적혀있는 모든 내용을 철저히 준비하자.-본인이 학창 생활을 하면서 인성을 드러낼 수 있었던 부분이나 어려움, 이를 해결했던 경험 등을 정리해서 숙지해두자. 화이팅"}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(2권)」","year":"2025학년도"},{"univ":"인하대학교","dept":"전기전자공학부","jeonhyeong":"학생부종합(인하미래인재전형들어가자 마자 긴장을 풀어주는 질문 → 타이머 6분 재고 시작 → 지)","method":"원동기 → 미적분 세특 → 확통 세특 → 2학년 진로활동 → 3학년 진로활동 → 수2 세특 → 수학 세특에서 실험이 많은 이유는? → 마지막 하고 싶은 말","notes":"교수님 1명, 입학사정관 1명 총 감독관 두 분","qa":[{"q":"점심 뭐 먹고 왔어요?","a":"주변 카페에서 간단하게 커피랑 빵 먹고 왔습니다."},{"q":"지원동기는?","a":"저는 전기전자공학의 ‘포괄성’이라는 학문적 특성이 제 탐구 역량을 가장 효과적으로 발휘할 수 있다고 생각하여 지원했습니다. 전기전자공학은 ‘지식’이라는 재료를 다각도의 응용을 통해 창의적인 산출물로 재생산한다는 점에서 매력을 지닌 학문이라고 생각합니다. 더불어 저는 고등학교 3년 동안 여러 분야의 이과적 지식을 창의적으로 융합하는 다양한 활동을 진행하였습니다. 일례로 저는 환경과 전기전자 분야를 접목하여 다양한 에너지 하베스팅 기술에 관심을 가지고 조사를 진행하였습니다. 그 결과 PCB형태 혹은 압전소재와 같이 다양한 방법을 활용한 기술 활용 방안을 모색할 수 있었습니다."},{"q":"미적분에서 수치해법에 관해 알아봤던데 무슨 활동을 했는지 말해주세요.","a":"수치해법이란 미분방정식의 해를 근사적으로 알아내는 방법입니다, 그리고 저는 오일러 방법에 관해 알아봤고 오일러 방법의 오차 누적 문제와 국소 오차 문제를 발견 이를 해결하기위해 4차 룬게-쿠타 방법에 관해 알아봤습니다. 그리고 이후 미적분학이 어떻게 일상에 쓰였는지 궁금해서 <미적분의 쓸모>라는 책을 독서하여 지식을 확장하였습니다."},{"q":"중심극한정리와 몬테카를로 방법에 관해 설명해주세요.","a":"우선 몬테카를로 방법이란 문제의 조건에 따라 난수를 이용하며 시뮬레이션 기법을 이용하여 문제의 근삿값을 구하는 확률적 기법입니다. 중심극한정리란 동일한 확률분포를 가진 독립 확률 변수 n이 적당히 크다면 정규분포에 가까워진다는 정립입니다."},{"q":"2학년 진로 활동에서 선인장 유무에 따른 사막화 유무를 판단하는 알고리즘에 관해 설명해보세요. 그리고 과적합 문제에 관해 설명해주세요.","a":"생명과학에서 배운 지표종의 개념을 활용해 선인장 유무에 따른 사막화 여부를 판단하는 알고리즘을 제작했습니다. 예를 들어 선인장이 없다면 사막화 그 반대 상황이라면 사막화가 아니라고 판단하는 알고리즘이었습니다 python을 이용하였고 layer를 통해 모델을 딥러닝 시켰습니다.과적합 문제란 머신러닝모델이 훈련 데이터에 지나치게 의존하여 불필요한 패턴까지 학습하여 발생하는 문제로 정규화, 교차검증의 방법으로 이를 해결하였습니다."},{"q":"3학년 진로활동에서 HBM 반도체에 관해 알아봤던데 조에서 자신의 역할은?","a":"저는 HBM의 공정과정에 관해 알아보는 역할을 맡았습니다. HBM공정에는 TSV공정의 이용되고 TSV공정이란 실리콘 웨이퍼 사이 구멍을 뚫어 금속을 채워 구리 배선으로 여연결하는 기술입니다. 이후 인공지능 반도체의 개념에 관해 알아봤습니다. 기존 반도체는 폰노이만 구조로 입력 로직반도체 메모리 반도체 로직 반도체 출력의 과정을 거치지만 인공지능 반도체란 해당 과정을 통합하여 효율성이 증가합니다."},{"q":"수학2에서 조사한 경사하강법과 진행한 실험에 관해 설명해주세요","a":"경사하강법은 함수의 기울기를 구해 기울기의 반대방향으로 이동해 극값을 찾는 알고리즘입니다. 그리고 저는 파이썬을 활용해 y=x^2의 함수를 가정해 해당 함수의 최적화에 관한 발표를 진행하였습니다."},{"q":"수학에서 실험을 많이 한 이유는?","a":"저는 수학 문제를 해결하는 것에서 흥미를 느끼기에 실험을 많이 진행했습니다. 이는 지식과 이론을 통해 응용을 하는 공학자가 가져야 할 태도와 비슷하다고 생각했기에 실험을 많이 진행하였습니다.후배들을 위한 조언 면접장에서 면접번호가 늦어 정말 많이 기다리면서 제 순번을 기다렸는데 그 시간에 봤던 내용중에서 질문이 들어왔습니다. 그런 남는 시간을 잘 이용해보세요. 그리고 말하기 연습을 많이 해보시고 수 과학 위주로 생기부를 보고 기초질문을 여러개 생각해보시고 답변을 만들어가세요. 그리고 답변할 때 최대한 외운 티 안나게 생각하면서 말하는 것처럼 말하면 좋습니다. 파이팅^^"}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(2권)」","year":"2025학년도"},{"univ":"인하대학교","dept":"전기전자공학부","jeonhyeong":"학생부종합(인하미래인재전형<전체적인 면접 흐름>정해진 시간까지 60주년 건물에 도착-> 입구에 도착하면 신분증과 수험표 검사 후 입장-> 안내에 따라 대기실에 도착 후 면접 순서 대기-> 면접 진행-> 면접 진행 후 번호표 반납 후 귀가)","method":"<면접 질문 관련>가산기 관련 질문-> 불대수 덧셈 법칙-> 불대수 개념-> 로피탈 개념-> 전력 효율성 관련 질문(ESS)-> ESS의 전력 효율성 증가 방법 관련 질문-> 미적분(푸리에 급수) -> 유리수&무리수 개념 질문-> 인성 관련 질문(가산기 관련 실험) -> 마지막 말 이전 타임의 면접이 끝나기 전까지는 60주년 건물 내로 입장이","notes":"불가능하므로 너무 빡빡하게 시간 맞추어서 도착하지 않으셔도 될 것 같습니다.","qa":[{"q":"여러 논리회로에 대한 탐구를 진행하신 것 같아보이는데 exclusive-or 게이트에 대해서 설명해주세요.","a":"입력 A, B를 가정한 다음 전기적 신호가 게이트에 입력된 것을 1로, 전기적 신호가 입력되지 않음을 0으로 가정한 다음 이를 이용하여 XOR 게이트의 진리표와 출력을 말을 통해서 묘사를 진행했습니다."},{"q":"불대수의 덧셈 법칙에 대해서 아는 바가 있나요?","a":"불대수에 대해서 탐구를 진행하면서 전반적인 불대수 법칙에 대해서 접한 적은 있지만 대략적인 내용에 대해서 탐구를 진행하였을 뿐 심층적인 내용에 대해서 다룬 적은 없기 떄문에 자세한 내용은 모르겠습니다."},{"q":"불대수가 일반적인 대수와는 다르게 가지는 차이점은 무엇인가요?","a":"불대수는 일반적으로 전자기기나 컴퓨터에 적용되는 대수로 불대수는 일반적인 수학적 표현법과는 달리 오직 참(1)과 거짓(0), 두 가지의 논리값만 가지는 대수입니다."},{"q":"로피탈에 대해서 설명해주실 수 있나요?","a":"로피탈은 미분을 통해서 그 값을 나타내는 것으로 알고 있습니다."},{"q":"전력의 효율성과 관련하여 다양한 활동을 하신 것으로 보이는데 전력의 효율성을 증가시킬 수 있는 방법이 있을까요?","a":"ESS에 대해서 언급한 후 ESS가 발전소에서 생산한 전기를 저장하고 필요할 때마다 사용함으로써 전기를 효율적으로 관리할 수 있는 시스템임을 설명했습니다."},{"q":"전력을 저장시키고 이를 다시 이용하는 과정에서 전력의 손실이 존재할텐데 ESS가 정확히 어떠한 방법으로 전기를 효율적으로 관리할 수 있나요?","a":"태양광에너지와 연관하여 태양광발전기는 낮 동안에는 작동할 수 있고 밤에는 작동할 수 없는 점을 고려하여 낮 동안에 저장해놓은 전기를 밤에 사용함으로써 전기를 효율적으로 관리 및 사용할 수 있다고 설명했습니다."},{"q":"미적분 과목에서 푸리에 급수에 대해서 알고 있으신가요?","a":"그 부분 쪽으로 심층적인 탐구를 진행해본 적이 없어 아는 바가 없습니다."},{"q":"유리수와 무리수에 대해서 알고 계시는가요?","a":"(생각하지 못한 질문이어서 당황하여 정확하게 설명하지 못하였음) 유리수는 실수에서 정의되고 무리수는 다른 것으로 알고 있습니다."},{"q":"(행발) 이과적 두뇌 회전이 탁월하다는 점이 언급되어있는데 특별히 이러한 능력을 발휘한 활동이나 실험이 있나요?","a":"4bit 리플 계산기 제작 활동에 대해서 언급하면서 전체적인 실험을 어떻게 진행하였는지와 실험 과정에서 발견한 문제점을 이후 carry look ahead를 추가적으로 제작함으로써 해결하였다는 과정에 대해서 설명했습니다."},{"q":"마지막으로 하고 싶은 말이 있으신가요?","a":"인하대학교 전기전자공학부에 입학하여 저의 전자기학 기초 지식을 더욱 탄탄하게 쌓아 올린 다음 제가 관심있는 분야에 진출하여 저의 꿈을 펼쳐나가고 싶습니다와 같은 맥락으로 조금 더 내용이나 표현을 추가하여 이야기했습니다.후배들을 위한 조언 자신의 생기부 내용에 대한 숙지를 먼저 진행하고 나머지 추가적인 지식이나 세부적인 내용들을 추가적으로 붙여나가면서 면접 준비를 하면 괜찮을 것 같습니다. 이후에도 면접에 대한 긴장감을 줄이기 위해 학교 선생님들이나 친구들과 모의 면접을 해보거나 예상 질문에 대한 답변을 계속해서 입 밖으로 꺼내보면서 외우는 것이 좋을 것 같습니다. 하지만 생기부에 대한 숙지가 진행되어도 생기부 이외의 내용들에 대해서 물어볼 수도 있기 때문에 최대한 준비를 하시되 면접 도중에 모르거나 헷갈리는 내용이 나와도 먼저 당황하지 않는 점이 중요한 것 같습니다. 저도 충분히 더 추가적으로 설명할 수 있는 질문들이 나왔지만 면접 때 그러한 질문을 받을 것이라고 생각하지 못해 당황하여 제대로 답변하지 못한 질문들이 있기에 마음 상태를 잘 준비하시는 것이 중요하다고 생각합니다. 또 그리고 희망과 관련 지식에 대해서는 이름에 대해서도 자주 쓰이는 것 이외에 다른 표현에 대해 숙지를 해놓으시는 편이 좋으실 것 같습니다. 힘내시기를 바랍니다."}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(2권)」","year":"2025학년도"},{"univ":"인하대학교","dept":"첨단바이오의약학과","jeonhyeong":"학생부종합(인하미래인재)","method":"지원동기 → 학과와 꿈의 관련성 질문 → 꿈을 선정하게 된 이유 → 생명과학 질문 → 협업을 이끌어 본 경험 → 생명과학 질문 → AI 질문 → 생명과학 질문","notes":"없음","qa":[{"q":"자기소개 해보세요.","a":"류머티스 관절염 치료제를 만드는 신약개발 연구원이 되고싶다. 과학과제연구 시간에 염증반응에 탐구를 진행하면서 염증반응이 많은 질병의 매개가 됨을 알게 되었고 화학 사고들을 접하면서 분광법과 유독성 물질에 대한 탐구를 진행해 화학물질의 안정성에 관심을 가지게 됨 나의 장점인 창의력, 협업 능력, 사고력을 바탕으로 인하대에서 꿈을 키워 나가고 싶습니다."},{"q":"류머티스와 본 학과와의 관련성은?","a":"휴미라 휴미라는 TNF-alpha"},{"q":"그 정도면 괜찮습니다.","a":"아, 네."},{"q":"생기부에 류머티스 내용이 없는데 왜 자기소개에 썼나요?","a":"류머티스를 하게 된 이유는 3학년 과학과제연구시간에 염증반응에 대한 탐구를 하면서 섬유화를 일으키는 경로를 알게되었다. 염증은 통증을 불러일으켜 일상생활에 피해를 줄 뿐 아니라 서서히 몸을 좀먹는다는 사실을 알게되었고 무엇보다 해결해야 할 과제라고 생각했기 때문입니다."},{"q":"통증이 뇌로가는 경로?","a":"통증은 염증반응으로 인해 지방산이 프로스타글란딘이 생성되게 됨. 이 프로스타글란딘이 신경전달물질의 수용체 결합을 촉진하여 통증이 발생하게 됩니다."},{"q":"통증의 신경계 메커니즘을 아는가?","a":"잘 모르겠습니다."},{"q":"자기소개 협업 능력 언급이 있던데 고교 생활 중 협업 능력이 드러나는 사례","a":"과학전람회에서 주제 선정 과정에서 어려움이 있었다. 후배들에게 당시 가장 고민이었을 학생부 작성에 도움이 되도록 저의 팀원들의 생기부에 적은 과학적 원리를 바탕으로 주제를 선정한 사례 언급했습니다."},{"q":"항암제에 대해서 깊게 탐구한 것 같은데 말해보세요.","a":"다양한 항암제가 존재하는 것을 알고 있다. 그 중 관심 있는 것은 2세대 항암제인 표적항암제였다 표적항암제는 단일클론항체를 기반으로 암에서 특정적으로 나타나는 EPR효과가 발생하는 환경과 같은 특징이 있으므로 표적이 된다."},{"q":"AI 내용 있는데 어떤 연관성?","a":"AI는 신약의 스크리닝 과정의 시간을 획기적으로 단축할 수 있으며, 앞으로의 세대에서없어서는 안될 것입니다."},{"q":"왜 없어서는 안되나요?","a":"앞으로는 개인 맞춤 창약의 시대가 열릴 것 그 수요를 충족하기 위해서는 AI의 도움으로 빠르게 신약을 창약하는 것은 필수적일 것이다."},{"q":"면역체계에 관심 많아 보인다. 노화의 발생기전을 면역과 관련지어 설명","a":"노화는 세포가 세포자멸사를 하지 못하고 늙은 세포가 많이 존재하는 현상을 말한다. 면역체계는 이 세포자멸사를 유도하기 위해서 염증반응을 생성해낸다. 염증 반응은 면역세포를 불러일으키며 염증성 사이토카인을 분비하여 더욱 많은 면역세포를 불러일으켜 세포의 세대 교체를 이루어낸다. 하지만 과다하게 염증반응이 분비가 되면 조골세포와 같은 세대 교체를 하는 과정보다 파골 세포 등의 작용이 심해져 노화가 촉진된다. 후배들을 위한 조언 생명과학 질문을 많이 하시고 학과와 생기부 속의 내용의 연관성을 많이 물어보심. 화이팅!!"}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(2권)」","year":"2025학년도"},{"univ":"인하대학교","dept":"통계학과","jeonhyeong":"학생부종합(인하미래인재행특에서 질문 → 봉사활동 질문 → 진로활동 질문 → 동아리 질문 →)","method":"심화수학 질문 → 생명과학1 질문- 입실 완료 후 30분 후에 면접 진행- 1인당 10분씩 면접 진행- 면접관 2명","notes":"수험표랑 신분증 꼭 들고 가기휴대폰, 태블릿 등 전자기기 다 제출해야함.","qa":[{"q":"‘정직’을 가장 중요한 가치라고 생각했다던데, 아직도 그렇게 생각하나요?","a":"네. 아직 그렇게 생각합니다."},{"q":"그럼 최근에 중요하게 생각하는 가치가 또 있나요?","a":"최근에는 성실이라는 가치를 중요하다고 생각합니다. 최근 입시를 하면서 성실한 마음가짐으로 임하면 좋은 결과가 따를것이라고 생각하고 있기 때문입니다."},{"q":"선후배간의 멘토멘티를 진행하면서 어려웠던 점이 있다면 말해주세요. 그리고 그 문제를 어떻게 해결했는지 말해주세요.","a":"후배에게 작년에 배웠던 내용을 가르쳐야했기 때문에 기억이 나지 않는 개념이나 문제들이 있을때가 가장 어려웠습니다. 이런 어려운일이 있을 때에는 작년 수학선생님을 찾아가서 후배가 질문한 문제를 함께 고민하며 문제를 해결했던 경험이 있습니다."},{"q":"3학년때 회귀분석과 분산분석에 대해 탐구했던데, 회귀분석과 분산분석의 유사성은 무엇인가요?","a":"회귀분석과 분산분석 모두 변수간의 관계를 설명한다는 점에서 유사성이 있다고 생각합니다."},{"q":"분산분석에 대해 탐구한 내용을 소개해주세요.","a":"이 활동을 하게 된 계기는 전에 회귀분석을 진행하면서 회귀분석과 분산분석이 변수 간의 관계를 설명한다는 점에서 유사성이 있다는 사실을 알게 되어 분산분석을 진행하게 되었습니다. 활동을 하면서 분산분석의 개념을 익히기 위해 책 ‘제대로 시작하는 기초 통계학’ 이라는 책을 참고하여 개념을 익혔습니다. 또한 이 개념을 실제 문제에 적용시켜보기 위해 엑셀을 활용하여 여러 편의점 만족도를 비교해보았습니다. 따라서 편의점 만족도 간의 차이가 있다는 결론을 낼 수 있었습니다."},{"q":"동아리에서 통계포스터를 만들면서 ‘AI 리터러시’라는 주제로 통계 포스터를 만들었던데, 이 활동을 하게 된 계기와 활동 내용을 말해주세요.","a":"이 활동을 시작하게 된 계기는 AI 리터러시의 중요성이 점점 강조되고 있다는 기사를 접했기 때문입니다. 이를 계기로 우리 학교 학생들의 AI 리터러시 실태를 파악하고자 통계 포스터를 제작하게 되었습니다. 활동을 진행하는 과정에서 네 가지 가설을 설정하고, 설문조사 결과를 바탕으로 각 가설을 검증했습니다. 예를 들어, “AI를 자주 사용할수록 AI 의존도가 높아질 것이다“라는 가설을 검증하기 위해 다양한 방법을 고민하다가 이 가설이 두 변수 간의 상관관계를 설명하고 있다는 점을 활용하여 회귀분석을 진행하였습니다."},{"q":"확률밀도함수와 적분에 대해 탐구한 내용을 설명해주세요.","a":"적분에 대해 배우고 정적분을 이용하여 그래프 아래 부분의 넓이를 구하는 것이 연속확률변수의 확률을 구하는 것과 관련있다는 점을 활용하여 확률밀도함수의 적분에 대한 탐구를 진행했었습니다. 확률밀도함수의 적분을 이용해 연속확률변수의 평균, 분산, 표준편차를 구해보았습니다. 또한 실생활에서 활용될 때에는 직접 적분하기 어려운 함수가 많이 사용된다는 것을 알고, 프로그램을 활용하여 적분하고자 했습니다. 이 활동을 통해 확률밀도함수와 적분의 관련성을 이해할 수 있었습니다."},{"q":"생명과학1에서 ‘쉽게 풀어쓴 생물통계학’이라는 책을 읽었다는데, 가장 인상깊었던 부분을 말해주세요.","a":"생물통계학에 대해 탐구하면서 생물통계학의 전반적인 내용을 이해하기 위해 이 책을 읽게 되었습니다. 그 중에서도 가장 인상깊었던 부분은 유전자 분석에 관한 내용이었는데, 이 부분에서 생물학의 복잡성을 통계학으로 설명할 수 있다는 점이 인상깊었기 때문에 기억에 남습니다.후배들을 위한 조언 생각보다 편안한 분위기에서 진행되었기 때문에 너무 많이 긴장하지 않는게 중요한것 같습니다. 면접 준비하면서 본인이 했던 활동 내용은 자세히 익혀두고, 관련된 개념까지 정확히 알아두면 좋을 것 같아요. 면접관의 기세에 눌리지 말고 무조건 내가 맞다는 생각으로 자신있게 대답하면 좋을 것 같아요!"}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(2권)」","year":"2025학년도"},{"univ":"인하대학교","dept":"화학공학과","jeonhyeong":"학생부종합(인하미래인재)","method":"면접 대기실에서 종이로 된 자료만 볼 수 있음 → 가번호가 호명되면 면접실로 이동 → 지원동기 → 전공질문 → 가장 기억에 남는 활동 질문 → 인성질문 → 7분 타이머 울리고 퇴실수험표 신분증 꼭 가져오기. 면접 대기실에서 전자기기 꺼야함.","notes":"입실 시간내에 입실완료하기. 수험번호나 이름 언급 안됨. 가번호로 자기소개하기","qa":[{"q":"인하대학교 화학공학과에 지원한 동기가 무엇인가?","a":"제가 인하대학교 화학공학과에 지원한 동기는 순수 화학을 넘어서 물리학, 생물학 등 다양한 학문과의 융합을 통해 현대사회가 직면한 문제를 해결하고 싶기 때문입니다. 저는 고등학교 시절 다양한 실험을 진행하면서 예상치 못한 결과가 도출되었을 때 변인과 가설을 재설정하며 문제해결능력을 길렀습니다. 또한 교과시간에 배운 과학 개념을 화학 분야와 연관지어 탐구하면서 융합적 사고 능력을 키워나갔습니다. 저의 이러한 역량들을 바탕으로 화학공학과에서의 연구를 통해 창의적이고 혁신적인 접근으로 인류의 건강과 환경에 기여하고 싶습니다."},{"q":"LCD화면에 대해 설명해봐라.","a":"LCD화면은 액정표시장치입니다. 백라이트에서 빛을 쏘면 편광판 사이로 들어가 영상을 표시합니다. 하지만 LCD화면은 시야각이 제한되어 있고 균일성이 없는 단점이 있습니다. 이를 보완하기 위해 나온 것이 OLED화면입니다. OLED화면은 시야각이 우수하고 모든 화면에서 빛이 동일하게 나와 균일성이 좋습니다."},{"q":"자신이 한 활동 중에 기억에 남는 것이 무엇인가?","a":"2학년 자율에서 미세플라스틱 속에 있는 화학물질이 세균에 미치는 영향에 대한 실험을 진행한 것이 가장 기억에 남습니다. 두 개의 배지를 준비해 미세플라스틱을 넣은 배지를 실험군으로 설정하여 대조군, 실험군 배지를 동일한 조건으로 배양시켰고 그 결과 미세플라스틱을 넣은 배지에서 대장균이 활발하게 증식했습니다. 이를 통해 미세플라스틱의 화학물질이 세균에 미치는 영향에 대해 알 수 있었습니다."},{"q":"깁스자유에너지 식에 대해 말해보세요.","a":"깁스자유에너지는 가역적 과정 속에서 뽑아낼 수 있는 유용한 에너지의 최댓값입니다. 깁스자유에너지 식은 G=H-TS입니다. 이때 G는 깁스자유에너지의 변화이고 H는 엔탈피의 변화, T는 절대온도, S는 엔트로피의 변화입니다."},{"q":"학창시절 어려움이나 갈등을 해결한 상황이 있나요?","a":"2학년 동아리에서 토론 주제를 선정하는데 있어 갈등이 있었습니다. 이때 제가 함께 읽은 책 내용과 현재 이슈화되고 있는 문제를 연관지어 토론 주제에 대한 의견을 내고 갈등을 중재했습니다. 후배들을 위한 조언 생기부 기반 면접으로 생기부 꼼꼼히 숙지하기, 면접 시간 7분으로 매우 짧음 → 지원동기에 자기소개(자신의 역량) 녹여서 하기"}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(2권)」","year":"2025학년도"},{"univ":"인하대학교","dept":"화학공학과","jeonhyeong":"학생부종합(인하미래인재)","method":"지원동기 → 생기부 관련 지식 질문 → 리더쉽 경험 질문 → 활동한 목적 질문","notes":"","qa":[{"q":"인하대학교 화학공학과에 지원한 동기를 말해주세요.","a":"저는 평소 호기심이 많아 지금 사용하는 물건이 어떻게 만들어졌는지 궁금했습니다. 고등학교에서 염료 감응형 태양전지 제작실험을 비롯한 다양한 실험을 하며 환경을 고려한 화학공정 등에 대한 지식을 기르는 등 관련 역량을 기르기 위해 노력했습니다.저는 끈기있는 태도로 탐구에 임할 수 있다는 장점을 가지고있습니다."},{"q":"어떤 신소재를 탐구했나요?(1학년)","a":"탄소나노튜브, 그래핀, 네오디뮴 자석 등을 조사하였습니다."},{"q":"탄소나노튜브에 대해 설명해주세요.","a":"탄소나노튜브는 탄소가 1개의 층으로 공유결합하여 원통형을 이루고 있는 구조의 신소재입니다."},{"q":"열의 일당량에 대해 설명해주세요.","a":""},{"q":"혼합 기체의 압력과 각 성분 기체의 압력 관계에 대해 설명해 주세요.","a":""},{"q":"리더쉽을 발휘한 경험에 대해 말해주세요.","a":"염료감응형태양전지 실험에 대해 이야기함."},{"q":"염료감응형태양전지를 실험하게 된 이유가 무엇이죠?","a":"실리콘 태양전지 말고 다른 태양전지에 대해 알게 되었고 사용화가 되지 않는 이유에 대해 탐구하고자 했기 때문입니다.후배들을 위한 조언 모르는 용어 없이 탐구 활동 꼼꼼히 살펴보고 열심히 준비해가야 합니다. 지원동기는 기본 질문인 것 같으니 꼭 준비해가세요. 편안한 분위기를 조성해주시니 긴장하지 말고 최선을 다하면 좋을 것 같습니다."}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(2권)」","year":"2025학년도"},{"univ":"인하대학교","dept":"환경공학과","jeonhyeong":"학생부종합(인하미래인재개인마다 정해진 입실시간에 맞춰 입실-> 대기실에서 안내사항)","method":"전달-> 가번호 순서대로 면접실 입실->면접 후 바로 귀가(면접 진행과정) 인사 후 착석-> 안내사항 듣고 면접 시작-> 지원동기-> 학생부기반 면접-> 마지막으로 하고 싶은 말면접 후 바로 귀가해야하니 짐을 꼼꼼히 챙기는 것이 좋음.","notes":"면접 당일 교내 차량이 너무 많아 일찍 가서 주차하고 기다리는 것을 추천함. 신분증을 꼭 지참해야 함.","qa":[{"q":"학생회활동을 많이 했는데, 본인의 역할에 대해 말해주세요.","a":"부장으로 일했던 것과 리더쉽, 문제해결능력 등에 대해 말함. 환경관련 활동에서 의견을 제시했던 것 등 실제 경험을 바탕으로 말함."},{"q":"(3학년 미적분) 뉴턴메소드가 뭐예요?","a":"뉴턴메소드의 정의에 대해 답변하고 보간법, 초깃값 설정 등 관련된 개념에 대해서도 대답함."},{"q":"(화학1) 비료가 토양과 식물의 생장에 미치는 영향에 대해 말해주세요.","a":"탐구의 동기, 과정, 결과 순서로 설명함. 읽었던 책과 탐구 내용을 바탕으로 답변함."},{"q":"(2학년 수학1) 삼각함수와 노이즈캔슬링 원리에 대해 설명해주세요.","a":"삼각함수에 대해 설명하고 파동의 종류와 삼각함수로의 표현에 대해 답함. 상쇄간섭을 이용해 외부노이즈를 감쇄하는 방식으로 노이즈캔슬링을 할 수 있다고 설명함."},{"q":"(수업량유연화) 미생물연료전지 원리에 대해 설명해주세요.","a":"미생물연료전지 정의와 원리에 대해 설명함."},{"q":"이차전지의 양극재와 음극재를 선정하여 새로운 이차전지를 고안했다고 했는데, 이에 대해 설명해주세요.","a":"전자의 이동속도를 개선하면 이차전지의 전력효율을 높일 수 있을것이라 생각하였고 이를 실현하기 위해서 양극재와 음극재를 새로 선정하였다고 답함. 양극재, 음극재로 새로 선정한 물질들에 대해 소개하고 이유에 대해 답변함."},{"q":"마지막으로 하고 싶은 말씀 하세요.","a":"저는 친환경전력 생산분야의 전문가가 되고 싶다는 꿈을 가지고 인하대 환경공학과에 지원하였습니다. 제 성격의 장점인 끈기와 성실함을 바탕으로 이 꿈을 이루고 싶습니다. 인하대학의 실용성 중심의 교육을 통해서 환경과 사회에 봉사하는 환경인재가 되고 싶습니다.후배들을 위한 조언 아무리 떨려도 면접관을 보고 본인 의견을 분명히 전달하는 것이 가장 중요하다고 생각하고 그러기 위해서는 말하는 연습을 많이 하는 것을 추천합니다.지원동기, 자기소개 등의 공통질문들은 따로 준비하지 말고 일맥상통하게 전하고자하는 내용을 정하고 질문 의도에 따라 조금씩 바꾸어 대답하는 것을 추천합니다."}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(2권)」","year":"2025학년도"},{"univ":"인하대학교","dept":"환경공학과","jeonhyeong":"학생부종합(인하미래인재전형· 지원동기)","method":"· 2학년 질문· 확통 질문· 2학년 질문","notes":"수험표, 신분증 챙겨가세요!","qa":[{"q":"2학년 때 주로 이차전지나 에너지 활동을 했던데 왜 전기전자공학과나, 이차전지공학과가 아니라 환경공학과에 지원했나요?","a":"이 때 지원동기 말했습니다."},{"q":"에너지를 다양한 분야에 접목시켰던데 그 중 하나에 대해 설명해주세요.","a":"물리학1 때 탐구한 열역학 1법칙, 화학1 때 수소에너지 설명했습니다"},{"q":"물리학1 교과 탐구내용에 대해 좀 더 자세히 설명해주세요.","a":"기억이 잘 안 나지만 어찌저찌 설명했습니다."},{"q":"수소 에너지 탐구 내용에 대해 자세히 설명해주세요.","a":"이것도 기억은 안 남지만 수소에너지 특징을 위주로 연료전지와 관련하여 설명했던 거 같습니다."},{"q":"확률과 통계교과에서 활동한 맥스웰 볼츠만 분포에 대한 질문","a":"잘 설명했습니다."},{"q":"2학년 때 각도에 따른 태양전지 효율 탐구 질문","a":"이것도 잘 답변했습니다.후배들을 위한 조언 2학년 준비를 상대적으로 덜 했는데, 1~3학년 웬만하면 꼼꼼히 다 보세요"}],"result":"","resultNote":"","src":"충청북도교육청 「2025 수시 면접 사례집(2권)」","year":"2025학년도"},{"univ":"인하대학교","dept":"경제학과","jeonhyeong":"학생부종합(인하미래인재오전 10시 10분에 입실 -> 오전 10시 40분 경 대기실 입장(전자기기)","method":"전원 끄고 비닐봉투에 넣음, 생기부 등 자료 확인 가능) -> 오전 11시 면접 시작 -> 면접 약 7분전 대기실 앞으로 호출 -> 바로 앞 번호학생 면접 기다린 후 -> 조교 분이 노크로 두드려 주시고 들어감생기부 및 면접 자료 미리 출력해갈 것, 면접에 이름 등 개인정보 발","notes":"언하지 않도록 주의할것, 면접 순서는 랜덤, 부여받은 번호표로 자신을 소개함","qa":[{"q":"2학년 수1 활동에서 산업분야의 로그함수를 활용한 내용이 있던데 어떤 예시가 있나요?","a":"제가 로그함수를 활용한 예시는 자본투입량과 노동생산량과의 관계를 구하는데, 은행에 원금을 넣을 떄 줄어드는 이자의 예시가 있습니다"},{"q":"2학년 수학2 활동에서 미분을 활용한 개념이 있는데 한계비용에 대해 설명해 주실수 있나요?","a":"제가 그 내용은 기억이 안나서 나중에 설명 드릴 수 있을까요"},{"q":"2학년 동아리에서 공매도 활동을 한 내용이 있던데 공매도가 지금 규제되고 있죠? 공매도가 규제되면 무슨 문제점이 발생할까요?","a":"공매도가 주식시장에 상장되기 전 주식을 살 수 있게 하는 제도를 의미하는데 이를 규제하면 투자하기가 상대적으로 어려워져 주식시장의 유동성 문제가 발생할 수 있습니다. 그리고 또한 외국인 투자자가 공매도가 정착되어 있는 지역을 선호하다 보니 외국인 투자자 유입이 감소되는 문제가 있습니다."},{"q":"2학년 자율에 esg경영 활동을 한 내용이 있던데 어떤 기업을 예시로 든 것 인가요?","a":"저는 맥도날드의 사례를 예로 들었는데요. 맥도날드에서는 지역사회 농산물을 자사의 햄버거의 재료로 사용함으로서 무역과정에서 발생하는 환경 오염을 방지하고 지역사회와 상생하며 이 수익을 소아암 환자를 위해 기부합니다"},{"q":"보니까 결석이나 조퇴가 많은데 특별한 이유가 있나요?","a":"제가 스트레스를 받을 떄 운동하면서 푸는 경향이 있는데 특히 농구를 하면서 많이 풀다보니 다리를 다치는 경우가 많아서 조퇴를 특히 많이 한거 같습니다"},{"q":"마지막으로 하고 싶은 말 있나요?","a":"저는 경제학자의 말로 마무리하고 싶은데요. 폴 사무얼슨에 따르면 ‘경제학은 너무 중요해서 경제학자만 알면 안된다’입니다. 저도 이에 동의하며 제 해박한 경제학 지식을 바탕으로 사람들의 합리적인 경제생활에 기여하는 경제 전문가로서 사회봉사를 실현할 것 입니다.후배들을 위한 조언 전공 관련 지식을 물어보는 경우가 있으니 이 점 유의하시기 바랍니다면접관분들이 온화하시며 저의 경우 압박 질문은 많이 없었습니다.면접 대기실에서 면접 자료를 볼 수 있으니 면접 자료를 가져가시기 바랍니다.면접 때 떨 수는 있으나 자기의 주장을 밀어 나가는 것이 중요합니다.2024 대입 면접후기"}],"result":"","resultNote":"","src":"충청북도교육청 「2025 대입 면접 후기집」","year":"2025학년도"},{"univ":"인하대학교","dept":"경영학과","jeonhyeong":"학생부종합(인하미래인재)","method":"아이스브레이킹->지원동기->대화중심 면접(대화 속에서 질문은 던지는 방식)->마지막으로 하고픈말입학사정관으로 보이시는 분께서 긴장된 분위기를 많이 풀어주시려고","notes":"합니다. 딱딱한 질문-대답구조의 면접형식이 아닌 대화위주로 이루어진 면접이었습니다. 입학사정관으로 보이는 분께서 긴장을 많이 풀어주려고 노력하셔서 준비한대로 편안하게 답해주시면 될것같습니다.","qa":[{"q":"많이 긴장되지는 않아요?","a":"조금 긴장됩니다(웃음)"},{"q":"8분정도 면접 진행됩니다. 질문 드릴테니까 최선을 다해서 말씀해주세요","a":"네!"},{"q":"지원동기 말씀해줄래요?","a":"저는 미래를 밝혀주는 ESG경영의 확대에 대해 고민하고있는 인하대학교 경영학과에 지원해보았습니다. 저는 고등학교 1학년때 경실련(경제정의실천시민연합)의 한 기사를 통해 ESG경영에 관심이 가게 된 학생입니다. 2030년부터는 모든 상장사에 대한 ESG공시가 의무화된다는 것을 접한 저는 ESG경영이라는 것이 무엇이며 관련 탐구를 진행해보았습니다. 고등학교 재학시절동안 ESG경영이 무엇인지와 관련 활동을 진행해보았는데요, E에 있어서는 환경평가지표활동, S에는 베리어프리 키오스크 제작활동, G로는 플랫폼노동자를 위한 조직부서만들기활동을 진행해보았습니다. 3년간 진행해본 결과 결국 ESG경영이라는 것이 많은 비용이 발생함을 알았으며 저는 그 중 세무적인 관점에서 기업의 ESG경영 부담을 완화시켜 주는 컨설턴트가 되고자 인하대학교 경영학과에 지원하였습니다."},{"q":"알겠습니다. 행동특기사항에서 흥미로운점이 있어서 여쭤볼게요. 성적이 유독 높은것으로 보이는데도 불구하고 친구들을 학업적으로 많이 도와주었다고 나오네요. 어떻게 이루셨다고 생각하나요?","a":"도와주는 과정에서 친구들이 학업적으로 성취감을 느끼는 모습에서 많은 뿌듯함을 느꼈습니다. 또한 학업적으로 누군가를 도와주면서 저 또한 복습의 장점이 있어 일석이조의 효과가 있던 봉사활동이라고 생각합니다."},{"q":"그렇죠. 저도 그렇게 생각합니다. 또 1학년때부터 여러 ESG에 대해 탐구했네요. 결국 손해를 보는것을 감수하고라도 이러한 경영전략을 해야한다는것인데 ESG의 가치가 앞으로 어떻게 변할것같나요?","a":"이제는 재무적인 평가요소뿐만이 아닌 비재무적인 요소까지 포함해서 기업의 투자를 결정하는 시대가 온 만큼 미래의 기업의 평가에 있어서 중요한 척도로 작용할 것이라고 생각합니다. ESG는 앞으로 미래의 경영전략산업에 있어서 무궁무진한 가치가 있을것으로 생각됩니다."},{"q":"문학시간에 ‘난쟁이가 쏘아올린 작은 공’에 대해서 탐구하였다고 나오는데 이 작품과 경영학간의 관계가 무엇이 있을까요?","a":"답변드리겠습니다. 우선 ‘난쟁이가 쏘아올린 작은 공’은 산업화시기에 사회적으로 소외된 약자계층에 대해 말하는 작품입니다(두분다 고개를 끄덕임). 이러한 작품과 경영학간의 관계로는 경영내 사람의 채용과정에서 장애인과 비장애인의 기준을 두어서는 안된다고 생각합니다. 사회적약자라는 이유만으로 비장애인과 차등성있는 채용과정을 두게 된다면 바람직하지 못하다고 생각되기에 이러한 점에서 앞 서말한 문학작품과 경영학 이 둘 사이의 관계가 이어질것이라고 생각합니다."},{"q":"체육세특에 벤포드법칙이 적혀있는데 이게 뭔가요?","a":"네, 벤포드 법칙이란 자연수의 맨 앞자리 수가 반복되며 통계적으로 법칙화된 수학법칙으로 알고있습니다."},{"q":"이것이 활용되는 분야는 어디일까요?","a":"(생기부 기반 내용) 네 기업의 회계조작에 대해 밝혀내는 역할도 할 수 있으며 주식가격동안 벤포드 법칙을 통해 조작의 유무를 밝혀낼 수 있다고 알고있습니다."},{"q":"이제 시간이 다 돼가네요. 마지막으로 하고싶은말 해볼까요?","a":"저는 ESG경영이라는 것이 단순히 유행 때문에 이를 조사하고 탐구해왔던 것이 아닙니다. ESG가 지닌 가치에 대해 공감하고 싶은 사람이 되고자 인하대학교 경영학과에 와서 여러 기업과 사람들이 상생할 수 있는 공동체에 기여하고자합니다. 인하대학교에 오게된다면 ‘윤리적 비전’과 ‘글로벌 마인드’를 겸비한 인재로 거듭나가기위해 열심히 노력하겠습니다. 감사합니다.(학과 인재상 언급)후배들을 위한 조언 면접의 전반적인 분위기가 편안함. 수학적인 개념 및 특정 사회현상의 개념에 대해 물어볼 수 있음. 자신의 학생부 모든 과세특에 대해서 간단한 용어정리 및 간략한 소개정도는 충분히 할 수 있어야함.2024 대입 면접후기"}],"result":"","resultNote":"","src":"충청북도교육청 「2025 대입 면접 후기집」","year":"2025학년도"},{"univ":"인하대학교","dept":"고분자공학과","jeonhyeong":"학생부종합(인하미래인재)","method":"동아리 질문(3학년)→전공 적합성 질문(2~3학년)→자율 활동 질문(3학년)→마지막 질문","notes":"수험표 및 신분증 잘 챙기기대기 시간 중 전자기기 일체 사용 금지(사용 시 부정행위)","qa":[{"q":"3학년 동아리 활동으로 르샤틀리에 원리에 대해 탐구했는데 르샤틀리에 원리에 대해 간단히 설명해주시고 탐구 과정을 소개해주세요.","a":"르샤틀리에 원리는 평형 상태에 있는 가역 반응이 농도 변화, 온도 변화와 같이 외부요인에 의해서 변하게 되면 새로운 평형 상태에 도달하게 되는 반응입니다. 저는 아세트산 용액과 아세트산 나트륨으로 실험을 진행했습니다. 두 용액 모두 산이기 때문에섞게 되면 pH가 더 감소할 것이라고 예상했습니다. 하지만 아세트산 나트륨은 염이기때문에 용액 내에서 완전히 해리되지만 아세트산 용액은 부분적으로 해리됩니다. 때문에 실험을 계속 진행하면 용액 내의 아세트산 이온이 증가하여 이를 감소하는 방향인역방향이 일어나게 되어 pH가 증가하게 됩니다."},{"q":"생기부를 보니 화학 전지에 대해 많이 탐구 및 실험을 하셨던데 화학 전지가 저희 학과와 어떠한 연관이 있는지 말씀해주세요.","a":"화학 전지는 화학 반응 중 산화환원반응을 이용하여 전기를 생산합니다. 하지만 이러한원리가 고분자 공학과에 어떤 연관이 있는지에 대해서는 잘 모르겠습니다."},{"q":"3학년 학급회 복지부 부장을 맡아서 학급 환경 개선을 위해 노력했다고 했는데 어떤 사업을 진행했는지 설명해주세요.","a":"저는 우산 빌려주기 사업이 가장 기억에 남았습니다. 비가 오는 날 친구들이 우산을 빌려가 비를 맞지 않는 모습과 다음날 잘 썼다고, 덕분에 비를 맞지 않을 수 있었다는 말을 들었을 때 뿌듯함을 느꼈습니다."},{"q":"마지막으로 하고 싶은 말이 있을까요? 10초 정도 드리겠습니다.","a":"2학년 동아리 활동과 관련하여 말하지 못한 것이 있습니다. 농도와 반응속도의 상관관계에 대해 탐구를 할 때 반응속도가 아닌 반응까지 걸리는 시간에 대해 구하여 보고서의 완성도가 떨어졌습니다. 이러한 경험을 바탕으로 3학년 동아리 활동에서는 온도와 반응속도의 상관관계에 대한 보고서에서는 반응속도를 구해 보고서의 완성도를 높여 결과가 만족스러웠습니다.후배들을 위한 조언 지원동기는 저와 선생님을 비롯해 무조건 나올 것이라고 생각해 당연히 면접 직전까지 달달 외우고 갔습니다. 하지만 막상 면접이 진행되니 지원동기는 물론 대학교에 대한 그 어떤 질문도 안 받았습니다. 저는 당황하여 흔히 말해 멘탈이 나갔고 이후 질문에 제대로 답변을 하지 못했습니다. 후배님들은 이런 사소한 상황에도 대비하여 면접 준비를 잘 하시길 바랍니다. 그리고 생기부에 전공과 관련된 이론들은 무조건 정확히 외우고 가는 것이 기본입니다. 꼬리 질문이 무조건 나옵니다. 마지막으로 면접 대기 시간 중에는 전자기기 사용이 불가하니 면접 대비 자료는 종이로 프린트해 가시길 바랍니다. 후배님들 파이팅하세요.2024 대입 면접후기"}],"result":"","resultNote":"","src":"충청북도교육청 「2025 대입 면접 후기집」","year":"2025학년도"},{"univ":"인하대학교","dept":"기계공학과","jeonhyeong":"학생부종합(미래인하인재호기심 천국에서 중력파에 대해서 발표했다는데 관련해서 설명해 보세요. -> 프로그래밍 시간에 물리교과에서 배운내용을 바탕으로 자동차)","method":"의 제동거리를 구하는 프로그램을 만들었다는데 관련된 물리이론과 과정을 말해주세요. -> 도함수의 개형을 활용하여 함수의 증가와 감소를 확인하고, 미분계수가 0인 점이 항상 극값을 가지는 것이 아니라는 것을 예를 통해 제시했다는데 한번 예를 들어 설명해 보세요.내용은 적은게 맞지만 그때 살짝 정신이 없어서 말을 제대로 했는지","notes":"기억 안남 그래도 밑에 적은 내용이랑 매우 유사함면접시간은 7분으로 제한되어 있었음 그래서 말을 좀 더듬으면서 대답했더니 시간을 좀 많이 써서 질문을 3개 밖에 못 받음","qa":[{"q":"호기심 천국에서 중력파에 대해서 발표했다는데 관련된 내용을 설명해 주세요.","a":"네. 우선 아이슈타인의 상대성이론에서는 질량이 클수록 중력이 크고 시공간 왜곡이 크다고 합니다. 그리고 이 때 만약 매우 큰 질량 변화가 생기면 그 질량변화로 인해 중력이 변하여 주변 시공간이 왜곡되는데 이 때 이 시공간왜곡이 파동처럼 퍼져 나가는 것이 중력파입니다. 이 중력파는 라이고라는 기계를 이용하여 측정할 수 있는데요. ~~ 레이저의 파동 간섭이 사용된 라이고 원리 설명하고 라이고 안에서 페브리 페르관을 이용해 빛의 경로를 늘려 주었을 때 얻는 효과에 대해 어버버하며 설명"},{"q":"프로그래밍 시간에 물리교과에서 배운내용을 바탕으로 자동차의 제동거리를 구하는 프로그램을 만들었다는데 관련된 물리이론과 과정을 말해주세요.","a":"네. 저는 우선 이 프로그램을 만들기 전에 자동차가 제동을 시작한 후 정지할 때까지 속력이 일정하게 감소한다고 가정 한 후 프로그램을 만들었습니다. (이때 다음 뭘 말해야 할까? 머리 속에서 엉켜서 잠시 생각을 정리할 시간을 주실 수 있나요? 말하고 한 5초 뒤 말을 이어감) 이 때 자동차의 제동거리를 구하는 방법은 속도가 일정하게 감소하는 운동이기 때문에 처음 속도 더하기 나중속도인 0 그리고 나누기 2를 하여 평속을 구하고 그 후 시간을 곱하여 자동차의 제동거리를 구하였습니다. 제가 프로그래밍을 잘 하진 못하여서 프로그램을 만들 때 간단한 사칙연산을 이용하여 프로그래밍 하였습니다. (이때 면접관님께서 제가 물리교과에서 배운내용을 애매모호하게 말해서 “그럼 자동차가 제동할 때 속력이 일정하게 감소한다고 가정하였다고 했는데 이 운동은 등속도 운동인가요, 아님 등가속도 운동인가요?” 라고 물으셔서 바로 등가속도 운동입니다. 라고 말함)"},{"q":"도함수의 개형을 활용하여 함수의 증가와 감소를 확인하고, 미분계수가 0인 점이 항상 극값을 가지는 것이 아니라는 것을 예를 통해 제시했다는데 한번 예를 들어 설명해 보세요.","a":"(처음에 질문 듣고 머릿속에서 어떻게 답변할지 정리하느라 시간이 좀 걸릴거 같아서 면접관님에게 질문을 한번만 더 말씀해 주실수 있나요? 부탁함 ) 보통 학생들이 미분을 처음 배울 때 미분계수가 0이 되면 극값을 가진다 라고 오해를 많이 합니다. 하지만 미분계수가 0일 때 극값을 갖는 경우는 도함수가 x 축을 통과하여 마이너스에서 플러스가 되거나 플러스에서 마이너스가 될 때입니다. 예를 들어 도함수가 2차함수라면 이 2차함수가 x축을 통과하지 않고 접하게 된다면 이때는 미분계수가 0이지만 극값을 갖지않고 변곡점을 가지게 됩니다.....후배들을 위한 조언 본인은 수능끝나고 놀다가 면접준비를 많이 하지 못했는데 후배님들은 부디 9월에 수시 넣는 순간부터 면접 말하기 연습까지는 아니더라도 본인의 생기부에 적힌 활동이 무슨 내용이고 어떤 개념인지 정도는 정리해 두면 좋음. 그리고 수능공부하면서 학교에서 선생님이 모의면접해주신다고 하면 그때마다 면접연습해보고 꼭 참여하면 좋음. 만약 인하대 면접 준비하는 친구들이 이것을 본다면 인하대 면접은 생각보다 매우 무난하고 빡세지 않음. 보니까 그냥 생기부내용 물어보면서 본인이 진짜 이 활동을 하고 이 내용을 이해했는지 정도만 확인 하는 것 같음. 본인을 말을 되게 못해서 뭔가 설명을 할 때 내용은 알아도 머릿속에서 정리가 잘 안되서 말을 전달하는데 조금 오래걸리고 약간 말이 왔다갔다함. 그러니 만약 본인이 말을 잘 못하는 학생이라면 면접연습할 때 연습이니까 말하는데 오래걸리더라도 말을 깔끔하게 하는 연습을 하면 좋을 것 같음. 나처럼 하면 면접질문 몇 개 못받고 끝날 수 있음. 뭐가 됐든 인하대 면접 준비하는 친구들은 긴장 많이 안해도 될 것 같고 파이팅 했으면 좋겠음. 2024 대입 면접후기"}],"result":"","resultNote":"","src":"충청북도교육청 「2025 대입 면접 후기집」","year":"2025학년도"},{"univ":"인하대학교","dept":"문화콘텐츠문화경영학과","jeonhyeong":"학생부종합(인하미래인재가번호 확인 ⇀ 난쏘공 모둠 토론 질문 ⇀ 요즘 영상의 길이 질문 ⇀)","method":"짧은 영상에 대한 부정적인 견해 질문 ⇀ <운영전> 갈래 바꿔쓰기 질문 ⇀ 백남준 관련 질문 ⇀ (학교 포커스) 왜 인하대 해당 학과 선택했는지 질문 ⇀ 마지막 할 말- 대기실 입실 후 안내를 받은 이후에는 핸드폰 사용 금지보관팩을 나눠주고, 전원을 끈 뒤 해당 보관팩에 넣은 뒤 가방에","notes":"보관하라고 안내 (보관팩 크기가 작아 태블릿 PC는 안 들어감)- 교수님 2인이 면접 진행- 가번호는 목걸이 형식으로 입실 전 착용하는 형식- 기본 질문 1 : 생기부 9","qa":[{"q":"안녕하세요, 가번호 XXX맞죠?","a":"네, 맞습니다. 가번호 XXX입니다."},{"q":"바로 들어갈게요, 난장이가 쏘아올린 작은 공을 읽고, 모둠 토론을 했다고 하는데 활동 설명좀 해줄래요?","a":"네, 난장이가 쏘아올린 작은 공이라는 책을 6-7인 정도의 구성원이 함께 읽고 책에서 질문을 뽑아내어 해당 질문에 대해 짧은 모둠 토론을 하는 활동이었습니다. 저는 토론 진행자를 맡아, ‘기존의 삶의 터전을 파괴하는 도시 재개발은 올바른가?’라는 질문을 조원이 이야기했을 때 이러한 질문에 관해 발언권을 부여하여 토론을 진행하고, 나아가 해당 질문은 교과에서 배우는 공리주의 개념과 연계하여 ‘다수의 이익을 위한 소수의 희생은 정당한가?’ 등의 질문으로 발전시켰던 기억이 납니다."},{"q":"요즘 영상의 길이가 짧아지고 있다고 생각하는 것 같은데, 지금도 그런 생각인가요?","a":"네, 맞습니다. 현재에도 숏폼 형태의 짧은 영상이 주를 이루고 있다고 생각합니다."},{"q":"그런데, 그게 안 좋은건가요?","a":"숏폼에 관해 연구한 한 논문을 본 적이 있습니다. 해당 논문에서는 숏폼 형태의 영상은 어떠한 정보나 감정을 짧은 시간내에 풀어내야 하기에 더욱 자극적일 수밖에 없고, 일정 시간 내 소비하는 영상의 개수가 긴 영상보다 짧은 영상이 압도적으로 많기 때문에 그러한 수용에도 영향을 끼친다고 말하였던 것 같습니다. 저는 이러한 내용에 전적으로 동의하며 숏폼 형태의 영상은 분명히 단점이 존재한다고 생각합니다."},{"q":"<운영전>을 트랜스미디어 갈래 바꿔쓰기를 했다고 하는데, 이게 뭔가요?","a":"<운영전>이라는 우리나라 고전 소설을 뮤지컬의 형식으로 갈래를 바꿔 구성한 활동이었습니다. 표면적으로는 사랑 이야기이지만, 실제 하고픈 이야기는 당대 사회를 비판하는 것이며 그렇기에 이중 액자식 구조를 가지는 <운영전>의 특징을 고려하여, ‘유영’이라는 인물에게 서사극의 해설자 역할을 부여하여 뮤지컬로 갈래를 바꾼다면 관객들이 작품의 본래 메시지인 사회 비판에 더 잘 집중하는 일종의 ‘낯설게 하기’ 효과를 얻을 수 있을 것 같아 뮤지컬을 택하였습니다."},{"q":"낯설게 하기를 의도하여 뮤지컬을 택했다는 건가요?","a":"네, 맞습니다. 관객들의 인물의 사랑이야기에만 집중한다면, 작품의 본래 메시지에는 도달하지 못하리라 생각했습니다. 그렇기에 극과 관객 사이에 어떠한 거리가 존재해야 한다고 생각했고, 그것을 바로 서사극의 해설자 역할인 ‘유영’의 낯설게 하기를 통해 얻을 수 있겠다고 생각하여 그렇게 진행하였습니다."},{"q":"백남준 전시도 보고온 것 같은데, 무슨 생각을 했나요?","a":"네, 백남준 작가의 ‘다다익선’이라는 작품이 가장 기억에 남습니다. 처음 작품을 본 감상은 단순히 ‘웅장하다’ 정도였습니다. 시간을 두고 천천히 작품을 감상하던 중 TV에 재생되는 화면에 집중할 수 있었는데, 화면에는 우리나라 사람들뿐 아니라 서양 사람들로 추정되는 인물들 또한 등장하였습니다. 제가 비록 작가님의 생각에는 미치지 못하겠지만, 저 나름의 해석은 TV라는 과학기술과 그러한 TV를 조형미있게 쌓아놓은 예술이라는 두 가지 학문의 연계를 통하여 동서양의 화합을 이룰 수 있을 것이라고 생각하고 작품을 제작하지 않으셨나 싶습니다."},{"q":"학생은 왜 우리 학과에 지원을 한 것인가요?","a":"문화콘텐츠문화경영학과에 지원하게 된 이유는 바로 학과명에서 찾을 수 있습니다. 타 학교들은 ‘문화콘텐츠’학과와 같이 경영과 관련된 키워드가 붙지 않습니다. 한류와 같이 어떠한 대중문화가 문화적으로도 상업적으로도 성공하기 위해서는 결국 산업과 연계되어야 한다고 생각하는 저의 가치관으로는 당연히 문화콘텐츠문화경영학과에 지원할 수밖에 없었습니다. 꼭 인하대학교에 입학하여 한류와 문화산업등에 관하여 함께 공부하고 싶습니다."},{"q":"시간이 이제 다 된 것 같은데, 마지막으로 할 말 있으면 해보세요.","a":"마무리 발언을 할 기회를 주셔서 정말 감사합니다. 직전에 말씀드린 대로 저는 어떠한 문화가 성공하기 위해서는 산업과 연계될 수 밖에 없다고 생각합니다. 문화 콘텐츠뿐만 아니라 문화경영에 관해서도 공부할 수 있는 인하대학교에 꼭 입학하여, 훌륭하신 교수님들, 선배님들과 함께하고 싶습니다. 감사합니다.후배들을 위한 조언 들어가면서 ‘안녕하십니까, XX대학교 XXXX학과에 지원하게 된 가번호 XXX번입니다.’라는멘트는 아예 고정적으로 머릿속에 입력해 두었으면 좋겠습니다. 타학교와 혼동하지 않게 무조건 주의합니다.입학사정관 없이, 교수님 두 분께서만 진행하시며 자기소개나 지원동기 없이 정말 생활기록부확인 면접이었습니다. 따라서, 생활기록부에 기재되지 않은 조금 더 심층적인 내용이나 지식이있다면 그것을 답변할 때 활용하면 좋은 반응을 얻을 수 있을 것 같습니다 (‘낯설게 하기’도생기부에 기재되어 있지는 않은 사항이나, 교수님만 두 분 들어오시는 특성상 뭔가 심화된 개념을 언급하면 플러스 요인일 것이라 생각하여 던진 것이었는데, 해당 부분에서 한 차례 더질문을 하신 걸로 보아 먹힌 전략이 아닌가 싶습니다.)입사관이 들어오지 않는 면접의 특성상, 교수님들이 자신과 말이 통하는, 의사소통을 원활히할 수 있는 학생을 선호하는 경향이 클 것으로 여겨집니다. 자기소개나 지원동기는 비중을 적게 준비하되, 생기부 내용을 기반으로 키워드를 잘 정리하여 누구든 한 번에 알아들을 수 있을 정도로 콤팩트하게 발언할 준비를 하면 좋을 것 같습니다. (당연히 기본적인 예의는 훨씬더 신경을 써야 하고, 눈맞춤 등의 면접 예절 또한 매우 중요할 것으로 생각됩니다.)기타 유의사항에 언급한 대로, 전자기기 보관용 봉투를 지급하긴 하나 크기가 작기에, 태블릿PC등은 소지하지 않은 채로 대기실 입실하는 편이 좋을 것 같습니다. 봉투에 넣어 가방에 보관하라고 안내하시기 때문에, 작은 가방 꼭 지참하면 좋겠습니다.인천이라 바닷가 쪽이고 면접고사장(60주년 기념관)이 좁은 골목처럼 위치하여 있어 건물 밖에서 대기하며 매우 춥습니다. 옷을 단단히 입고 가시는 편이 좋을 것 같습니다.바로 맞은편에는 개방해 놓은 강의실 건물이 있습니다. 학부모님들도 대체로 해당 공간에서대기하십니다. 화장실은 해당 건물을 이용하면 좋습니다.인하대는 지역주민 개방학교로 알고 있습니다. 도서관 열람실이나 서호관의 빈 강의실을 이용할 수 있는 걸로 알고 있습니다. 미리 도착하여 준비하는 학생들은 해당 공간이나 5호관 쪽카페를 이용하면 좋을 것 같습니다.인하대 유튜브에서 면접과 입시에 관련된 홍보팀이 촬영한 영상이 있습니다. 해당 영상 속에등장하시는 인하대생분이 건물 입실 전 간단한 안내를 하시기에 비교적 친숙하게 느낄 수 있고, 영상에서 또한 몇 개의 팁을 얻어갈 수 있으니 꼭 참고하시기를 바랍니다.수능 때 사용할 수 있는 초침, 분침, 시침만 있는 손목 시계를 하나 준비하시는 것을 추천하고싶습니다. 핸드폰을 꺼야 하기에, 간단한 시간 확인이 필요할 때 불편을 겪을 수 있습니다. 인하대에서는 시계 또한 전자기능이 없는지 따로 확인을 하시기에 걱정하지 않고 아날로그 시계로 하나 준비해가시면 도움될 것 같습니다. (면접 시 이미지적인 면에서도 부정적으로 작용하지는 않을 것입니다.)P.S. 문과 계열 학생임에도, 수학 과목의 세부능력 특기사항에 관한 질문이 종종 나오는 것으로 보입니다. 비록 저는 수학 관련 질문을 받지 않았으나, 수학 관련된 과목에서 생기부의 주요 키워드를 이용하여 활동한 경우나 학과에서 주요하게 볼 만한 주제를 선정한 경우에는 잘대비하여 면접할 수 있었으면 좋겠습니다.2024 대입 면접후기"}],"result":"","resultNote":"","src":"충청북도교육청 「2025 대입 면접 후기집」","year":"2025학년도"},{"univ":"인하대학교","dept":"사회인프라공학과","jeonhyeong":"학생부종합(인하미래인재8시 ~ 8시 30분 입실 -> 9시까지 대기실에서 대기 -> 바로 옆 강의)","method":"실에서 면접 7분 정도 봄 -> 긴장 풀어주시려고 같이 심호흡하자고 말씀해주심 -> 생기부 기반 진로 관련 내용 질문 -> 수학교과지식 질문 -> 끝나자마자 짐챙기고 퇴실","notes":"친절하셨고 입학사정관 한 분, 교수님 한 분으로 면접은 7분 정도였다. 수험생 대부분이 셔츠에 니트, 슬랙스를 입었다.","qa":[{"q":"지원동기와 고등학교 생활에서 어떤 노력들을 했는지 말씀해주세요.","a":"어떤 토목공학기술자를 희망하여 건설 관련 활동 설명 후 대학교 당시 듣고 싶은 수업 얘기함."},{"q":"동아리에서 건설 관련 활동으로 가우디 건축 탐구하셨네요. 설명해주세요.","a":"가우디의 사그라다 파밀리아 대성당을 현수선 아치로 설명함."},{"q":"미인정지각 왜 하셨나요?","a":"학교 특성 기숙사 얘기와 시험기간으로 새벽공부해서 늦잠. 지각하지 않기 위해 한 노력들 얘기함."},{"q":"뉴턴운동 제2법칙 등 물리학과 연계해서 내진설계 구조물 만드셨는데 뉴턴운동제2법칙이 뭔가요?","a":"개념 설명 후 구조물에 어떻게 적용했는지 얘기함."},{"q":"로그함수와 지수함수의 관계 설명해주세요(생기부 내용)","a":"역함수 설명"},{"q":"수학과 건설 연관해서 많이 탐구하셨는데 이 중 가장 기억에 남는 활동이 뭘까요?","a":"현수교를 이차함수 분석 -> 왜 현수교의 현수선은 하이퍼볼릭코사인 함수가 아닌 이차함수로 근사할 수 있는지 탐구한 내용 설명함"},{"q":"일차함수와 이차함수 각각 설명해주세요.","a":"(타이머 울림) 개념 설명함 -> 시간이 괜찮다면 마지막으로 하고 싶은 말 해도 되는지 양해 구함."},{"q":"네 마지막으로 하고 싶은 말 하세요.","a":"관련 동아리에서 어떤 활동하고 싶은지 설명.후배들을 위한 조언 인하대학교 사회인프라공학과 면접은 생각보다 다들 친절하시고 웃어주셔서 크게 긴장하지 않아도 될 것 같아요. 진로 관련과 관련 교과 세특 내용 잘 숙지하시면 면접 잘 보실 수 있어요!2024 대입 면접후기"}],"result":"","resultNote":"","src":"충청북도교육청 「2025 대입 면접 후기집」","year":"2025학년도"},{"univ":"인하대학교","dept":"사회인프라공학과","jeonhyeong":"학생부종합(인하미래인재)","method":"긴장푸는대화 → 봉사질문 → 스마트건설 키워드질문 → 확률과통계질문 → 진로활동질문 → 탄소중립실현방법질문","notes":"자기소개, 지원동기, 마지막 하고 싶은 말 준비했는데 안 물어볼 수 있음, 면접실이 강의실 이여서 면접관님들이 멀리 있을 수 있음.","qa":[{"q":"봉사활동을 많이 하셨는데 어떤 것이 가장 인상깊나요?","a":"환경을 깨끗이 하기 위한 플로깅 활동의 리더로 여러 차례 활동한 것이 가장 기억에 남 습니다. 플로깅 활동을 했던 강가의 수질오염에 대한 심각성을 느끼고, 4개월에 걸쳐서 수질정화 실험을 했기에 가장 기억에 남습니다.실험 내용은 부레옥잠과 물상추, EM흙공을 한 수조에 넣고 이것들의 정화능력을 비교 했습니다.친환경 합성세제를 많이 사용하고, 생활하수를 좀 더 깨끗이 만들어 강으로 방 류할 수 있는 하수처리 방법이 고안되어야겠다는 생각을 했습니다."},{"q":"생기부 내용에 ‘스마트‘라는 키워드가 많은데 건설에 스마트가 어떻게 활용될까요?","a":"스마트시티는 4차 산업혁명의 핵심 기술들인 사물인터넷(IOT)과 빅데이터 등의 기술들 을 적용한 도시인데, ICT를 이용해 도시의 공공기능을 네트워크화하여 주민들이 편리하 게 이용할 수 있고 도시 관리 또한 보다 쉽고 정확하게 관리할 수 있도록 한 도시라고 할 수 있다. 우리나라는 대표적으로 부산과 세종에 스마트시티를 구현 해나가고 있다."},{"q":"확률과 통계에서 인구주택총조사라는 통계자료를 통해 토목 건축학적인 입장에서 분석 했다고 했는데 어떤 내용인가요?","a":"1-2인 가구 증가로 인해 소형주택이 부족하므로 공급이 더 필요함, 1-2인 가구의 연령 대가 고령화되므로 고령자 친화적이고 안전을 고려한 사회 인프라 건설이 필요하다. 모든 정책의 출발점은 정확한 정책대상의 파악이므로 제대로 된 표본을 통한 통계 자료 를 갖추고 있어야 한다고 생각한다."},{"q":"여기 진로활동에 해양 쓰레기에 대한 고찰을 했다고 써 있는데 어떤 내용인가요?","a":"쓰레기로 뒤덮힌 지구 곳곳의 상황을 적나라한 사진으로 고발한 책인 ‘쓰레기책’을 읽 고 가장 기억에 남는 충격적인 사실은 쓰레기가 부자 나라에서 가난한 나라로 이동한다 는 사실이었다. 쓰레기는 완벽한 분리수거가 되지 않아 공장에서 사람이 일일이 손으로 분리해야하기에 다른 나라로 수출해 버리는 게 원가가 더 싸다고 한다. 이 책을 읽고 나서 정말 큰일이다 싶어, 학급 친구들에게 탄소중립 실천 앱에 학급 개설을 해서 우리 가 실천할 수 있는 작은 실천들을 모아 우리 학급 이름으로 나무 심기에 참여했다."},{"q":"그럼 탄소중립은 어떻게 실현할 수 있을까요?","a":"저희가 탄소 중립 앱으로 실천했던 활동은 우리가 실생활에서 신경만 쓰면 할 수 있는 활동이였습니다. 예를 들면 안 쓰는 제품의 코드를 뽑던가 유튜브의 화질을 낮게 보는 활동을 통해 데이터 처리에 들어가는 에너지를 줄이며 탄소 중립에 기여할 수 있습니다.후배들을 위한 조언 첫 번째 면접과 두 번째 면접은 천지 차이니까 첫 번째 면접은 떨려서 답변을 생각하고 말하긴 어려우니 그전까지는 열심히 생기부 외우고 대본 외우는 것에 집중하고 두 번째 면접부터는 훨씬 덜 떨리니까 최대한 면접장 안에서 생각하고 말하는 것이 중요하다.2024 대입 면접후기"}],"result":"","resultNote":"","src":"충청북도교육청 「2025 대입 면접 후기집」","year":"2025학년도"},{"univ":"인하대학교","dept":"생명공학과","jeonhyeong":"학생부종합(인하미래인재)","method":"생명공학에 관련된 생기부 질문들 >> 마지막으로 하고 싶은 말","notes":"면접관님들은 총 2명으로 구성되어 있고 시간은 대략 7분 정도 소요(질문에 대한 답이 아직 다 안 끝났으면 그대로 이어서 진행)","qa":[{"q":"과학 마술쇼를 해서 큰 호응을 얻었다고 되어있어서 흥미로운데 구체적으로 어떤 마술 쇼를 했나요?","a":"코끼리 코 치약이라는 것을 진행했는데 이것은 과산화 수소와 아이오딘화 칼륨의 반응을 이용한 실험이었습니다. 과학 마술쇼가 지역 초등학교에서 진행된 것이다 보니 큰 호응을 얻을 수 있었던 것 같습니다."},{"q":"소독에 쓰이는 에탄올의 농도가 70퍼가 적당하다고 조사했다는데 왜 70퍼가 적당한가요?","a":"네, 만약 에탄올의 농도가 70퍼를 이상이 된다면 세균의 표면을 굳게 해서 소독 작용이 세균 내부까지 일어날 수 없게 하고 70퍼보다 작게 된다면 소독 효과가 떨어지기에 70퍼가 적당합니다."},{"q":"사이토카인이 무엇이고 사이토카인이 과다분비되면 어떻게 되는가?","a":"사이토카인이라는 것은 단백질에서 분비되는 면역 물질입니다. 그것이 과다분비가 된다 면 사이토카인 폭풍이라는 자가면역 질환이 발생하게 됩니다."},{"q":"Primer가 무엇이고 어떤 것으로 구성되어 있는가?","a":"Primer라는 것은 DNA 복사를 도와주는 물질입니다. (기억이 안나서 잠시 3초 정적 후에 기억나는 것을 말함..) 그리고 그것은 RNA중합효소와 DNA중합효소로 이루어져 있습니다.후배들을 위한 조언 열심히 준비는 해도 가서 물어보는 과정에서 자신이 모르는 질문이 나오는 경우도 있을 것이다. 물론 완벽하게 준비를 해서 가면 문제가 없겠지만 그래도 만약 모르는 질문이 나온다면 질문하기를 포기하기보다는 뭐든지 그것에 관련된 것을 말해보는 것이 더 좋을 듯 싶다.2024 대입 면접후기"}],"result":"","resultNote":"","src":"충청북도교육청 「2025 대입 면접 후기집」","year":"2025학년도"},{"univ":"인하대학교","dept":"신소재공학과","jeonhyeong":"학생부종합(인하미래인재)","method":"지원동기->간단한 본교 관련 지식질문->미적분 질문->전공질문->독서질문->마지막 할말","notes":"","qa":[{"q":"결정구조의 종류?","a":"단순입방구조,체심입방구조,면심입방구조"},{"q":"반도체원리?","a":"트랜지스터의 원리 설명함"},{"q":"친구들에게 좋은 평을 받은 이유?","a":"학교축제에서 좋은 무대를 주도하여 만듬후배들을 위한 조언 생기부 분석을 잘해가야 합니다. 나오지 않을 것 같은 과목도 대비해야합니다.2024 대입 면접후기"}],"result":"","resultNote":"","src":"충청북도교육청 「2025 대입 면접 후기집」","year":"2025학년도"},{"univ":"인하대학교","dept":"신소재공학과","jeonhyeong":"학생부종합(인하미래인재)","method":"들어와서 인사후 앉음앉아서 면접 진행 모두 자상하게 생기시고 웃고계심","notes":"원서 접수순으로 면접 순서가 정해지는 것으로 예상되니 참고","qa":[{"q":"폐배터리와 역설계를 엮어서 어떤식으로 설명이 되는까?(꼬리)","a":"역설계는 완성품을 먼저 구상하는 것을 시작으로 하기 때문에 보통적인 설계보다 재료의 성질을 수월하게 예측 가능 +배터리에서는 주로 니켈과 코발트 리튬등이 재활용됨 -> 더욱 뛰어난 효율로 배터리의 재활용소재 파악 + 비용의 유연한 조정 가능"},{"q":"배터리 원리","a":"리튬이온전지 예시 - 방전 과정 - 양극 산화 음극 환원 (충전은 반대) 산화전극 ->환원전극으로 이온 이동 설명"},{"q":"산화환원을 표현하는 방법","a":"산소의 이동과 전자의 이동을 기준으로 설명"},{"q":"상전이 (대학교 과정에서 나오는데 어떻게 탐구했냐?)","a":"상전이의 정의(물질의 한 상이 다른 상으로 전이되는 과정)으로 설명 + 이를 통해 탐구했던 상전이와 배터리의 수명과의 반비례관계 언급"},{"q":"기억나는 신소재","a":"형상기억합금, 세라믹"},{"q":"마지막 할말","a":"인하대만의 연구실 조사, 세라믹에 관한 관심 어필후배들을 위한 조언 생기부와 관련된 교과 개념 챙겨가셈생기부 활동 충분한 숙지자기소개 감성팔이 금지2024 대입 면접후기"}],"result":"","resultNote":"","src":"충청북도교육청 「2025 대입 면접 후기집」","year":"2025학년도"},{"univ":"인하대학교","dept":"신소재공학과","jeonhyeong":"학생부종합(인하미래인재)","method":"지원동기 -> 화학/물리 개념 -> 발표내용 다시 말하기&활동 진짜로 했는지 확인 -> 우유급식 어떻게 했는지 -> 마지막으로 할 말노크나 가번호 앞에서 같이 대기해주시던 분이 해주심. 건물 입실도","notes":"그 시간에 딱 맞춰서 가능하게 하니 무리하게 1~2시간 전에 갈 필요는 없을 듯합니다.","qa":[{"q":"촉매와 활성화에너지와 반응속도의 관계?","a":"정촉매랑 부촉매로 나눠서 활성화에너지와 반응속도의 관계 설명"},{"q":"열역학 제 1법칙, 제 2법칙에 대해 간략하게 설명","a":"둘 다 설명함[질문(꼬리)] 엔탈피가 뭔지? (간략하게)설명함[질문(꼬리)] 열역학과 제로 에너지 건물이 연관있어 보이는데 학생들 앞에서 설명할 때 어떻게 설명했는지 간단하게 설명?보일러로 집을 데울 때를 예시로 신재생 에너지(지열에너지, 태양열 에너지 등)를 사용하므로 화석연료 사용을 자제함으로 효율이 뛰어나다고 함(에너지 위주로 설명)"},{"q":"화학 평형이 뭔지?","a":"반응이 안 일어나는 것처럼 보이지만 실제로는 반응이 일어나고 있는 상태라고 함. 예시로 상평형과 동적평형을 들었음"},{"q":"연료전지의 개념? (간략하게)","a":"설명함"},{"q":"철 제련을 친환경적으로 하는 방법?","a":"이산화탄소를 배출하는 코크스와 일산화탄소를 사용하던 기존 방식과 달리 수소를 사용하여 H2O가 생성되도록 하면 친환경적이라고 함"},{"q":"시사팀장하면서 어려웠던 점을 어떻게 해결했는지?","a":"과학기사이다보니 전문적인 용어나 이론 등을 사용하기에 인터넷에 용어나 이론에 대해 검색한 후 그거로도 해소가 안 되면 선생님께 질문해서 해결했다고 함"},{"q":"우유 급식할 때 카리스마있게 친구들이 우유를 먹도록? 독려했다는데 어떻게 했는지?","a":"번호 부여해서 안 먹은 친구들에게 먹으라고 했다고 함"},{"q":"마지막으로 하고 싶은 말","a":"나의 장점 말한 후 후에 되고 싶은 진로인 연구원이 될 때 나의 장점이 도움이 될 거라고 말함후배들을 위한 조언 인하대는 개념 위주로 질문하는 편이니 생기부 내용에 있는 개념은 모조리 알아두기(특히 과학, 수학) ~발표로 호응받음, ~칭찬함, ~로 보아 뛰어난 학생임.처럼 생기부에 활동에 대한 칭찬이 있다면 칭찬이 쓰여있는 그 활동을 실제로 진행했는지 물어보는 느낌임.(간략하게 한 줄 정도로 적혀 있더라도 질문하시는 듯)인성 질문은 행특에서 봉사활동 관련해서 질문하는 듯 합니다^^(실제로 한 건지 확인하기 위해서 질문하시는 듯한 느낌)2024 대입 면접후기"}],"result":"","resultNote":"","src":"충청북도교육청 「2025 대입 면접 후기집」","year":"2025학년도"},{"univ":"인하대학교","dept":"신소재공학과","jeonhyeong":"학생부종합(인하미래인재)","method":"감사인사->지원동기->전공관련질문, 인성질문->마지막말","notes":"대기실에서는 전자기기 휴대금지","qa":[{"q":"지원동기 한번 말씀해주세요.","a":"문명 발전의 획기적인 순간은 신소재에 의해서 이루어졌습니다. 혁신을 이루기 위한 기 술과 이론들이 생겨도 이를 실현할 도구가 없으면 발전은 이루어지지 않기 때문입니다.따라서 저는 신소재공학과에 진학하여 세상에 획기적인 순간을 가져오는 개척자가 되고 싶습니다."},{"q":"(지원동기 듣고,) 아는 신소재가 무엇이 있나요?","a":"그래핀, 탄소나노튜브 같은 탄소 동소체들 같은 신소재에 대해 알고 있습니다."},{"q":"탄소나노튜브는 어디서 알게 되었나요?","a":"1학년 통합과학 시간에 반도체에 대해서 스스로 조사하던 와중에 탄소나노튜브가 반도 체에 쓰일 수 있다는 뉴스를 접하고 나서, 이에 대해 관심을 가지게 되었습니다."},{"q":"탄소기반 신소재뿐만 아니라, 다양한 신소재에서는 원자들 간의 결합이 중요합니다.한번 화학시간에 배운 결합 종류 이야기 해주세요.","a":"공유결합, 이온결합, 금속결합, 배위결합에 대해 알고 있습니다. 배위결합은 공유결합의일부이지만 고급화학때 배운 점이 인상깊어서 따로 대답해 보았습니다."},{"q":"이 결합들에 대해서 설명해주세요.","a":"공유결합은 결합하는 원자끼리 전자를 내놓아서 이를 공유하면서 이뤄지는 결합이고,시그마, 파이결합을 해서 결합이 강력하다는 이점이 있습니다. 이온결합은 양이온과 음이온의 정전기적 인력으로 결합을 하며 이 역시 강력한 결합입니다. 금속결합은 원자의핵 사이에 자유전자들이 전자의 바다를 이루어서 펴짐성과 반짝거리는 특성을 지니게해줍니다."},{"q":"화학시간에 아름다운 공식 고르는 활동에서 이상기체 방정식을 골랐는데, 이유가 있나요?","a":"기체상수를 사용한다는 점과, 화학2 시간에 배운 3가지의 방정식을 통일한다는 점이 인상 깊어서 고르게 되었습니다."},{"q":"(이유를 듣고,) 어떤 공식이 포함되어있는지 3가지 공식을 말씀해주세요.","a":"보일법칙, 샤를 법칙, 아보가드로 법칙이 있습니다"},{"q":"어려운 내용이긴 한데 화학 시간에 엔트로피와 통계적 관계에 대해서 잘 설명했다고 쓰여 있는데, 이에 대해서 설명해 주세요.","a":"이 내용은 ‘화학의 미스터리’라는 책을 읽고 생각해 낸 발상이었습니다. 책에서는 엔트로피를 분자의 움직임으로 설명해 주어서 각각의 분자의 움직임을 확률적으로 나타내고,이과정에서 무한 원숭이 역설, 라플라스의 악마등 다양한 통계적 해설을 곁들여서 설명해주었기 때문에 이러한 점이 인상 깊었습니다."},{"q":"화학을 좋아하는 것 같은데 두레 멘토링 보니까 화학 멘토를 했는데, 뭘 가르치셨나요?","a":"전 원자의 구조, 오비탈, 결합 같은 부분에 자신이 있었기 때문에 친구들에게 이러한 점들을 가르쳐주었고, 이러한 과정에서 저도 한 걸음 더 성장할 수 있었습니다."},{"q":"신소재공학과 관련된 기억에 남는 활동이 있나요?","a":"착화합물을 합성하여 고급 화학때 배웠던 결정장이론을 검증하는 실험이 가장 기억에남습니다."},{"q":"30초 남았는데 하고 싶은 말 있나요?","a":"제 3학년 담임선생님은 절 미친 과학자 같다고 하셨습니다. 제 열정적인 모습을 보시고하신 말씀이었습니다.동아리에서 진행한 기기 분석 실험에서는, 관련된 내용들을 모두 찾아보고, 도출한 결론에 대해서 이해가 될 때까지 실험과 탐구를 진행해 열정적인 모습을 보였습니다.전 미친 과학자에 만족하지 않았습니다. 스스로 이해하고 알게 된 내용들을 학교 학술제 에 참여하여 주위 학우들에게 적극적으로 알리면서 소통하는 과학자의 면모도 갖추도록 노력했습니다. 신소재공학은 개개인만 잘해서는 성공하기 어려운, 협조와 협동이 필요한 공학 분야라고 생각합니다. 따라서 제가 고등학교에서 발전시켜 온 저의 모습은 신소재공학에 적합하다 고 생각합니다.후배들을 위한 조언 준비잘하고, 떨지않고, 아는것만 잘 대답하면 될 듯. 말이 길어진다 싶으면 종결어미를 잘 사용하기, 질문의 의도를 파악하면서 잘 끝내기.2024 대입 면접후기"}],"result":"","resultNote":"","src":"충청북도교육청 「2025 대입 면접 후기집」","year":"2025학년도"},{"univ":"인하대학교","dept":"아태물류학부","jeonhyeong":"학생부종합(인하미래인재1. 면접 들어갈 때 문 열어주심2. 지원동기 없이 바로 생활기록부 질문(인성적인 부분, 창체활동, 세특 다양하게 나옴))","method":"면접 유의사항 안내(블라인드 면접, 필요시 촬영이나 녹음할 수도 있음, 타이머 사용)면접실 들어가서 큰 소리로 인사함.가번호를 크게 읽으라고 시키심.앉기 전에도 인사함. (계속 웃었음)1. 면접 시작 전 유의사항과 함께 10분 타이머를 맞추셨는데, 다른 후기들 보니, 면접 시간을 안알려주셨다고 함2. 타이머 울려서도 질문을 받을 수도 있음","notes":"3. 면접대기실에서 전자기기 사용 불가하고, 면접 첫 순서 시작과 동시에 자료도 못보게 했음(근데 다른 학과는 안그랬다고도 하고...)4. 김대진, 남대식 교수님이 면접을 보심(달라질 수도 있겠지만, 면접 전 학과 홈페이지에서 교수님들 얼굴 보고 들어감)","qa":[{"q":"(인성) 실장하면서 겪었던 갈등과 극복 사례를 말해주세요","a":"실장을 하면서 반에 큰 갈등은 없었지만, 지금의 반을 만들어준 계기를 말씀드리고 싶습니다. 코로나로 학교 행사에 대한 기대가 큰 상황에서 체육대회를 준비하게 됐습니다. 기대가 많았던 이유에서인지 반티를 정하고 나서 약간의 갈등이 있었습니다. 반티를 투표를 통해 다수결로 정하였으나 반대를 한 소수의 친구들이 반티를 입고 싶지 않다고 이야기를 했고 그 과정에서 친구들끼리 감정이 상하는 일이 있었습니다. 그러나 저는 그 소수의 친구들의 이야기를 먼저 끝까지 들어준 후, 다수결로 정한 반티를 입고 체육대회에 참여하는 것이 우리가 반티를 정한 이유라는 논리로 설득했습니다. 결국 모두가 반티를 입고 나가 체육대회를 즐겼고 그 결과 저희 반이 1등을 할 수 있었습니다."},{"q":"지금도 잘 지내고 있나요?","a":"지금도 서로를 생각하며 행복하게 잘 지내고 있습니다."},{"q":"(세특) 확통에서 이항분포와 조건부확률의 예시를 색인해봤다고 하는데 그 예시는 무엇인가요?","a":"먼저, 조건부확률이란 한 사건이 일어났을 때를 가정한 후, 다른 사건이 일어날 확률을이야기합니다. 빅데이터와 관련된 책을 읽고 나서 알게 된 예시를 말씀드리겠습니다.비가 올 때 직장인들이 칼국수를 먹을 확률을 구할 때 조건부확률을 사용해서 구할 수있습니다. 흔히 ‘비가 오면 국물 요리를 먹겠지‘라고 생각하지만, 실제로도 비가 올 확률이 올라갈수록 회사가 모여있는 곳 근처의 국물요리 식당 주변 기지국 신호가 증가합니다. 이런 것을 바탕으로 비가 올 때 직장인들이 칼국수와 같은 국물 요리를 먹을 확률을 조건부 확률로 계산할 수 있습니다. (칼국수요?!! 막 웃으심)"},{"q":"본인 진로와 우리 학부의 연관성은 무엇인가요?","a":"제 꿈은 동남아시아에 특화된 국제통상전문가입니다. 국제경제 시간 동남아 국가로의수출 확대 방안을 탐구하며 제 꿈을 확실히 하게 되었습니다. 저는 특히, 중소기업의수출을 확대해보고 싶습니다. 탐구를 하며 중소기업 수출 부진에 제가 내린 두 가지 결론은 중소기업이 FTA활용을 잘하지 못한다는 점, 또 물류 전략을 효율적으로 세우지못한다는 점이었습니다. 이에 중소기업에게 효율적인 물류 전략을 제시할 수 있는 국제통상전문가가 되기 위해 아태물류학부에 지원한 것입니다."},{"q":"(세특) 수학2에서 지니계수를 탐구했는데, 지니계수를 구하는 방법과 지니계수의 활용방안은 무엇인가요??","a":"지니계수란 한 국가의 소득 불평등 정도를 보여주는 지표로, y=x인 로렌츠 곡선과 가구별 소득액 그래프 간의 넓이로 구할 수 있습니다. 로렌츠 곡선 밑 넓이를 로렌츠 곡선과 가구별 소득액 그래프 사이의 넓이로 나누면 됩니다. 현대 우리나라 지니계수는 약0.2에서 0.3사이이며, 0.4를 넘기면 불평등한 사회라고 봅니다. 저는 최근 코로나 19를겪은 만큼 지니계수와 코로나 19 사이의 관계에 대해 관심을 가지고....(말 끊김, 놀람)(답변을 잘하고 계세요, 근데 지금 시간이 많이 남지 않아서 다음 질문을 꼭하고 싶거든요. 넘어갈게요.)"},{"q":"(창체) 세계사를 바꾼 15가지 무역전쟁이라는 책을 읽은 동기와 아주 간단한 내용 소개해주세요. 빨리","a":"네! 제가 국제정치 이슈를 탐구하다 그 이면에 숨은 경제적 논리가 흥미로워 경제, 국제경제 과목을 모두 수강한 만큼, 이런 정치, 경제가 잘 얽혀있는 무역전쟁에 관심이많았습니다. 이에 세계사를 바꾼 만큼 강력한 이슈들을 탐구하고 또, 미래에는 어떤 무역전쟁이 펼쳐질지 예상해보기 위해 책을 읽게 되었습니다. (10분 타이머 울렸는데, 끄시고 더 말해보라고 하심) 가장 기억에 남는 무역전쟁은 미일 무역전쟁으로, 책을 읽고나서, 환율조작국이라는 용어가 등장한 배경을 알게 되었습니다. 이에 일본의 버블 경제와 현재의 엔저현상을 연관지어 탐구하기도 했습니다. (네~ 그렇군요. 아쉽지만 시간이짧았네요. 그쵸?? 웃으시면서 다시 보자고??하심) 네! 감사합니다. 안녕히 계세요.인사하고 나옴후배들을 위한 조언 학과 홈페이지에 교수님 성함, 전공, 사진이 올라와 있어!사진을 자주 봤더니 면접 본 교수님이 낯설지 않고 그냥 아는 아저씨 같은 느낌이었어.그리고 교수님 성함 검색해서 교수님 인터뷰 내용 찾아보는 것도 좋은 방법이야!2024 대입 면접후기"}],"result":"","resultNote":"","src":"충청북도교육청 「2025 대입 면접 후기집」","year":"2025학년도"},{"univ":"인하대학교","dept":"전기공학과","jeonhyeong":"학생부종합(인하미래인재)","method":"푸리에 급수에 대한 질문 -> 시간 상수 측정 실험에 대한 질문 -> 1학년 2학기의 미인정 조퇴의 이유에 대한 질문 ->블랙홀에 대한 질문 -> 탐구 중 쿨롱법칙과 만유인력법칙의 유사점과 차이점에 대한 질문면접관이 두 분 계시고 두분이 조금 떨어져 계신다.","notes":"타이머를 누르고 타이머가 끝날때까지 질문을 하신다.꼬리질문이 꽤나 많았다.","qa":[{"q":"푸리에 급수에 대한 탐구를 하였는데 설명해 보세요","a":"이 탐구는 제가 2학년 수학시간에 삼각함수의 활용사례를 찾아보다가 푸리에 해석이라는 것을 알게 되었고 그 당시 교육과정에서 배운 내용으로는 더 깊이 탐구하지 못 했습니다. 그래서 미적분을 수강한 뒤 급수에 대해 배우고 푸리에 급수에 대해 탐구한 활동입니다. 푸리에 급수 란 아무리 복잡한 비정현파인 신호여도 사인과 코사인 함수의 급수로 표현가능하다는 것입니다.[꼬리질문] 이것이 쓰인 사례에 대해 아는게 있나요?가장 흔히 접할 수 있는것에는 노이즈 캔슬링기술이 있고 또 전파망원경에 쓰입니다[꼬리질문] 전파 망원경에는 어떻게 쓰이나요?별에서 나오는 비정현파의 신호를 사인과 코사인의 합으로 나타내어 이 신호들을 해석하는것으로 쓰입니다"},{"q":"시간 상수에 대한 실험을 하였다고 했는데 이것에 대해 설명해 주세요","a":"함수발생기를 이용하여 구형파 신호를 만들고 캐퍼시터에 연결하고 캐퍼시터 양단에 오실로스코프를 물려서 두 파형의 차이를 비교하여 시간 상수를 관찰하였습니다. (시간상수가 점근선의 63.2%라는 것을 말하려다가 꽤 절어버림) 시간상수는 점근선의 63.2%가 될 때를 관측해야합니다. 시간상수가 크면 속도가 느려진다는 것입니다[꼬리질문] 속도가 느려지는 것이 무슨 얘기죠?(고민 4초.?)구형파는 파형이 뚝뚝 끊기는 파형을 가지고 있습니다. 전원 공급이 갑자기 꺼졌다 켜졌다 하면 전자기기에 고장이 날 수도 있습니다. 그래서 캐퍼시터를 사용합니다. (기억이 잘 안 나는데 좀 아쉽게 대답함)[꼬리질문] 속도를 더 느려지게 하려면 어떻게 해야하나요?(고민 4초정도 함. 긴장해서 아는데 대답 못 함) 그것에 대해서는 자세히 알지 못해서 답변하기 어렵습니다. 이 대학교에서 더 깊이 탐구해 보고 싶습니다."},{"q":"1학년 2학기때 미인정 조퇴가 있는데 왜 그런거죠?","a":"저는 중학교때부터 새벽에 공부하는 습관이 있었습니다. 그러다가 온라인 수업 주간에 수업 중 졸았고 그 뒤로 계속 자서 끝날 때까지 못 일어났습니다. 그래서 미인정 조퇴가 찍혔습니다. 이 일을 계기로 이 습관을 바꾸게 되었고 앞으로 대학 들어가서도 문제없이 다닐 것입니다."},{"q":"블랙홀에 대한 탐구들이 있는데 블랙홀이 뭔가요?","a":"블랙홀은 탈출속도가 빛의 속도보다 빨라 빛조차 빠져나오지 못해서 까만 별입니다. 태양의 질량보다 큰 별에서 핵융합과 중력이 평형을 이루는데 중력이 너무 세서 빨려들어가 버린 죽은 별입니다[꼬리질문] 탈출속도에 대해 얘기하셨는데 탈출속도에 대해 말해보세요(고민하다가) 이것에 대해 정확히 알지 못했습니다."},{"q":"탐구 중 쿨롱법칙과 만유인력법칙의 유사한 점에 대해 알게 되었다 써져있는데 이게 뭔가요?(질문이 기억이 잘 안남)","a":"쿨롱법칙은 양전하와 음전하가 있을때 두 전하 사이에 작용하는 힘은 r제곱 분의 두 전하의 곱 곱하기 쿨롱상수라는 것이고 만유인력법칙은 질량을 가진 두 물체 사이에 작용하는 힘은 r제곱분의 두 물체의 질량의 곱 곱하기 중력상수라는 것입니다. 두 공식 사이의 유사점을 찾을 수 있었습니다[꼬리질문] 차이점에 대해 말해주세요(위에 질문을 파악을 잘 못한거 같음. 그래서 차이점을 물어봤다고 하심 당황해서 좀 버벅거림)아아 넵. 쿨롱법칙은 양자개념에서의 법칙이고 만유인력법칙은 실생활에 응용가능한 그런 법칙입니다.[꼬리질문] 차이점에 대해서 묻고 있습니다 말해주세요(다시 물어보심. 방금 차이점에 대해 말한 거 같은데 왜 그러시는지 모르겠음. 당황)이것은 자세히 잘 모르겠습니다.->(말 정리가 좀 안되서 그렇지 자세히 잘 설명했습니다라는 말을 좀 하셨슴)총 정리: 꽤 떨려서 기억이 잘 안 나고 적으면서 놈 정리가 된 부분이 있는거 같아서 이 적은 것보다 버벅거림과 정리 안됨이 있었음. 처음부터 미인정까지는 오른쪽 더 젊은 교수님이 하심. 그리고 나머지는 왼쪽 더 나이가 있으신 교수님이 하심. 오른쪽 분은 조금 웃어주셨고 오른쪽 분이 질문하실 때 왼쪽 분은 무엇을 계속 읽고 계셨고 오른쪽 분의 답변을 할때 눈을 한번 마주쳐봄. 왼쪽 분은 웃어주시진 않지만 위로해주심. 대체로 두분 다 빡센 분위기는 아니였음.후배들을 위한 조언 생기부 숙지는 기본이 되어야 하고 생기부 활동에 대한 요약을 공책에 직접 정리하면서 공부를 하는 것이 좋다. 대기실에서 전자기기를 제외한 자료가 허용되기에 이 공책으로 이때 연습하는 것이 좋다. 면접관들께서 매우 친절하기 때문에 긴장하지 않아도 된다. 꼬리질문이 꽤나 깊기 때문에 깊이 알아가는 것이 좋다. 자신감이 제일 중요하다. 모의면접을 최대한 많이 해보며 면접과 익숙해지는 것이 좋다.2024 대입 면접후기"}],"result":"","resultNote":"","src":"충청북도교육청 「2025 대입 면접 후기집」","year":"2025학년도"},{"univ":"인하대학교","dept":"전자공학과","jeonhyeong":"학생부종합(인하미래인재)","method":"지원동기->자율활동 질문->동아리 질문->회로와 관련된 활동 질문->미적분 푸리에급수 질문->마지막 할말","notes":"꼬리 질문에 대한 대비를 철저히 해야한다. 거의 대부분 전공과 관련된 부분에 대해서 질문한다.","qa":[{"q":"지원동기에 대해서 말씀해보세요","a":"저는 호기심이 많아 주변의 전자기기들과 반도체가 어떻게 작동하는지 너무 궁금했습니다. 그래서 반도체의 성능을 높이는 법, 누설전류 문제, 트랜지스터 원리 등 여러가지를 탐구했습니다. 그리고 공동교육과정도 신청해서 강의를 들었습니다. 그럼에도 모르는 부분이 있어서 산업체와의 연계 실습이 잘 짜여진 인하대 전자공학과에서라면 궁금증을 해결할 수 있을 것 같아서 지원했습니다."},{"q":"자율활동 중에서 한국이 메모리 반도체 분야에서는 강국이지만 시스템 반도체 분야에선 떨어진다고 나와있는데 이를 해결할 방법이 있을까요?","a":"우선 시스템 반도체 분야의 인재를 양성하는데에 주력해야한다고 생각합니다. 이를 위해선 정부에서 지원 시스템이나 정책을 실시한다면 해결할 수 있다고 생각합니다."},{"q":"동아리장을 하신 적이 있는데 무엇을 하셨나요?","a":"우선 동아리를 만들게 된 계기부터 말씀드리겠습니다. 1학년 때 실험동아리에 속하면서 실험을 계획해 실험을 하기도 했지만 다른 친구들의 실험 또한 하느라 하고픈 실험을 또 하기엔 시간이 부족했습니다. 그래서 동아리를 만들어 하고 싶은 실험을 계획하고 뜻이 맞는 친구들을 모아 실험을 진행하고 토의하는 형식으로 진행했습니다."},{"q":"전기전자 기초라는 과목을 배우셨는데 이러한 과목이 있었나요?","a":"저희 학교에는 없고 타학교에서 수강신청을 따로해서 수업을 듣는 공동교육과정이라는프로그램을 통해 제가 신청해서 들은 과목입니다."},{"q":"그럼 기억에 남는 이론은 있으신가요?","a":"발전기에 대한 플레밍의 오른손 법칙이 기억납니다."},{"q":"미적분 시간에 푸리에 급수에 대해서 다루셨는데 푸리에 급수를 후배들에게 설명한다면어떻게 설명하시겠습니까?","a":"주기적인 함수를 삼각함수의 합으로 나타내는 것이라고 할 것 같습니다."},{"q":"마지막으로 할말 있으세요?","a":"저는 공학자로서 필요한 능력이 탐구력, 융합적사고능력, 리더쉽, 커뮤니케이션 능력이라고 생각합니다. 그래서 이를 기르기 위해 좋은 교우관계를 유지하고 신뢰를 받아 3년간 실장 부실장으로 반을 이끌며 하고 싶은 실험을 위해 동아리장으로서 실험동아리를이끌기도 했습니다. 그리고 무엇이든 탐구할 때면 심화탐구를 진행했고 교과간의 연계에 집중했습니다. 이렇게 기른 공학자로서의 자질을 바탕으로 이 대학의 체계적인 교육을 받으며 인재로 거듭나도록 하겠습니다.후배들을 위한 조언 마지막 할말에 자신이 어필할 점을 깔끔하게 정리하여 말하면 좋다.꼬리 질문에 대한 대비를 철저히 해야한다.거의 대부분 전공과 관련된 부분에 대해서 질문한다.모르는 것이 있다면 최대한 아는 것을 대답하되 거짓을 고하지 말 것 그리고 이에 대하여 대학에 와서 알아보겟다는 열정을 보일 것.대학의 커리큘럼이나 인재상을 통해 대학에 대한 관심을 드러낼 것.기본적인 이론들을 한번씩 정리해볼 것.2024 대입 면접후기"}],"result":"","resultNote":"","src":"충청북도교육청 「2025 대입 면접 후기집」","year":"2025학년도"},{"univ":"인하대학교","dept":"환경공학과","jeonhyeong":"학생부종합(인하미래인재- 면접번호 (6번))","method":"- 대기실 대기 (약 80분)- 면접실 입실 후 면접관 2인과 면접 진행 (약 8분)인성질문 -> 전공질문 -> 전공질문 -> 세특 개념 확인 질문 ->중요한 과목 질문 -> 마지막 말","notes":"교수님 한 분과 입학사정관 한 분이 들어오시고 시작할 때 긴장을 푸는 질문으로 가볍게 시작합니다. 세특의 개념 숙지를 중요하게 생각합니다.","qa":[{"q":"자기주도적 학습을 잘 진행할 수 있는 이유","a":"항상 과목을 학습하기 전 그 과목에 대한 자신감을 가지고 학습에 임하기 때문에 스스로 과목을 탐구할 수 있는 능력을 기를 수 있었기 때문이라고 생각합니다."},{"q":"자신의 장점 - (어떤 활동)","a":"저의 장점은 친구들을 협력시킬 수 있는 리더십이라고 생각합니다. (교외 정화행사에 리더로 참여하여 친구들이 올바른 시민의식을 가질 수 있도록 노력한 활동)"},{"q":"모둠활동에 참여하지 않는 친구는 어떻게 할까","a":"모둠 구성원 친구들의 강점을 존중해 주면서 그 친구들이 잘 해낼 수 있는 역할을 부여 해줄 것입니다. 그렇게 한다면 친구들은 자신의 강점을 살리면서 모둠활동을 이루어 나 갈 수 있기 때문입니다."},{"q":"활성슬러지법의 장점, 단점","a":"활성슬러지법의 장점은 과정에 투입되는 비용이 적지만 수질오염 개선에 효율적이라는 장 이 있습니다. 하지만 슬러지를 사용하기 때문에 온도에 취약하고 오랜 기간 관리가 필요 합니다."},{"q":"e의 정의를 이용한 정화방법","a":"물을 정화할 때는 오염된 물에 깨끗한 물을 넣어 정화합니다. 이때 n번에 나누어서 n번 정화한다고 하면 e의 정의가 사용됩니다. 결론적으로 물을 정화하면 0.37이라는 1/e 특정 값보다 더 오염도를 낮출 수 없다는 결론이 나오게 됩니다."},{"q":"보일법칙이란 ?","a":"보일법칙은 온도가 일정할 때 부피와 압력은 반비례한다는 법칙입니다."},{"q":"분자량 측정실험","a":"분자량 측정실험을 진행할 때 산소 기체의 분자량을 측정하였고, 산소는 물에 잘 녹지 않는 특성을 가지고 있기 때문에 수상치환법을 사용하여 기체의 질량을 측정한 후 이상기체상태 방정식에 대입하여 산소의 분자량을 측정하였습니다."},{"q":"산염기 측정실험","a":"산염기 측정실험은 농도를 모르는 산 용액에 농도를 알고 있는 염기성 용액을 넣어 농 도를 측정하였습니다. (‘적정’이라는 내용이지만 생각나지 않아 과정을 설명함)"},{"q":"가장 중요하게 생각하는 과목","a":"제가 가장 중요하게 생각하는 과목은 화학입니다. 환경공학에서 이론을 분석하고 실험 을 설계하는 활동이 많은데, 화학 과목이 분석, 실험과 관련된 역량을 키우기에 적합한 과목이라고 생각하기 때문입니다."}],"result":"","resultNote":"","src":"충청북도교육청 「2025 대입 면접 후기집」","year":"2025학년도"},{"univ":"인하대학교","dept":"국어교육과","jeonhyeong":"학생부종합(인하미래인재)","method":"자기소개 및 지원동기생기부 기반 질문마지막 할말대학교 안 교통이 매우 혼잡하기 때문에 일찍 가서 주차하는 것이 좋","notes":"을 것 같다.면접과 관련해서는 따로 연락을 주지 않기 때문에 홈페이지에서 필요한 정보를 꼼꼼하게 찾아읽어야 한다.","qa":[{"q":"네 안녕하세요~.그럼 시작해봅시다. 자기소개랑 지원동기 말씀해주세요.","a":"안녕하십니까. 저는 넘쳐나는 정보를 선별해 내고 제가 자신 생각과 융합하여 새로운 가치를 창출 해낼 수 있는 사람입니다. 실제로 저는 국어 교과에서 학습한 시조인 님이 오마 하거늘과 메타버스, AI, 애니메이션 등을 융합하여 저만의 새로운 방식으로 수업을 진행한 경험이 있습니다. 이러한 경험을 바탕으로 미래 국어교사가 되어서도 다양한 교수법과 교육 기술을 적용하여 학생의 수업 이해도와 학습의 즐거움을 높여주는 수업을 진행하는 교사가 되고 싶다는 생각을 하여 국어교육과에 지원하게 되었습니다."},{"q":"(생기부 문장 그대로) “3학년 화법과 작문에서 대화형 인공지능 서비스를 교육 현장에 접목해야 한다고 주장함. 이를 활용하여 쉽게 생각해보지 못한 아이디어로 심화탐구학습을 계획하고 탐구활동 및 보고서 쓰기에 큰 도움을 받았다는 경험을 제시하면서 긍정적인 면을 강조함.” 이라고 되어 있는데 인공지능서비스가 교육에 효과적인 이유와 본인이 인공지능 서비스를 통해 실제로 얻은 아이디어에는 무엇이 있는지 말해보세요.","a":"챗GPT는 학생들이 보고서 작성에 악용하는 경우가 많아서 선생님들께서 굉장히 부정적으로 생각하는 경우가 많았고 저도 그 점에 어느 정도 동의하는 바였습니다. 하지만 챗GPT를 올바른 방향으로 사용한다면 학습 내용을 토대로 학생들이 생각하지 못한 새로운 아이디어와 탐구 방향을 조언받을 수 있습니다. 챗GPT의 활용을 통해 학생들은 더 넓어진 범주에서 자신의 생각을 확장해나갈 수 있습니다. 화법과 작문 세특에 기록된 한글책임교육제에 대한 탐구도 한글을 더 효율적인 방법으로 많은 사람에게 교육하고 싶다는 생각을 가지고 챗 gpt에게 질문을 던지며 주제를 구체화했습니다."},{"q":"3학년 자율에 설득화법의 실패 사례에 대해 탐구했다고 되어있는데 한번 말해볼래요?","a":"저는 설득 실패사례를 총 세가지 유형으로 분류하여 탐구했습니다. 그 중 화자중심의설득실패 사례에 대해 말씀드리겠습니다. 화자는 설득을 진행하며 청자에게 지속하여 이해확인질문을 하게 되는데 이 과정에서 설득실패가 발생합니다. 이해확인 질문은 청자의 이해도를 확인하기 위해 던지게 되는 질문으로 잘 이해했어?, 알아듣겠어? 등의 질문을 지속하며 청자도 불쾌함을 느끼게 되고 질문을 지속하는 화자도 자신의 주장이 정확하게 전해지고 있는지 불안감을 느끼게 되며 이 과정에서 설득에 실패하는 경우가 많습니다."},{"q":"설득실패사례는 어떻게 조사했어요?","a":"평소 의사소통역량을 중시하기 때문에 소통과 관련된 학술 논문을 찾아 읽었고 친구들에게 자신의 설득 실패사례를 공유할 수 있는 설문지를 돌려 다양한 사례를 얻을 수 있었습니다. 친구들에게 너는 남을 설득할 때 어려움을 겪은 적이 있어? 등의 질문을 지속적으로 던지며 사례를 수집하는 과정에서도 소통에 대한 새로운 깨달음을 얻을 수 있었습니다."},{"q":"탐구를 바탕으로 자신의 설득법칙을 재구성했다고 되어 있는데 그중 중요하다고 생각하는 법칙을 이야기해 줄래요?","a":"저는 총 여섯가지의 설득 법칙을 재구성하였습니다. 그 중 제가 가장 중요시한 법칙은 일관성의 법칙입니다. 일관성의 법칙은 자신만의 고정된 설득법칙을 만들어 놓으면 다양한 상황에 맞춰 다양하게 활용할 수 있다는 점에서 가장 중시했습니다."},{"q":"그렇군요. 다른 법칙은 뭐가 있는지 이름만 말해줄래요?","a":"공손성의 법칙, 권위의 법칙, 사회적응의 법칙, 감사의 법칙, 선호의 법칙입니다."},{"q":"3학년 진로에서 언어학의 뉴미디어 적용이라는 탐구를 진행한 경험이 있는데 본인이 생각한 뉴미디어의 특징은 무엇인가요?","a":"뉴미디어는 전혀 새로운 형태의 미디어이기보다는 인스타그램, 페이스북 등 기존에 존재하던 SNS가 확대되어 사람들에게 더 사회문화적, 심리적으로 더 직접적으로 영향을 준다는 특징이 있습니다."},{"q":"체계 언어학의 관점으로 탐구를 진행한 이유는 뭔가요?","a":"체계언어학은 언어학이 사회의 변화를 담아낸다고 보는 입장이기 때문에 뉴미디어의 영향을 받아 변화한 학생들과 현대인들의 언어 특성을 효과적으로 분석해낼 수 있을 것이라고 생각하여 체계언어학의 관점에서 탐구를 진행했습니다."},{"q":"뉴미디어에서 비언어적 요소가 많이 사용된다는 점을 제시했다고 되어있는데 왜 그런지 생각해본 적 있어요?","a":"네. 미디어의 확산과 사용으로 인해 사람들은 유용성과 점진적인 관계 증진을 추구했던 과거의 언어사용태도와 달리 친밀감을 중점으로 한 지속적인 대화를 중시하게 되었습니다. 이 과정에서 자신의 감정 표현이 보다 쉽고 자유로워졌고, 특히 학생들의 툭툭 던지는 감정표현이 많아지면서 이모티콘 등의 비언어적 요소의 사용이 증가했다고 생각합니다."},{"q":"아쉽게도 대답하는 동안 10분이 다 지나가 버렸네요. 마지막으로 하고싶은 말 있으면 해보세요.","a":"지금은 소통역량을 굉장히 중요시하지만 사실 저는 소통에 조금은 미숙한 학생이었습니다. 하지만 중학교때 우연히 접한 김수영 시인의 시인 ‘풀’ 속 주인공인 풀이 주어진 상황에 유연하게 대처하는 모습을 보고 저도 지난 저의 태도를 반성하고 상대방과의 유연한 소통을 경험할 수 있었습니다. 이러한 저의 경험을 통해 미래 교사가 되어 학생들에게 문학을 통해 성찰하고 성장할 수 있는 기회를 주고 싶습니다. 또한 주의깊게 듣고 말하는 방식을 가르치며 사회속의 당당한 구성원으로서 성장할 수 있도록 돕고 싶습니다. 저에게 인하대학교에서 배우고 자라날 수 있는 기회를 주신다면 정말 감사하겠습니다.후배들을 위한 조언 -본인의 생기부 내용을 무조건 정확하게 암기해야한다.-예상 질문을 하나하나 만들어보고 답변을 첨삭하는 것도 좋지만 시간도 너무 오래걸리고 그렇게 준비한 답변은 잊어버리기 쉬워서 비효율적이다.-생기부와 관련된 논문이나 기사를 많이 찾아 읽으면서 답변에 관련된 소스를 준비한다고 생각하며 준비하는 것이 경험 상 스트레스도 덜 받고 효율적이었다.-이렇게까지 준비해야한다고? 싶을 정도로 준비하고 연습하는 것이 좋다. 준비한 내용이 면접에 다 나온다는 보장은 없지만 돌발 질문에 대한 대비가 되어있기 때문에 자신감이 생기고 쉽게 당황하지 않는다. 2024 대입 면접후기"}],"result":"","resultNote":"","src":"충청북도교육청 「2025 대입 면접 후기집」","year":"2025학년도"},{"univ":"인하대학교","dept":"사회복지학과","jeonhyeong":"학생부종합(인하미래인재)","method":"대기실에서 대기한 후 차례가 되면 면접실로 들어감.면접관은 2명이었음. 면접시간은 10분","notes":"휴대폰은 꺼두어야 하며 마스크는 KF 마스크를 써야함.","qa":[{"q":"지원자가 관심 있는 복지 분야는 무엇이고 그 이유","a":"노인 복지에 관심이 많습니다. 그 이유는 언론에서 우리나라의 고령화 문제와 노인 빈곤 문제가 심각하다는 것을 접하였습니다. 실제로도 주변에서 노인 노숙자들을 많이 볼 수 있었습니다. 이를 통해 노인 빈곤 문제가 정말 심각하다는 것을 경험하게 되어 노인 복지에 관심을 가지게 되었습니다."},{"q":"노숙자 분들을 어디서 보았죠?","a":"지하철역이나 버스정류장 같은 곳에서 보았습니다."},{"q":"노인 빈곤을 해결할 방안은?","a":"기초연금을 올리는 동시에 수급자 대상임에도 수급을 받지 못하는 사람들의 수를 줄여야 한다고 생각합니다."},{"q":"기초연금을 올릴 때의 부정적인 측면은?","a":"다른 곳에서 예산을 더 가져오는 것이기 때문에 해당 분야에는 안 좋은 영향을 끼치겠지만 현재 우리나라의 노인 빈곤 문제가 가장 심각하다고 생각하기 때문에 기초연금을 올려도 된다고 생각합니다."},{"q":"현재 기초연금이 얼마인지 아세요?","a":"40만원 이하라고 알고있습니다."},{"q":"표본조사를 할 때 표본오차를 줄이기 위한 방안은?","a":"표본의 대표성을 확보하는 것이라고 생각합니다. 그 방안으로는 다양한 나이, 성별, 지위를 고려해야 한다고 생각합니다."},{"q":"진로희망이 바뀐 이유","a":"제가 경찰이 되고 싶었던 것은 사람들을 돕고 싶었기 때문이었습니다. 그러나 고등학교 1,2학년 때 경찰의 역할과 사례들을 공부하다 보니 경찰은 사후적인 성격이 강하다는 생각이 들었습니다. 사건이 일어나기 전에, 보다 직접적으로 사람들을 도울 수 있는 분야를 생각해 보다가 사회복지학과 진학으로 변경하게 되었습니다.후배들을 위한 조언 면접관들이 생각보다 친절하시고 이야기를 끝까지 들어주시니 버벅거려도 당황하지 않고 하고 싶은 말 다 하기. 2023 대입 면접후기"}],"result":"","resultNote":"","src":"충청북도교육청 「2024 수시 대비 면접 후기집」","year":"2024학년도"},{"univ":"인하대학교","dept":"신소재공학과","jeonhyeong":"학생부종합(인하미래인재)","method":"대기실에서 약 한 시간 정도 대기를 하고 한 명씩 나가 면접실 앞에서 5분 정도 대기하고 면접을 본 후 퇴실면접관 2명","notes":"수험표와 신분증 지참KF94 마스크를 착용하지 않으면 면접을 보지 못함","qa":[{"q":"1학년 행특에 있는 좌우명을 잘 보여주는 사례 한 가지 얘기 해주세요","a":"2년 동안 진행한 빛의 이중슬릿 실험에 대해 1학년 때부터 한 활동을 얘기함. 실험 실패 사례도 같이 얘기함"},{"q":"반도체의 원리와 종류에 대해 말씀해주세요","a":"반도체의 원리와 종류에 대해 말함. 순수 반도체가 있고, 여기에 원자가 전자가 3인 불순물을 넣으면 p형, 원자가 전자가 5인 불순물을 넣으면 n형 반도체가 된다고 설명함"},{"q":"화학2에서 자유에너지에 대해 배우셨나요? 이를 설명해보세요","a":"(처음에 모르는 눈치여서 면접관님에 다시 엔트로피라고 얘기 해주셨음) 비자발성이 커지는 쪽으로 모든 자연 현상이 흘러간다고 답함. (긴장해서 잘못 얘기함->면접관님이 다시 기회를 주셨음)-> 무질서도가 커지는 쪽으로 자연 현상이 흘러간다고 답함."},{"q":"인류의 편의를 증진시키는 소재 한 가지와 특징에 대해 말해보세요","a":"플라스틱에 대해 설명함"},{"q":"물질의 물리학을 읽었는데, 내용과 느낀 점을 말해보세요.","a":"평소 물질을 생각하면 추상적으로 생각을 하곤 했기 때문에 이 책을 읽으면 이를 해결할 수 있을 것이라고 생각해 이 책을 읽게 됨. 하지만 책을 읽다 보니 이를 해결할 수 없을 것이라는 생각을 하게 됨, 책에 있는 구절을 예로 들어 이를 설명함."},{"q":"리더쉽 발휘 사례를 말해보세요","a":"자율동아리인 동물 환경 동아리에서 부장 역할을 맡아 갈등을 해결한 사례를 답함. 봉사 시간을 정할 때 생긴 갈등"},{"q":"사람책 열람 서비스 봉사를 오래 했는데, 무슨 봉사고 어떤 것을 배웠는지 말해보세요","a":"진로가 비슷한 친구들이 모여 어린 아이들을 대상으로 교육 봉사를 했고, 아이들의 눈높이에서 많은 공부를 했고, 과학은 점진적으로 학습해야 하는 과목이라는 것을 알게 되었다고 답함."},{"q":"10초 정도 남았는데, 짧게 하고싶은 말을 해보세요","a":"8분이라는 면접 동안 저의 모든 것을 보여드리지 못한 것 같습니다. 인하대에 입학해 저의 능력을 모두 보여드리도록 노력하겠습니다.후배들을 위한 조언 생기부에 적힌 내용을 잘 정리한다면 질문에 어려움 없이 답할 수 있다.생각보다 인성 질문도 많이 물어보니 대비가 필요할 것 같다.2023 대입 면접후기"}],"result":"불합격","resultNote":"","src":"충청북도교육청 「2024 수시 대비 면접 후기집」","year":"2024학년도"},{"univ":"인하대학교","dept":"영어영문학과","jeonhyeong":"학생부종합(인하미래인재영어영문학과의 경우에는 7명 정도씩 나누어서 시간대 별로 면접을 봤습니다. 그래서 제 시간대의 7번째로 면접을 본 저는 약 1시간 정도)","method":"걸렸습니다. 전자기기는 모두 지퍼백에 담아 가방에 보관했습니다. 제 순서가 되기 10분 전에 모든 짐을 챙기고 면접실 앞에 의자에 앉아 대기 한 후 앞 순서 수험자가 나오면 제가 들어갔습니다. 면접관 두 분이서 번갈아 가면서 질문하셨고 창체 관련 질문보다는 세부능력 특기사항 관련 질문을 많이 주셨습니다.","notes":"","qa":[{"q":"셰익스피어 오셀로랑 소네트 읽었다고 나와있는데 두 개 모두 또는 하나라도 기억에 남는 특징이 있나요?","a":"오셀로는 질투라는 감정에 대한 힘이 이렇게 강력하다는 것을 느끼게 해준 작품이었고 소네트는 지금 사용하지 않는 2인칭 대명사의 형태와 발음의 차이로 인한 운율 구성이 인상깊었습니다."},{"q":"영어 교육 쪽에 관심이 있는 것으로 보이는데 그 진로와 영미문학이 무슨 관계가 있는지 말씀해주실 수 있나요?","a":"저는 영문학을 통한 영어 교육이 필요하다고 생각했습니다. 문학은 독자에게 다양한 사고를 할 수 있도록 도와주고 논문과 같은 정제된 형태의 영어가 아닌 원어민 위주로 쓰인 글로서 자연스러운 형태의 영어를 접하게 해주어 학생들에게 다양성을 가르쳐줄 수 있다고 생각했습니다. 그렇기에 영문학이 영어 교육과 큰 관련이 있다고 생각했습니다."},{"q":"사회문화 때 영어로 된 미디어 접근에 따른 영어 학업 성취도와 관련된 연구를 하셨는데 이에 대해서 설명해주실 수 있나요?","a":"저는 영문학을 통한 영어 교육이 필요하다고 생각했습니다. 문학은 독자에게 다양한 사고를 할 수 있도록 도와주고 논문과 같은 정제된 형태의 영어가 아닌 원어민 위주로 쓰인 글로서 자연스러운 형태의 영어를 접하게 해주어 학생들에게 다양성을 가르쳐줄 수 있다고 생각했습니다. 그렇기에 영문학이 영어 교육과 큰 관련이 있다고 생각했습니다."},{"q":"가장 봉사 정신이 있었던 봉사 활동은 무엇이라고 생각하시나요?","a":"영어로 된 미디어 접촉이 영어 학업성취도와 관련이 있는지 실험을 한 탐구였습니다. 우리 학교 학생들을 대상으로 설문지법을 통해 영어로 된 미디어 접촉에 대한 사실과 영어 학업성취도를 측정하여 이에 대한 관련성을 발견하고 실제로 효과가 있다는 것을 알게 됐습니다. 그렇기에 저는 영어로 된 미디어를 영어 수업에 적용해야 된다고 생각했습니다."},{"q":"그럼 교우 관계를 위해 진행했던 봉사는 없었나요?","a":"탈플라스틱 실천 관련 봉사를 한 것이 가장 인상 깊었습니다. 점점 심해지는 환경 문제에 관심을 가지고 플라스틱 사용 문제에 대한 심각성을 인식 후 내용을 정리하여 학우들에게 환경 교육 실시와 병뚜껑을 재활용하여 플리 마켓을 만들어 친환경 제품을 파는 등 친환경을 위한 활동에 참여해 뿌듯함을 느꼈습니다.후배들을 위한 조언 생각보다 면접 분위기가 엄하지 않아서 질문한 거 편하게 대답하고 왔던 거 같아요. 그래서 면접이라고 너무 긴장하지 마시고 생각보다 분위기 잘 풀어주시니까 열심히 준비만 하면 될 것 같아요!2023 대입 면접후기"}],"result":"","resultNote":"5번","src":"충청북도교육청 「2024 수시 대비 면접 후기집」","year":"2024학년도"},{"univ":"인하대학교","dept":"전자공학과","jeonhyeong":"학생부종합(인하미래인재60주년 기념관에서 봄.)","method":"대기실에서 기다리고 번호가 적힌 팔찌를 나눠줌.번호가 불리면 면접실 앞에서 잠깐 앉아서 기다려야함.그 후 앞의 면접자가 나오면 스태프의 지시에 따라 들어가면 됨.","notes":"대기실에선 전자기기를 사용하지 못함.면접관에게 자기소개 시, 이름과 수험번호를 말하면 안 됨.","qa":[{"q":"배 안 고파요?","a":"네 괜찮습니다."},{"q":"추천알고리즘 작동원리를 조건부확률을 이용하여 설명해주세요 (수학1 세특에 대한 질문)","a":"추천 알고리즘은 조건부확률을 이용합니다. 조건부 확률이란 어떤 사건이 일어났을 때 다른 사건이 일어날 확률을 나타내는데요, 어떤 콘텐츠를 소비하고 다른 콘텐츠를 소비할 확률을 조건부 확률을 이용해 나타낼 수 있습니다."},{"q":"1학년 진로에 적힌 부분에 대한 질문입니다. ‘중학교 3학년 때 교사의 신뢰를 얻어 공부를 시작하였다’고 적혀있는데 이게 무슨 말이에요?","a":"공부에 대한 자신감이 없었던 중학교 시기에 담임 선생님께서 용기를 불어 넣어주셔서 열심히 할 수 있었습니다."},{"q":"휴리스틱 함수가 뭐에요? (인공지능 세특에 대한 질문)","a":"경우의 수를 탐색하는 방법 중의 하나입니다.(자신없이 말함)"},{"q":"황색망사점균과 철도 시스템에 관한 활동을 하셨는데 이에 대해 설명해주세요. (수학1 세특에 대한 질문)","a":"황색망사점균과 철도 시스템이 같은 패턴을 가지는데 이에 대해 탐구했습니다. (어떤 패턴을 가지고 있냐고 물어보심) -> 잘 기억이 나지 않지만, 황색망사점균이 먹이를 찾기 위해 관을 확장하여 만든 망과 인간이 인조적으로 철도를 확장하여 만들어진 철도 시스템이 유사한 점을 갖는다는 것을 알게 되었습니다."},{"q":"성적이 하락한 이유에 대해 설명해주세요.","a":"2학년 때 수강생 수가 줄었기 때문입니다."},{"q":"수학2 세특에 ‘맥스웰 방정식을 순환 적분을 이용해 나타냈다’고 되어있는데 순환 적분이 뭐에요?","a":"(머뭇거림) 순환 적분은 폐회로에서… (폐회로가 뭐냐고 물으셨고 몇 초 간 정적) -> 잘 모르겠습니다. (‘교육과정에 있는 내용은 아니죠?’라고 물으심) -> 네"},{"q":"물리2 독서로 ‘전자부품백과사전’이 있는데 어떤 내용의 책이에요?","a":"2학년 때 만들었던 빔 프로젝터를 보완하기 위해 콘덴서를 추가하였는데 이 때 콘덴서에 대한 이해가 필요할 것 같아서 읽은 책입니다."},{"q":"기억에 남는 외부 봉사활동이 있을까요?","a":"외부 봉사활동을 코로나 때문에 거의 못하다가 3학년 때 처음으로 경비원분들께 반찬을 전달 해드리는 봉사활동을 하게 되었는데요, 이 때 봉사를 하면서 뿌듯함을 느낄 수 있었습니다."},{"q":"최소 제곱법이 무엇인가요? (수학2 세특에 대한 질문)","a":"해를 구하는 방식 중 하나로 근사적으로 구하려는 해와 실제 해의 오차의 제곱의 합이 최소가 되는 해를 구하는 방식입니다. (‘실제 해가 있는데 왜 해를 또 구해요?’라고 물으셨고 몇초간 정적) -> 다시 설명드려도 될까요? (네 그렇게 하세요) -> 독립변인과 종속변인의 데이터 값을 좌표평면에 찍고 임의의 직선을 그어 그 직선과 데이터 사이의 거리의 제곱의 합이 최소가 되도록 하는 것이 최소제곱법입니다."},{"q":"대학교에 들어와서 공부 계획이 어떻게 되나요?","a":"저는 인하대학교에 입학하면 인하대학교 전자공학과의 체계적인 교육과정 아래에서, 반도체 영역 수업을 들을 것입니다. 인하대학교 전자공학과는 설계수업에 특화 되어있기 때문입니다. 열심히 공부하여 사회에 나가 종합적 설계 엔지니어가 되어 자랑스러운 인하인으로서 학교와 국가 발전에 이바지 할 수 있는 인재가 되겠습니다."},{"q":"마지막으로 하고 싶은 말이 있나요?","a":"인하대학교에 꼭 입학하고 싶습니다.후배들을 위한 조언 인하대학교에 간절히 오고 싶다는 느낌을 주는 것이 중요하겠고, 무엇보다 인하대는 서류 기반 면접이므로 생기부의 사소한 부분까지 정확히 파악하고 가는 것이 좋을 것이다. 필자 본인은 성적이 낮지 않았으나 면접을 잘 보지 못해 떨어진 것 같다. 그러니 본인의 성적과 상관없이 최선을 다해 준비하는 것이 필요하고, 끝까지 방심하지 않는 것이 중요하다.수학 세특 질문이 많이 나오는 듯 하다.본인의 성적이 하락세라면 이에 대한 이유와 어떤 식으로 극복하려 노력했는지 생각해 가는 것이 좋을 것이다.2023 대입 면접후기"}],"result":"불합격","resultNote":"","src":"충청북도교육청 「2024 수시 대비 면접 후기집」","year":"2024학년도"},{"univ":"인하대학교","dept":"컴퓨터공학과","jeonhyeong":"학생부종합(인하미래인재정해진 입실 시간에만 들어갈 수 있고 들어가서 본인확인을 여러 번)","method":"합니다. 그리고 전자기기를 압수하고 간단한 유의 사항을 듣고 대기합니다. 대기하는 동안 준비해 온 자료는 볼 수 있고 저는 1시간 정도 대기한 것 같습니다. 면접은 2대 1로 진행하였고 자소서가 없어 자소서 질문은 없었습니다. 저는 시작하자마자 타이머를 누르고 시작했습니다. 자세는 주먹 쥐고","notes":"무릎에 갖다 대는 형식이 제일 좋은데 예상치 못한 질문이 들어오면 자세가 흐트러질 수 있는데 조심해 주세요.","qa":[{"q":"대기하면서 긴장되지 않으셨는지?","a":"대기하면서 떨리는건 사실이었지만, 교수님들께 빨리 저를 어필하고 싶은 마음을 가지고 대기했습니다."},{"q":"1학년때 선행상을 어떠한 이유로 받게 되었나?","a":"면학분위기 조성에 일조하였던 것 같습니다. 저희가 코로나 세대여서 2학기부터 오프라인 수업을 시작했습니다. 따라서 공부 면학분위기가 전혀 형성되지 않았습니다. 이런 상황에서 저는 알찍 일찍 등교해 1교시 수업 전 책을 펴놓고 자습을 하고 있었습니다. 그 때 아이들이 “쟤 뭐하냐?‘같은 말로 다가왔고 같이 공부하는 아이들도 늘어났습니다. 후에 선생님 귀에도 들어가게 되어 선행상을 받은 것 같습니다."},{"q":"3학년 동아리 장이었는데 어떻게 아이들을 모집했나요?","a":"아이들에게 경험을 선사해주고 싶었습니다. 저 역시 제 진로와 관련된 활동을 경험해보고 싶었고, 아이들에게도 경험을 선사해주어 본인들이 선택한 진로에 좋은 인상을 심어주고 싶었습니다. 이를 바탕으로 한 결과 아이들을 순조롭게 모집했던 것 같습니다."},{"q":"만약 공동체 생활 중에 말을 전혀 듣지 않는 구성원이 있다면 어떻게 할 것인지?","a":"처음엔 당연히 제가 양보할 것입니다. 하지만 계속해서 말을 듣지 않는다면 이름을 빼버리든지 제재를 가할 것입니다. 왜냐하면 교수님들이나 선생님들이 제시하신 공동체 과제는 개인일 때 생길 수 없는 시너지를 공동체에서는 가질 수 있기 때문입니다. 그 의도를 해치고 방해를 가하는 것은 마땅히 제재를 받아야 한다고 생각합니다."},{"q":"가장 인상 깊었던 동아리 활동은?","a":"저는 웹페이지 구현이었던 같습니다. 저희가 활동했던 것을 템플릿으로 사용하고 1일차, 2일차 같은 텍스트를 클릭하면 페이지에 연결할 수 있게 했습니다. 파일을 공유하기 위해 파일공유 앱도 추가하였습니다. 이런 활동 등을 통해 제가 만든 결과물을 보고 뿌듯함을 느꼈고, 동적 웹페이와 같은 시스템도 알게 되었습니다."},{"q":"수학2 과목에 코로나19 확산 예측 및 방역에 수리모델링이 사용된다고 하는데 설명 좀 해주세요.","a":"저는 SIR 모델을 탐구했습니다. SIR모델은 하나의 줄임말인데. S는 감염시킬 수 있는 사람I은 이미 감염된 사람. R은 사망하거나 회복된 사람입니다. 이를 통해 각각의 방정식을 구성하였고 확률적으로 확산한다는 가정하에 예측을 구성한다고 합니다."},{"q":"내 시간이 다되어서 여기까지 하겠습니다.후배들을 위한 조언 저는 제가 준비해온 것에서 거의 나오지 않았습니다. 저런 질문들이 나올 것이라는 것은 생각지도 못하고 있었는데 실전에서 나름 잘 한 것 같습니다. 또한 생각해보니 전공 관련 질문은 마지막에 하나 나왔습니다. 인성 질문이 대다수 였던 것 같네요. 그리고 자기소개랑 지원동기도 물어볼 줄 알았는데 나오지 않았습니다. 아마 시간이 정해져 있어서 그런 것 같애요. 해주고 싶은 조언은. 이렇듯 실전에서는 전혀 예상치 못한 것들이 나오니 평소 질문에 대한 멘트를 준비하고 외울 때 하나하나 자세히 외우지 않고 단어와 그 흐름 위주로 공부하셔야 할것 같습니다. 외우는 것은 실전에서 까먹으면 정말 답없습니다. 따라서 공부를 통해 언제 어디서든 말할 수 있는 수준이 되어야 합니다. 2023 대입 면접후기","a":""}],"result":"합격","resultNote":"","src":"충청북도교육청 「2024 수시 대비 면접 후기집」","year":"2024학년도"},{"univ":"인하대학교","dept":"통계학과","jeonhyeong":"학생부종합(인하미래인재)","method":"대기실에서 약 한 시간 정도 대기를 하고 한 명씩 나가 면접실 앞에서 5분 정도 대기하고 면접을 본 후 퇴실(면접관 2명)","notes":"","qa":[{"q":"간단하게 지원동기 말씀해주세요.","a":"안녕하십니까 저는 통계학과 경제학을 바탕으로 산업의 흐름을 이해하고 인공지능이라는 트렌드에 맞춰 빅데이터 산업을 이끌어 나가며 AI투자분석 프로그램을 제작하는 데이터 사이언티스트가 되고자 인하대학교 통계학과에 지원하게 되었습니다."},{"q":"생기부 보면 2학년 말에 성적이 떨어졌던데 왜 그런가요?","a":"건강상의 문제에 대해 언급"},{"q":"전교 부회장으로 활동한 기록이 있는데, 가장 기억에 남는 활동이 있나요?","a":"생활복을 제작하면서 학생들이 문제삼는 것을 해결할 방법을 제시한 것, 갈등의 상황을대화로 풀어나가면서 스스로의 능력을 발휘한 것에 대해 언급"},{"q":"언어와 매체에서 회귀분석에 대해 탐구했다고 하는데 구체적으로 어떤 것을 했나요?","a":"이론에 대한 탐구 진행 + 설문조사 실시해서 자료를 바탕으로 엑셀로 회귀분석 진행"},{"q":"확률과 통계를 이수했던데 중복조합이 뭔지 설명해 주세요","a":"개념에 대해 설명"},{"q":"정보과학에서 파이값을 구하는 프로그램을 만들었다고 되어있는데, 어떤 방법을 이용해서 만들었나요?","a":"삼각함수 값을 이용하여 일정 간격을 놓고 배치된 영역에 두 직선에 임의의 선분이 생길 때 직선과 이루는 각의 크기와 확률계산에서 기하적 확률을 이용해 적분을 통한 파이값 도출 프로그램 제작."},{"q":"회전변환이 무엇인가요?(기하 심화내용)","a":"이론 내용 설명"},{"q":"마지막으로 하고싶은 말 있다면 해주세요.","a":"저의 궁극적인 목표는 AI투자분석 프로그램을 제작하는 것입니다. 시중에도 이미 그런 모델들이 나와 있는 것으로 아는데요, 인간과 비교했을 때 안정성은 보장되지만 수익성이 떨어 진다는 단점이 있다고 생각했습니다. 만약 제가 직접 제작하게된다면 두 마리 토끼를 모두 잡아 새로운 혁신으로 자리잡을 모델을 만들어보고 싶습니다. 인하대학교에서 그 길을 함께 걸어가고 싶습니다. 감사합니다.후배들을 위한 조언 면접을 볼 때 중요한 것은 자신의 세특에 기록된 이론적인 내용을 숙지하는 것입니다. 면접연습에서 아무거나 딱 집어서 물어봤을 때 딜레이 되는 시간 없이 바로 대답할 수 있는 정도가 되어야 한다는 것입니다. 그리고 자신의 생각을 덧붙일 수 있는 것도 면접에서 강점으로 작용할 수 있습니다. 하지만 무엇보다 기억해야 할 것은 자신감을 가지고 대답해야 한다는 것입니다. 면접관의 기세에 눌려 제대로 대답하지 못하거나 버벅이게 된다면 안 좋은 결과로 나타날 수 있습니다. 모두 들 밝고 힘차게, 자신 있게 걸어나가길 바랍니다!!2023 대입 면접후기"}],"result":"합격","resultNote":"","src":"충청북도교육청 「2024 수시 대비 면접 후기집」","year":"2024학년도"},{"univ":"인하대학교","dept":"한국어문학과","jeonhyeong":"학생부종합(인하미래인재입실 시간이 다 되면 대기실로 입실했습니다. 대기실에서는 다양한 과)","method":"가 모여서 대기하고 있습니다. 대기실에서 휴대폰을 지퍼백에 넣어놓고 가번호를 배부했습니다. 대기실에서 대기하다가 전전 번호가 면접을 보면 면접실 앞에서 대기했습니다.","notes":"가 번호를 배부하는데 수험번호가 아닌 가 번호를 말하고 들어가야 합니다.","qa":[{"q":"지원동기 말씀해 주세요","a":"한 나라의 정체성을 나타내는 것은 여러 요소가 있을 수 있지만 언어라고 생각합니다. 한국어문학과에서 언어와 문학에 대해 심층적으로 배워 세계를 향해 한국 문학의 우수성을 알리는 사람이 되고 싶습니다."},{"q":"3학년 진로활동때 LTE 활동으로 사투리 보존방안을 발표했다고 써있는데 어떤 활동인지 자세히 말해줄 수 있나요?","a":"아 이 활동은 빠른 인터넷의 발달로 사투리가 사라지고 있다는 것에 주목해.. (갑자기 머리가 하얘지면서 말을 더듬기 시작함) 어.. 어.. 보존방안에 대해 이야기해 볼.. 필요가 있다 생각해.. 발표를 진행했습니다. 어.. 다양한 문학 작품을 통한 사투리 보존 방향이 중요하다는 점을 깨달을 수 있었습니다. (면접관님께서 아리송한 표정을 지으셨다.)"},{"q":"문헌정보학과를 희망하셨다고 생기부에 명확하게 제시해 주셨는데 두 학과가 연관이 없는 것은 아니지만 왜 한국어 문학과에 지원했는지 설명 해주세요.","a":"문헌정보학과를 처음에는 희망 했지만 점점 문헌정보학과에 대해 조사하면서 내가 배우고 싶었던 것과는 거리감이 있다는 것을 알게 되었습니다. 결국 제가 하고 싶었던 것은 문학작품에 대해 배우고 이를 보존하고 알리는 것이라고 생각해 한국어문학과에 지원했습니다."},{"q":"2학년 자율활동에 카프카의 변신을 읽고 한 활동이 있는데 이 활동이 어떤 활동인지 설명해 주세요.","a":"카프카의 변신을 읽고 조를 짜서 같이 책에 대해 이야기 해보는 활동이었습니다. 제가 생각했던 관점과는 다른 관점에 대해 알아볼 수 있었던 기회였습니다. 다른 친구들과 이야기해보면서 문학작품을 해석하는 방법이 다양하다는 것을 깨달았습니다."},{"q":"시간이 좀 남았는데 마지막으로 할 말 있으신가요?","a":"현재 K-콘텐츠가 세계를 향해 널리 나아가고 있습니다. 인하대학교에서 한국어 문학을 배워 한국 문학이 세계로 널리 펄쳐나가게 도와줄 수 있는 인재가 되고 싶습니다."},{"q":"아 .. 시간이 다 되었네요. 이제 퇴장하면 될 것 같아요. 후배들을 위한 조언 면접시간이 6분 밖에 안되기 때문에 질문에 알맞은 대답을 해야 할 것 같습니다. 짧은 시간에 자신을 나타낼 수 있는 대답을 하는 것이 좋을 것 같습니다. 말을 더듬어도 포기하지 말고 자신이 원했던 대답을 끝까지 하는 것이 중요하다 생각합니다.교과 세특에서 물어보는 것이 아닌 자율활동, 진로활동을 중심으로 면접이 진행되었습니다.적당한 말의 빠르기와 크기를 한번 조절해 보는 것도 중요할 것 같습니다. 2023 대입 면접후기","a":""}],"result":"추가합격","resultNote":"","src":"충청북도교육청 「2024 수시 대비 면접 후기집」","year":"2024학년도"},{"univ":"인하대학교","dept":"행정학과","jeonhyeong":"학생부종합(인하미래인재)","method":"(일반 대입 면접 과정과 동일) 모든 참가자가 지정실에 대기 후 면접실로 이동하여, 면접관의 질문에 답변하는 방식으로 진행됨.학과별로 면접관 2~3명이 들어오며 참가자는 1명씩 차례대로 들어감. 약 10분간 진행.","notes":"블라인드(익명) 면접 방식으로 진행되고, 면접 당일날에 가번호가 지급됨.교복 등 모교를 예측할 수 있는 복장을 제외하고 깔끔한 평상복 입고 가는 것이 best.","qa":[{"q":"(행동특성 및 종합의견) 2학년 때 성격이 보살과 같다고 했는데, 지난 3년 간 학교 생활에 어떤 마음을 가지고 임했는가?","a":"소통능력과 포용력 언급하여 경청의 자세를 가지고 학교생활에 적극적으로 임했다는 점을 강조함."},{"q":"국민취업지원제도의 정의는?","a":"국민취업지원제도는 취업 서비스와 수혜자에게 가는 실업 급여 제도로 구성된다는 점을 언급함."},{"q":"(추가질문) 미국 복지 제도와 비교했을 때, 두 나라 간의 제도적 차이(장단점)는?","a":"국민취업지원제도의 취지가 잘 실현되고 있다는 장점이 있으나, 자회사 홍보 목적으로 참여한 기업이 존재하기 때문에, 중개인이 해당 회사에 취업하는 것을 강요하는 사례를 언급함."},{"q":"미중 패권 분쟁에서 '패권안정론'의 정의는 무엇인가?","a":"찰스 디킨스의 패권 안정론은 패권국이 전 국가에 대한 공공재 배분 역할을 담당하고 있기에, 두 국가 간의 패권 분쟁이 중요한 이슈로 여겨지고 있다고 말함."},{"q":"생활과 윤리 시간에 님비/핌피 문제를 조사했는데, 두 용어 간 정의상 차이는?","a":"혐오 시설의 정의를 말하면서 해당 시설을 기피하고자 하는 국민의 반응을 님비, 혐오 시설과 반대로 공연장과 같은 좋은 영향을 줄 수 있는 시설에 대해 긍정적 반응을 보이는 현상을 핌피라고 언급함."},{"q":"(추가질문) 우리나라에서 이 문제를 대처하기 위해 정부가 가져야 할 태도는 무엇이라고 생각하는가?","a":"구체적 사례는 언급하지 못했지만, 이런 문제가 생길수록 국가와 시민 간의 소통망을 강화해야한다는 점을 주장함."},{"q":"우리나라 기후 문제에 대해서 그동안 정부가 했던 정책은 무엇이 있을까?","a":"전 정권에서 시행하던 탄소 중립 및 신재생 에너지 정책을 언급함. 후배들을 위한 조언 공공 사회와 긴밀하게 연결된 학과인 만큼, 시사 관련 질문이 나올 수 있다는 점을 명심하여 자신이 조사했거나 관심 있는 최신 이슈를 알아갈 것.면접 예상 질문과 자신이 준비한 답변을 전체 암기하지 말고, 키워드를 암기할 것. 해당 키워드를 말하면 관련 내용을 말할 수 있을 정도로 준비해 갈 것.“우리는 아직 학생이다. 모든 지식을 통달한 전문가가 아니다.” 그러니 면접 때 실수할 수 있다는 점을 명심할 것.2023 대입 면접후기"}],"result":"추가합격","resultNote":"예비 4번","src":"충청북도교육청 「2024 수시 대비 면접 후기집」","year":"2024학년도"},{"univ":"인하대학교","dept":"경제학과","jeonhyeong":"학생부종합전형(인하미래인재- 1차 합격 후 공지된 면접 고사장으로 입장함.- 면접 고사실 옆방에서 대기함.)","method":"- 면접 차례가 오면 안내원에 따른 호출로 면접 고사실로 입실함.- 2명의 면접관과 면접을 진행.- 6분의 면접시간이 주어짐.- 1분이 남았을 때 안내원이 면접관에게 알려주기 위해 문을 두드림. - 이후 남은 1분 동안 면접을 진행한 후 퇴실함.","notes":"수험표와 신분증, 자가 문진표 소지대기방에서 전자 기기 사용금지","qa":[{"q":"인하대 경제학과에 지원한 지원동기가 어떻게 되시나요?","a":"저는 교지편집부 활동을 하면서 경제부 기자라는 꿈을 키워왔습니다. 경제 기자가 되기 경제 기사를 쓰며 경제에 흥미를 느꼈고 이를 계기로 경제에 관심을 가졌습니다. 특히 경제 불평등에 관심을 가졌고 나아가 우리나라 경제 불평등에 대해 알아가다보니 이를 해결하고 싶다는 생각을 했습니다. 그래서 저는 저소득층을 위한 정책들을 마련해 한국 경제 불평등을 해결하는 한국 경제 정책 연구원이 되기 위해 경제학과에 지원했습니다."},{"q":"경제수학 세특을 보면 연천인율, 도수율, 강도율이 있는데 이것이 뭔가요?","a":"연천인율은 1년간 근로자 1000명당 발생하는 재해 건수를 수치화한 것, 도수율은 근로자 100만 시간당 발생하는 재해 건수를 수치화한 것 그리고 강도율은 근로시간 1000시간당 재해로 인해 상실된 근로 손실일수를 수치화한 것입니다."},{"q":"봉사시간이 엄청 많네요. 가장 기억에 남는 봉사 활동은 무엇이었나요?","a":"제게 있어 가장 기억에 남는 봉사 활동은 온라인 축제를 기획한 것입니다. 저는 학생문화부 부장을 맡았습니다. 당시 코로나 때문에 오프라인 축제가 어려웠습니다. 하지만 저는 축제를 진행시키기 위해 온라인 축제를 기획하였고 학교 축제에 부정적인 선생님들을 한분 한분 찾아가 직접 만든 계획서를 가지고 설득했습니다. 이후 학생들과 즐겁게 온라인 축제를 진행시켰기 때문에 제게 있어서 온라인 학교 축제가 가장 기억에 남습니다.충청북도교육청"},{"q":"온라인 축제가 봉사 활동 기록에 없는데, 방송 봉사 활동에 포함된 건가요?","a":"네, 맞습니다."},{"q":"복지관에서 학습지도를 한 봉사활동도 있었는데 이건 기억에 안 남았어요?","a":"물론 복지관에 가 어린 친구들을 위해 봉사 활동을 한 것도 기억에 남지만 3년 동안의 학교생활 중 가장 기억에 남는 봉사활동은 학교 축제를 기획하는 것이었습니다."},{"q":"자소서를 보면 후방굴절 노동공급곡선을 언급했는데 이에 대해 설명해주세요.","a":"후방굴절 노동공급곡선에서 일정 소득을 넘어서면 소득효과가 대체효과보다 커져 노동 의욕이 감소하고 여가를 더 선호하는 현상이 생깁니다. 그렇기 때문에 저는 이를 세금제도인 누진세제와 연결시켜 고소득자에게 고세율을 적용한다며 세후 소득이 낮아져 소득효과가 대체효과보다 커지는 것을 막을 수 있기 때문에 누진세제의 효과가 있다는 보고서를 작성했습니다."},{"q":"많은 책을 읽었는데 가장 인상 깊었던 책은 무엇인가요?","a":"제게 있어서 가장 인상 깊었던 책은 ‘넛지’ 입니다. 넛지라는 책은 디폴트값 즉, 기본값에 따라 사람의 행동에 영향을 주고 이익을 줄 수 있다고 말합니다. 제 꿈이 경제 정책 연구원인데 처음에 수립한 정책을 잘 만든다면 국민 경제에 긍정적인 영향을 줄 수 있을 것이라는 생각을 심어주어서 넛지라는 책이 가장 인상 깊습니다."},{"q":"시간이 다 되었네요. 마지막으로 하고 싶은 말 있나요?","a":"씨앗은 큰 나무가 될지 예쁜 꽃이 될지 아무도 모르는 무궁무진한 발전 가능성을 가지고 있습니다. 씨앗이 발아하기 위해서는 물이 필수적입니다. 저는 인하대라는 물을 받아 지금 이 자리에서 저 자신을 발아시키고 싶습니다.후배들을 위한 조언"},{"q":"꾸준하고 장기간의 면접준비","a":""},{"q":"자신의 생기부, 자소서 전체 내용을 파악하는 것. 진로와 관련되지 않은 비교과까지도 준비할 것.","a":""},{"q":"스스로 예상질문과 꼬리질문을 만들 것","a":""},{"q":"자신의 전공과 관련된 심층적인 지식 필요 (전공 관련 시사 공부 등)","a":""},{"q":"학교 선생님에게 도움을 청하고 꾸준히 모의 면접하여 피드백을 구할 것. (다양한 선생님에게 하면 할수록 좋음)이런 기본적인 것과 더불어 무엇보다도 면접에서 가장 중요한 건 다 이길 수 있다는 자신감이다. 자신의 내신이 낮아서 갖는 부담감이나 면접으로 뒤집어야 한다는 생각은 오히려 해가 된다. 자신이 준비한 만큼 하고 싶은 말을 다 하고 오는 것과 차분하고 큰 목소리로 면접의 주도권을 잡는 것은 면접에서 높은 점수를 받을 수 있다. 또한, 면접준비를 많이 하면 할수록 자신의 답변에 정확함과 당당함을 부여한다. 그렇기에 면접준비는 바쁘더라도 틈틈이 준비할 것.충청북도교육청","a":""}],"result":"합격","resultNote":"","src":"충청북도교육청 「2022 대입 면접 후기집」","year":"2022학년도"},{"univ":"인하대학교","dept":"국어교육과","jeonhyeong":"학생부종합전형(인하미래인재60주년 기념관으로 들어가서 수험표와 신분증 확인하고 체온 측정하고 엘리베이터 타러 간다. 안내해주시는 분이 수험표 보고 몇 층인지 다 확인하고 엘리베이터 앞까지 다 안내해주신다. 국어교육과와 교육학과는 7층이라서 7층까지 갔다. 내리자마자 안내하시는 분이 수험번호 확인하고 대기실까지 안내해준다. 대기실 가서 수험표랑 신분증, 본인 확인하고 가번호 팔찌 받고 과 스티커 붙여진 책상에 앉아 있는다. 들어가자마자 핸드폰 꺼서 가방에 넣고 1시 40분에 유의사항을 들었다. 자)","method":"리에 앉아 있다가 순서가 조금씩 다가오면 문 앞에 배치된 의자로 불려 나가고, 그다음은 대기실 바로 앞 의자, 그다음은 면접실 바로 앞 의자에 앉는다. 대기실 바로 앞 의자까지는 준비한 종이 볼 수 있는데 면접실 앞에서는 못 본다. 참고로 면접실 앞에 앉아 있으면 안에서 말하는 소리 다 들린다. 내용까지는 확실하게 안 들리는데 단어 단위로 조금씩 들린다. 면접은 대략 6~8분이지만, 타이머 울려도 계속 질문하시거나 마지막 말할 기회 주신다. 면접 끝나고 앞에서 짐 챙겨서 엘리베이터 앞으로 가면 가번호 팔찌 가위로 끊어주신다. 그대로 엘리베이터 타고 내려와서 들어온 문으로 나오면 된다.- 입장할 때 수험표 프린트해주니까 잊어버리거나 잃어버렸어도 괜찮다.","notes":"- 차 진입 금지라고 했지만, 다들 면접 보는 건물 앞에서 내렸다.- 가번호 팔찌를 줬는데, 생각보다 길다. 영어+숫자로 6글자였다.- 대기실 가자마자 전자기기 꺼야 한다.","qa":[{"q":"자기소개+지원동기","a":"안녕하십니까 세상을 바라보는 넓은 시각을 키워주는 교사가 되고 싶은 (가번호)입니다. 지역간 비경쟁 독서토론에서 ‘알지 못하는 아이의 죽음’ 책을 읽고 특성화고의 생활과 특성화고 취업 실습의 문제를 알게 되었습니다. 이는 인문계고에 다니는 사람으로서는 깨닫기 힘든 문제였지만, 책을 통해 특성화고의 문제를 바라보게 되며 세상을 더 넓게 바라볼 수 있게 되었습니다. 이러한 경험을 토대로 학생들이 세상을 넓게 바라보도록 도와 더 큰 세상에 나아가도록 힘쓰고 싶어 인하대학교에 지원하게 되었습니다.충청북도교육청"},{"q":"독서 권수가 굉장히 많은데 읽을 수 있었던 비법? 이유는 무엇인가요?","a":"쉬는 시간, 점심 시간 틈틈이 읽는 등 자투리 시간을 활용했기에 책을 많이 읽을 수 있었습니다."},{"q":"1학년 활동에서 유음화 비음화 탐구 활동이 무엇인지 설명해주세요.","a":"사람들은 ‘신라면’의 발음을 [신나면]이라 하는지, [실라면]이라 하는지 궁금해져서 추가로 8개의 단어를 선정해 설문조사를 진행했습니다. 설문조사 결과 학생들이 교사보다 유음화를 많이 사용한다는 결론을 내렸습니다."},{"q":"그 이유가 무엇인가요?","a":"학생들이 교사보다 외래어를 접하는 경우가 많아 원음을 중시하게 되는 정도가 높기 때문이라고 생각했습니다."},{"q":"그러면 ‘신라’는 [실라]로 발음하지만, 신라와 신라면은 다른데 표준 발음을 수정할 때 유음화로 [실라면]이라 해도 되나요?","a":"‘신라면’의 표준 발음이 없는 상황이니, 수정이라기보다는 제정할 때 사람들이 많이 발음하는 대로 지정하는 것이 좋을 것 같다고 생각합니다."},{"q":"이미 정해진 문법 체계가 있는데 사람들이 많이 사용한다고 그렇게 막 바꿔도 되나요?","a":"‘짜장면’도 원래 [자장면]이 표준 발음이었지만, 사람들이 [짜장면]으로 많이 발음하다 보니 둘 다 표준 발음으로 지정되었듯이, ‘신라면’도 비슷한 경우로 생각하면 될 것 같다."},{"q":"1, 2학년 때 종교활동 많은데(동아리가 기독교 동아리였음) 어떻게 국어 교사에 관심이 있는지 어떻게 알 수 있죠?","a":"학교 내 동아리만이 아닌, 다른 학교와 연합한 동아리였기 때문에 더욱 다양한 사람을 만나는 기회가 되었습니다. 이는 새로운 사람을 만나도 친밀하게 관계를 유지하는 방법을 배울 수 있었고 교사가 되었을 때 학생들에게 다가가고, 관계를 유지하는 데 적용할 수 있어 도움이 될 것입니다."},{"q":"그럼 국어는? 국어 내용은 없나?","a":"동아리 활동에 국어 관련 활동인 진로 신문 제작, 맞춤법 퀴즈, 한 학기 한 권 읽기 등이 있기 때문에 국어 내용이 부족하지는 않습니다. 이뿐만 아니라 생활기록부의 다른 기재 사항에서도 충분히 국어 관련 활동이 있다고 생각합니다."},{"q":"국어 교사를 늦게 희망한 편인데, 3년 내내 국어 교사를 준비한 친구들에 비하면 활동이 부족하다고 생각하지 않나요? 어떻게 설명할 수 있죠?","a":"활동의 깊이를 달리했습니다. 1, 2학년 때는 선생님께서 주도하시는 독서토론을 했다면 3학년 때는 후배들을 위해 직접 독서토론을 주도하며 더 깊은 활동을 진행했습니다. 또한 1, 2, 3학년 모두 문법 탐구 활동도 꾸준히 해왔고, 고전문학 교육방안 마련 등 활동을 했으니 부족하지는 않다고 생각합니다."},{"q":"시간이 다 지났는데 마지막 말 하고 싶으면 하세요.","a":"저는 학교에서 여러 번의 독서토론을 하며, 제가 모르는 분야를 다양하게 접하는 기회가 되었습니다. 이러한 점을 이용해 다른 교과와 융합하여 융합교과 독서토론을 기획한다면, 독서 교육과 함께 더 다양한 수업을 진행할 수 있을 거라고 생각했습니다. 인하대충청북도교육청학교에 입학한다면, 이러한 활동을 사범대학 다른 과 친구들, 교수님들과 함께 만들어나가며 성장하는 시간을 갖겠습니다.후배들을 위한 조언 홈페이지 들어가서 교수님들 얼굴을 익히고 가는 것을 추천한다. 내적 친밀감이 생겨서 조금이나마 마음이 편해진다.꼬리 질문이 많은 편이었다. 한 분은 공격적으로 질문하시고, 다른 한 분은 웃으면서 들어주셨다. 교수님들이 역할 분담을 하셨구나~ 생각하니 꽤 편안해졌다.겉옷 면접 들어가기 전까지 계속 입고 있을 수 있으니 복도에서 추우니까 입고 있기충청북도교육청"}],"result":"합격","resultNote":"예비 3번","src":"충청북도교육청 「2022 대입 면접 후기집」","year":"2022학년도"},{"univ":"인하대학교","dept":"영어영문학과","jeonhyeong":"학생부종합전형(인하미래인재1. 면접 입실 시간에 맞춰 인하대학교 60주년 기념관 앞에서 같은 면접 시간대의 학생들이 다같이 모임.2. 안내관의 안내에 따라 면접이 진행되는 층에 따라 줄을 섬. (본인은)","method":"2층과 지하1층 줄에 섬.)3. 건물에 입실 후 미리 인쇄해 온 수험표와 신분증 대조 및 코로나 증상 검진표 확인4. 열감지 기계에서 열 측정 후 해당 면접 층으로 이동.5. 면접 대기실에서 차례가 불릴때까지 대기. (영문과, 행정학과, 경영학과 같은 대기실 사용)1. 수험표를 꼭 먼저 인쇄해서 챙겨가야 하며 코로나 검진표 집에서","notes":"미리 작성해서 가야 번거롭지 않음.2. 대기실 입실 후 전자기기 사용하면 부정행위로 간주.","qa":[{"q":"점심 밥 먹고 왔어요?","a":"아직 먹지 않았습니다."},{"q":"긴장해서 그런가.. 면접 끝나고 먹어야겠네요.","a":"네. 긴장을 많이 해서 그런 것 같아요."},{"q":"그래도 어쨌든 학생을 평가해야 하니 이제 슬슬 시작해도 될까요?","a":"네 !"},{"q":"생활기록부를 보니까 영어권 문화 교과를 이수했는데 가장 기억남았던 활동은 무엇이에요?","a":"(순간 기억이 안나서) 앗 혹시 2학년때 이수한 과목이 맞나요?"},{"q":"네 맞아요.","a":"10년 후 저의 미래 모습에 대해 에세이를 작성한 후 친구들에게 발표한 활동이 가장 기억에 남습니다. 이 활동으로 저의 꿈인 국제교류전문가를 이루어 열심히 활동하고 있는 저의 모습을 구체화 할 수 있었으며 친구들 앞에서 영어로 발표하며 영어 회화 능력 또한 기를 수 있었습니다."},{"q":"흠 에세이 작성 활동과 영어권 문화가 무슨 관련이 있는지 모르겠는데요.","a":"영어권 문화와 직결적인 관련은 없던 활동이었지만 미래의 저의 모습을 상상하며 저의 꿈을 이루고 싶은 열정을 얻을 수 있었습니다.충청북도교육청"},{"q":"네 알겠습니다. 그럼 2학년때 영어스피치 동아리 시간에 ‘다른 친구들이 하지 않는 활동에 먼저 솔선수범 하는 모습을 보았다.’라고 적혀있는데, 솔선수범을 할 수 있었던 원동력이 무엇인가요?","a":"제 자신을 믿는 자존감과 그 자존감을 통해 나오는 자신감이라고 생각합니다. 자존감과 자신감을 토대로 정해진 동아리 시간에 보다 친구들과 함께 많은 것들을 배우고 싶었습니다. 모두 시작하지 않는 분위기에서 제가 먼저 발표를 진행하며 친구들에게 용기를 주었다고 생각합니다."},{"q":"다음으로는 3학년때 세계문화 동아리에서 다양한 영어권 나라의 문화를 비교하였다고 하는데 어떤 활동이었나요?","a":"다른 영어권 나라와 호주의 문화를 비교하였던 활동입니다. 미국과 영국같은 영어권 나라는 많이 조사하고 탐구했었지만 호주는 제가 알아볼 수 있었던 기회가 적었기 때문에 선정하였습니다. 이 활동을 통해 호주는 다른 영어권 나라와 달리 회계연도를 6월로 사용하며, 마트에서 실온과 냉장고에 있는 음료의 가격을 달리 하는 것을 알게 되었습니다."},{"q":"그럼 그 활동에서 알게 된 것들과 영미문학을 연결 시킬 수 있나요?","a":"음.. 그러한 심층적인 활동은 하지 못하였습니다. 하지만 제가 인하대학교에 입학하여 꼭 교수님들께 더 배우고 싶습니다.(여기서 웃어주셨음)"},{"q":"꿈이 국제교류전문가라고 했는데 전 아직까지도 이 꿈이 추상적이게 들리는데 정확히 무슨 직업이며 미래의 계획이 있나요?","a":"국제교류전문가는 한국의 문화를 타국에게 알리는 직업으로 한국의 우호적인 이미지를 도모하는 직업입니다. 저는 인하대학교 영어영문과를 졸업한 뒤 ‘한국국제교류재단’이라는 공기업에 입사하는 것이 최종 목표입니다. 이 공기업에서는 현재 한국의 문화를 알리기 위해 다양한 사업들을 진행중입니다. 저는 그중에서도 얼마전 캐나다에서 열린 한국 영화제 사업이 가장 인상깊었습니다. 인하대학교를 통해 저의 꿈을 꼭 실현하고 싶습니다."},{"q":"네 이제 시간이 다되었네요. 수고하셨어요.","a":"네 감사합니다!후배들을 위한 조언 우선 자신의 생기부와 자소서를 완전히 파악해야 불안하지 않고 자신감이 생기는 것 같습니다. 인하대학교는 6분에서 8분정도 면접을 진행합니다. 실제로 진행하여보니 굉장히 짧은 시간이었습니다. 이 시간동안 자신을 어필해야합니다. 물론 말의 내용도 중요하지만 가장 중요한건 예의바름이라고 생각합니다. 저는 들어가자마자 간단한 목례를 하고, 의자 옆에 서서 안녕하십니까라고 하며 공손히 인사하였습니다. 나갈때도 마찬가지로 감사합니다 라고 인사하였습니다. 또한, 너무 긴장하지 않아도 된다고 생각합니다. 교수님께서도 아이스브레이킹을 진행하시면서 최대한 저의 긴장을 풀어주시려고 하셨습니다. 그리고 저는 인하대학교 홈페이지에서 과목 커리큘럼과 교수님들의 얼굴을 외워갔습니다. 실제로 면접장에 들어갔을 때 면접관님들이 모두 홈페이지에서 본 교수님들이셨고 따라서 조금 편안한 분위기로 면접을 진행할 수 있었습니다. 자신감 있는 모습을 보여준다면 교수님들께서 인상깊게 보실 것이라고 생각합니다.충청북도교육청"}],"result":"합격","resultNote":"","src":"충청북도교육청 「2022 대입 면접 후기집」","year":"2022학년도"},{"univ":"인하대학교","dept":"영어교육과","jeonhyeong":"학생부종합전형(인하미래인재면접시간 : 6~8분면접절차 : 입구에서 열 체크, 손 소독 후 수험표 및 자가진단표)","method":"확인->대기실로 이동->핸드폰 전원 끄기->신분증 검사 후 손목밴드(가번호) 차기 ->호명이 되면 소지품 다 들고 대기실 맨 앞으로 이동 후 손목밴드 확인->복도에서 대기->면접장 앞으로 이동하여 소지품은 바구니에 넣은 후 대기->면접실로 입실->면접 진행","notes":"블라인드 면접 / 5개 학과가 같은 대기실 사용","qa":[{"q":"영어Ⅱ 시간에 다른 나라의 교육정책에 대해 조사했다고 했는데 가장 기억에 남는 정책 한 가지를 소개해줄 수 있을까요?","a":"네, 저는 핀란드의 교육정책이 가장 기억에 남습니다. 핀란드는 학생 중심 수업으로 유명한데, 토론수업 등을 통해서 학생들의 생각을 이끌어내는 수업을 진행한다는 것을 알게 되었습니다. 저 역시 교사가 되었을 때 토론수업, 독서수업을 통해서 학생들의 생각을 확장시키는 수업을 만들어가고 싶다는 생각을 하게 되었습니다."},{"q":"접두사에 대해서 설명해줄 수 있나요?","a":"(대답 잘 못 했음.) (면접관님이 웃으시면서 다음 질문으로 넘어가겠다고 말씀하심.)"},{"q":"2015 개정 교육과정을 탐구했는데, 가장 강조되고 있는 역량이 무엇이라고 생각합니까?","a":"저는 2015 개정 교육과정 중학교 영어과를 탐구했습니다. 2009 개정 교육과정과 비교하는 활동을 했는데, 2009년에는 내용을 정확하게 학습하는 데에서만 그치는데 비해서 2015년에는 학습을 한 후 학생이 자신의 생각을 표현하는 활동까지 확장해나가는 것을 알 수 있었습니다. 2015 개정 교육과정에서는 의사소통 역량이 가장 강조되고 있다는 생각이 들었습니다."},{"q":"그러면, 학생이 생각했을 때 현재 학교에서 의사소통 역량을 기르기 위한 노력이 잘 시행되고 있다고 생각합니까?","a":"네, 저는 잘 시행되고 있다고 생각합니다. 학교에서 수행평가를 볼 때도 말하기나 발충청북도교육청표를 통한 수행평가가 많아지고 있고, 수업시간에도 자신의 의견을 공유해보는 활동을 많이 하기 때문입니다."},{"q":"외국인 근로자 및 외국인을 위한 한국어 교육을 했다고 했는데, 이 봉사를 하면서 어려운 점은 없었습니까?","a":"외국인 근로자 분들이 영어권에 사시는 분들이 아니다 보니까 제가 영어로 한국어 어휘를 설명해드리기는 한계가 있었습니다. 최대한 쉽고 간단한 영어 표현을 사용하려고 노력하고, 손동작이나 표정을 통해 맥락 속에서 단어를 이해하실 수 있도록 도와드렸습니다."},{"q":"외국인 근로자 분들은 어느 지역에서 오신 분들이 많았습니까?","a":"베트남과 스리랑카에서 오신 분들이 가장 많았습니다."},{"q":"외국인 근로자 봉사는 얼마나 했습니까?","a":"고등학교 1학년 때 1년 정도 했고, 주말을 이용하여 일주일에 4시간 정도 봉사를 했습니다."},{"q":"자기소개서에서 ‘언어는 세상을 바라보는 창문’이라고 표현했는데, 무슨 뜻인지 보충 설명을 해주세요.","a":"언어는 많은 사람들과 소통하고 다양한 정보를 얻기 위한 매개체이기 때문에 세상을 바라보는 견문을 넓혀줄 수 있다고 생각합니다. (중간에 7분 타이머 울림) 우리는 언어를 이용해 세상을 살아가고, 또 소통을 위해 언어가 반드시 필요하기 때문에 언어가 세상을 바라보는 창문이라고 표현했습니다."},{"q":"지역 내 수학 부스에서 수학 조장을 했다고 했는데, 조장을 하면서 무엇을 배우게 된 것은 무엇입니까?","a":"수학 부스를 운영하면서 설명서 제작에 논의하며 갈등이 발생한 경험이 있습니다. 다양한 연령층의 학생들이 체험을 하러 왔는데, 연령별로 다르게 설명하는데 어려움을 겪게 되었습니다. 이전에는 좋은 조장이 되려면 좋은 의견을 내서 잘 통솔해야 한다고 생각했었습니다. 하지만, 조원들의 의견에 경청하며 함께 소통한 결과 연령별 설명서 세 세트를 제작하여 부스를 성공적으로 마칠 수 있었습니다. 저는 이 경험을 통해 소통의 중요성을 깨닫게 되었고, 교사가 되었을 때도 학생들의 말에 경청하고 공감하는 교사가 되어야겠다고 다짐하게 되었습니다."},{"q":"마지막으로 하고 싶은 말 있으면 해보세요.","a":"저는 고등학교 재학 기간 동안 국내교육정책 탐구와 2015 개정교육과정 탐구, STEAM 교육 탐구 등 교육에 관련된 다양한 활동들을 하며 교사로서의 역량을 키웠습니다. 어떠한 과제가 주어지더라도 항상 열정을 다해 탐구하며 매순간 노력할 자신이 있습니다. 인하대학교에 합격하게 된다면 앞으로도 열심히 배우고, 동아리와 봉사에도 적극적으로 참여해서 공감하고 소통하는 영어교사로 성장하기 위해 최선을 다하겠습니다. 제게 인하대학교 영어충청북도교육청교육과 교수님들과 진솔한 이야기를 나눌 소중한 기회를 주셔서 너무 감사드립니다. 내년에 꼭 캠퍼스에서 만나 뵐 수 있었으면 좋겠습니다. 감사합니다!후배들을 위한 조언 준비가 덜 되어서 제대로 답변을 못 한 것이 있다고 하더라도, 면접 도중에 크게 당황하거나 낙담하지 않았으면 좋겠습니다. 사람이기 때문에 충분히 실수할 수 있습니다. 다음 답변에서 충분히 만회할 기회가 있고, 면접은 인사하고 나가는 것까지가 면접이기 때문에 아직 끝날 때까지 끝난 것이 아니라는 점 꼭 말해 주고 싶습니다.충청북도교육청"}],"result":"","resultNote":"","src":"충청북도교육청 「2022 대입 면접 후기집」","year":"2022학년도"},{"univ":"인하대학교","dept":"항공우주공학과","jeonhyeong":"학생부종합(인하미래인재)","method":"한 명씩 들어가 질문을 받고 나옴. 면접관은 총 2명- 개인 면접으로 긴장하지 않은 모습을 보여주고 최대한 자신이 알고","notes":"있는 것을 조리 있게 말하기.- 질문이 조금 많은 편이고 자신이 조사했다고 한 부분은 정확하게 알아가기","qa":[{"q":"간단히 자기소개 해주세요","a":"저는 1학년 때 항공우주 박물관에 다녀온 이후로 항공기의 여러 원리를 체험해보고 많은 종류의 비행기를 직접 보면서 비행기를 직접 만들고 싶다는 꿈을 갖게 되었습니다. 화학 주제 탐구를 하며 친환경 비행기를 직접 조사해보았습니다. 직접 만든 비행기로 전 세계 환경오염의 피해를 줄이고 싶었으며 직접 만든 비행기를 세상에 널리 알리는 것을 목표로 삼고 있습니다."},{"q":"이계도함수가 그래프에서 갖는 의미는 무엇인가요","a":"다항식을 그래프로 나타낼 때 순간순간의 기울기를 말합니다."},{"q":"베르누이 원리 간단하게 설명해주세요","a":"이상기체는 유체의 속도가 빠르면 압력은 낮아지고 반대로 속도가 느리면 압력이 높아지게 되는데 이것을 베르누이 정리라고 하며 대표적으로 비행기의 날개를 예로 들 수 있습니다. 날개 위아래의 압력 차이로 날개에 양력이 발생하는데 이 힘으로 비행기가 날 수 있습니다."},{"q":"생기부 보니까 비행기 조종사가 되고 싶다고 되어있는데 왜 저희 학과에 지원하였나요?","a":"비행기를 조종하는 것도 저의 오랜 꿈이었지만 하늘을 나는 다양한 비행기를 직접 만드는 것 또한 저의 오랜 꿈이었어서 지원하게 되었습니다."},{"q":"마지막으로 하고 싶은 말 있으신가요?","a":"’쓰레기 책‘을 읽고 개발도상국들이 입고 있는 피해의 심각성을 알게 되었습니다. 인하대학교 항공우주공학과에 다니며 환경오염의 피해를 줄일 수 있는 친환경 비행기를 만들어 많은 사람들에게 도움을 줄 수 있는 사람이 되고 싶습니다. 후배들을 위한 조언 면접관과 본인의 거리가 조금 있는 편이라 또렷한 발음과 큰 목소리가 필요해요!충청북도교육청"}],"result":"합격","resultNote":"","src":"충청북도교육청 「2022 대입 면접 후기집」","year":"2022학년도"},{"univ":"인하대학교","dept":"정보통신공학과","jeonhyeong":"학생부종합전형(인하미래인재전형1. 건물 앞에 면접을 보는 층별로 줄서기2. 줄별로 체온, 신분증 확인하며 건물 입장)","method":"3. 대기실에 들어가 거리두기 하며 착석4. 휴대폰 수거 및 마스크 벗어서 얼굴 확인5. 호명 시 모든 짐을 가지고 복도의자로 이동6. 짐을 바구니에 두고 앞사람이 방에서 나오면 노크 후 입실7. 7분 타이머를 맞추고 시작하며 시간이 지나면 알람이 울림- KF94마스크가 아닌 경우 입장이 제한됨.","notes":"- 휴대전화를 수거하지는 않으나 전원을 끈 상태로 지퍼백에 보관함.- 대기실에서 면접 공부를 허용해줌.","qa":[{"q":"이동통신세대의 변천사를 조사했다고 했는데 어떤 특징이 있나요?","a":"이동통신세대는 전송 속도를 기준으로 1G부터 현재는 5G까지로 나누어진다고 알고 있습니다. [꼬리질문] 또 다른 특징은 없나요?한 번에 전송할 수 있는 양과 전송방식의 차이도 조금씩 존재합니다."},{"q":"트렌지스터에 대해서 조사했다고 하는데 트렌지스터가 뭔지 설명해주세요.","a":"트렌지스터는 p-n-p형과 n-p-n형으로 나누어집니다. 이미터와 베이스, 컬렉터인 3개의 단자로 이루어져 증폭작용과 스위칭작용을 하며 열이 거의 발생하지 않아 대부분의 전자기기에 이용됩니다.[꼬리질문] 그 외에도 요즘 많이 사용되는 종류가 있는데 알고 있나요? 아직 안 배웠나?고등과정에서 배운 건 제가 답한 부분이 전부이지만 대학에 입학하고 더욱 배워보고 싶습니다."},{"q":"블록체인 기술에 대한 보고서를 깊이 있게 작성했는데 블록체인 기술이 정확히 무슨 기술인가요?","a":"누구나 열람할 수 있는 장부에 거래 내역을 투명하게 기록하고, 여러 대의 컴퓨터에 이를 복제해 저장하는 분산형 데이터 저장기술입니다. 여러 대의 컴퓨터가 기록을 검증하여 해킹을 막기에 보안성의 측면에서 탁월합니다. 블록체인에 저장하는 정보는 다양하기 때문에 블록체인을 충청북도교육청활용할 수 있는 분야도 매우 광범위합니다. 대표적으로 가상통화와 전자 결제, 디지털 인증뿐만 아니라 화물 추적 시스템, P2P 대출, 원산지부터 유통까지 전 과정을 추적하거나 예술품의 진품 감정, 위조화폐 방지, 전자투표, 전자시민권 발급, 차량 공유, 부동산 등기부, 병원 간 공유되는 의료기록 관리 등 신뢰성이 요구되는 다양한 분야에 활용할 수 있습니다."},{"q":"자기소개서에서 암호에 대해서 적었는데 폴리비오스 암호는 무엇인가요?","a":"네? 자기소개서에 적혀있지 않나요?[꼬리질문] 아니 적혀있는데 잘 모르겠네 그러면 암호의 순서를 바꿔서 사용하는 암호 같은 것도 알고 있나요?잘 모르겠습니다."},{"q":"라이파이가 뭔가요?","a":"빛으로 신호를 입력하면, LED 램프가 깜빡거리며 빛을 전송하고 그 깜빡인 빛을 다시 광검출기가 받아 디지털기기를 작동시키는 신호로 사용하게 되는 원리입니다. 라이파이의 가장 큰 장점은 가시광선을 사용하기 때문에 기존 와이파이보다 최고 100배이상 빠른 속도로 사용할 수 있으며 가시광선이 도달하는 곳까지만 통신이 가능하기 때문에 보안성이 탁월하다는 것입니다. 하지만 단점 역시 반드시 빛이 있는 곳에서만 통신이 가능하다는 것입니다. 하지만 라이파이가 가진 장점들이 결코 단순하지 않기 때문에 이 기술을 더욱 발전시킬 필요가 있다고 생각합니다."},{"q":"다문화 가정 봉사활동을 진행했다고 했는데 무엇을 느꼈나요?","a":"다문화 가정에서 자란 아이와 함께 공부하며 한국어와 한국의 문화에 적응할 수 있도록 도움을 주는 봉사활동을 진행했습니다. 이 봉사활동을 하면서 제가 만났던 아이의 부모님 두 분 모두가 베트남 분이셨습니다. 가장 큰 소통방법인 언어적 소통이라는 부분에서 어려움을 겪었지만 이를 통해 저 역시 베트남의 언어와 문화를 공부해 볼 수 있는 기회가 되었고 아이 역시 한국어를 사용하여 대화를 많이 할 수 있는 기회가 생겨 국어능력 뿐만 아니라 수학과목에서의 성적 역시 상승시킬 수 있었습니다. 이때 상대방을 이해하는 소통능력을 활용해 연극동아리활동과 학급임원 활동에서 의사소통의 문제를 융통성 있게 해결할 수 있었습니다. 후배들을 위한 조언 면접 대기시간이 길면 몇 시간이 걸릴 정도로 생각보다 길기 때문에 그 시간 동안 공부할 것을 가져가면 더욱 편안한 마음으로 면접을 볼 수 있습니다. 또, 한 질문에 대답을 못 했다고 하더라도 다음 질문이 남아있기에 차분한 마음가짐을 유지하는게 중요하다고 생각합니다. 저는 제가 준비했던 질문과 제가 가지고 있는 지식 수준을 넘는 질문을 여럿 받았기 때문에 모든 질문을 준비해가려는 자세가 아니라 후회 없이 답하고 오겠다는 자세를 가지는 게 중요하다고 생각합니다. 충청북도교육청"}],"result":"합격","resultNote":"X","src":"충청북도교육청 「2022 대입 면접 후기집」","year":"2022학년도"},{"univ":"인하대학교","dept":"생명공학과","jeonhyeong":"학생부종합(인하미래인재전형1. 1차 합격자 발표 때 공지받은 건물 앞에 가면 조교분들이 층에 따라 줄을 세운다.)","method":"2. 조교분들의 안내에 따라 들어가면서 발열체크, 신분증 확인 등등을 한다.3. 대기실에 가서 면접 안내 사항을 안내받는다.4. 가번호를 받고 휴대폰을 끄고 제출한다.(가방 있으면 가방에 넣어도 된다.)5. 자신의 가번호가 불리면 가서 면접을 본다.","notes":"꼭 KF94마스크를 써야 하고 층마다 대기하는 줄이 다르므로 꼭 주의해야 한다.","qa":[{"q":"긴장되세요?","a":"아니요 편안한 마음으로 왔습니다."},{"q":"먼저 자소서에 관해서 질문하겠습니다, 자기소개서에 텔로머레이스 과발현을 시키지 않고 다른 방법을 생각하셨다는데 그거에 대해서 말해주세요.","a":"노화에 가장 직접적인 원인이 되는 텔로미어의 길이를 연장시키기 위해 텔로머레이스를 과발현할 시 암세포로 변할 수도 있다는 문제점이 있어 텔로미어의 길이 감소의 속도를 줄이는 방안으로 사고를 전환하게 되었습니다. 산화적 스트레스가 텔로미어의 감소를 촉진시킨다는 논문을 보고 항산화제를 활용하는 방법과 모체의 운동이 자손의 텔로미어의 길이에 영향을 줄 수 있으므로 적절한 운동에 대한 방안, 아직 많이 연구된 것은 없지만 TRF1과 TERRA의 작용이 텔로미어의 길이에 영향을 준다는 논문을 보고 이를 활용한 방안을 제시했습니다."},{"q":"자기소개서에 있는 자료의 객관성과 관련된거 설명해주세요[대답] 논리학 선생님께 조언을 구하고, 논문을 보면서 메타분석한 내용에 대한 설명","a":""},{"q":"자기소개서에 있는 자료의 구조화에 대해 설명해주세요[대답] 본론 얼개를 활용한 자료의 구조화에 대해 설명충청북도교육청","a":""},{"q":"생기부 질문하겠습니다.실장으로서 자리를 배치할 때 친구들의 의견을 수합하여 자리를 배치하였다고 했는데 그게 굉장히 힘들었을 텐데 어떻게 했나요?[대답] 정시를 준비하는 친구와 수시를 준비하는 친구들의 의견을 반영하여 정시친구들은 뒷자리에 앉도록 배치를 하고 수시친구들은 앞자리에 배치했다는 내용에 대한 설명","a":""},{"q":"고급 생명과학에서 친구들에게 가장 좋은 문제로 평가 받았다는데 어떤 문제였나요?[대답] 유전자 재조합 시 가장 중요한 재조합된 세포를 선별하는 과정에 대한 문제를 만들기 위해 여러 가지 수능 문제와 기출문제를 분석하여 가장 합당한 문제를 그림자료까지 제시하며 ㄱㄴㄷ 보기를 활용한 문제를 만들었다는 설명","a":""},{"q":"화학에서 르샤틀리에의 원리를 이공계 기피현상으로 설명했다는데 어떻게 설명했나요[대답] 과학중심사회와 이공계의 어려움으로 인한 이공계 친구들의 기피현상과 관련하여 설명","a":""},{"q":"좋은 결과가 있기를 바라겠습니다.후배들을 위한 조언 충청북도교육청","a":""}],"result":"합격","resultNote":"","src":"충청북도교육청 「2022 대입 면접 후기집」","year":"2022학년도"},{"univ":"인하대학교","dept":"화학과","jeonhyeong":"학생부종합전형(미래인재전형)","method":"세미나실에서 대기 -> 면접실 앞에서 대기 -> 면접 진행","notes":"","qa":[{"q":"담임선생님께서 자기주도성이 뛰어난 학생이라고 해 주셨는데 그 이유가 무엇이라고 생각하나요?","a":"저 스스로와의 약속을 지키기 위해 플래너에 계획을 세우고 야간 자율학습을 통해 꾸준히 공부하려고 노력하였기 때문이라고 생각합니다."},{"q":"동아리 부장으로 활동을 하면서 온라인 활동도 병행한 것 같은데 온라인 활동으로는 무엇을 하셨나요?","a":"온라인 활동으로는 영화 속 과학적 오류 찾기, 실험 진행 후 활동 소감 발표 등의 활동을 진행하였습니다."},{"q":"잘 따라오지 않은 학생도 있었을 텐데 이럴 때는 어떻게 해결하였나요?","a":"따로 이야기를 하여 같이 하면 좋겠다고 얘기해 주었습니다. 또한 실험 전에 해야 할 역할을 주었습니다."},{"q":"화학과에서는 실험을 많이 진행할 텐데 잘 따라오지 않은 친구가 있으면 어떻게 할 것인가요?","a":"저는 실험을 진행할 때 보다 실험하기 전이 더 중요하다고 생각합니다. 그렇기 때문에 실험을 진행하기 전에 구체적으로 역할을 나눠서 같이 하도록 할 것입니다."},{"q":"원자가 결합 이론과 분자 오비탈 이론의 차이점에 대해 말해 보세요.","a":"원자가 결합 이론은 핵과 핵 사이에 전자 분포의 확률이 증가함으로써 공유결합을 하는 것이고 분자 오비탈은 원자가 결합 이론과는 다르게 새로운 결합성과 반결합성 오비탈이 생겨 전자들이 에너지가 낮은 것부터 차곡차곡 쌓여 결합을 형성하는 것입니다."},{"q":"동핵 이원자 오비탈과 이핵 이원자 오비탈의 차이점은 무엇인가요?","a":"동핵 이원자 오비탈은 두 원자의 에너지가 같은 반면에 이핵 이원자 오비탈은 두 원자의 충청북도교육청에너지 준위가 다릅니다. 또한 동핵 이원자 오비탈은 결합차수가 정수인 반면에 이핵 이원자 오비탈은 소수점이 생겨 정수가 아닙니다."},{"q":"수학 세특에 보면 물의 최소가 되는 부피를 확인하였다고 하는데 이것을 설명해 보세요.","a":"방정식을 지오지브라라는 앱을 이용하여 최소가 되는 부분을 확인해보았습니다.(수소 결합과 관련해서 설명해야 하는데 잘못 대답한 것 같음)"},{"q":"마지막으로 할 말 해보세요.","a":"고등학교 시절 화학 연구원의 꿈을 이루기 위해 화학과 관련된 다양한 활동을 하였습니다. 인하대학교 화학과에 진학하여 화학 기기들을 이용해 다양한 실험을 진행하고 싶습니다.감사합니다.후배들을 위한 조언 다른 대학교에 비해서 자소서 관련 질문이 적었던 것 같습니다.인하대학교는 특히 다른 학교에 비해 면접 시간이 짧습니다.진로 과목이 아닐지라도 진로 관련 활동은 모두 챙기는 것이 좋을 것 같습니다.인성 질문이 생각보다 많이 나왔습니다.면접 끝나기 2분 전에 노크해서 알려줍니다.충청북도교육청"}],"result":"합격","resultNote":"","src":"충청북도교육청 「2022 대입 면접 후기집」","year":"2022학년도"},{"univ":"인하대학교","dept":"기계공학부","jeonhyeong":"학생부 종합(인하미래인재전형)","method":"면접시간 6분 / 면접위원 2명","notes":"","qa":[{"q":"일의 단위는?","a":"J(줄)이라 대답함."},{"q":"물리에서 가장 어려웠던 부분은?","a":"운동부분이 가장 어려웠다. 어떤 부분에서 무슨 공식, 개념을 사용해야 할지 파악하기가 어렵다고 대답함."},{"q":"뉴턴 1,2,3법칙에 대해 설명하시오.","a":"뉴턴 1,2,3법칙에 대해 정석적으로 대답함."},{"q":"신뢰를 통해 원동력을 얻을 수 있다고 했는데 어떻게 얻을 수 있을까요?(자소서 기반 질문)","a":"누군가가 자신을 믿어준다면 그 사람의 기대를 충족시키고자 하는 마음이 원동력이 될 수 있다고 대답함."},{"q":"화학에서 에너지 보존 법칙에 대해 배웠는데 지구에서 에너지 보존 법칙을 말해보세요.(생기부 기반 질문, ‘물리보다 화학을 더 잘 하셨네요.’라고 말씀하시면서 질문함)","a":"여러 반응에서나 실생활에서 에너지는 손실이 된다. 하지만 이러한 에너지는 다른 형태의 에너지로 바뀌어 다른 곳에서 사용되며 지구 전체의 에너지는 평형을 이루게 된다고 대답함."}],"src":"세종특별자치시교육청 「2020 보인다! 면접지도 길라잡이」","year":"2020학년도"},{"univ":"인하대학교","dept":"전자공학과","jeonhyeong":"학생부 종합(인하미래인재전형)","method":"면접시간 6분 / 면접위원 2명","notes":"","qa":[{"q":"정전식 터치스크린이 무엇인가?","a":"정전식 터치스크린은 현재의 휴대폰에 적용되어 있는 기술로 서로 닿아있는 두 극판이 약전이 흐르고 있는 상태에서 전기가 흐르고 있는 사람의 몸, 손가락이 터치를 하게 된다면 극판의 전기의 흐름이 바뀌면서 휴대폰에서 전기의 흐름이 바뀐 곳을 추적해 좌표를 남겨 터치가 되는 방식인 터치스크린입니다."},{"q":"‘정전식’ 이라는 말이 무슨 의미인가?","a":"정전식이라는 것은 감압식과는 다르게 극판에 전기가 이미 흐르고 있는 상태로, 손가락이나 정전식 터치펜으로만 터치가 가능한 터치스크린의 방식입니다."},{"q":"감압식 터치스크린은 무엇인가?","a":"감압식 터치스크린은 정전식 터치스크린의 반대로 구형 휴대폰에 적용되어있는 기술입니다. 이는 두 극판이 서로 떨어져있어 물체로 터치를 하게 되면 압력이 가해져 두 극판이 맞닿게 되어 정전식처럼 전기가 흐르게 되는 방식의 터치스크린입니다."},{"q":"IOT가 무엇인가?","a":"IOT란 ‘Internet Of Things’ 즉, 사물인터넷으로 4차산업혁명이 다가오면서 초음파센서 휴지통과 같이 물체 속에 인터넷이 존재해 편리한 삶을 만들어주는 것입니다."},{"q":"물체속에 어떻게 인터넷이 존재할까?","a":"사실 인터넷이라는 말보다 전자회로가 더 많이 사용이 된다고 생각합니다. 방금 예로 든 초음파센서 휴지통도 초음파 센서로 일정거리에 오게 되면 자동으로 뚜껑이 열리게 되는 구조이기 때문입니다."},{"q":"수상중에 발명이나 노벨에세이에서 한 것을 자세하게 말해보라","a":"3학년 때, 발명아이디어에서 금상을 수상한 아이디어를 말씀드리자면, 유니버설 디자인으로 시각장애인분들을 위한 지팡이를 구상했었습니다. 초음파센서와 열감지 센서를 이용해 사용자의 안전을 보장하고 GPS센서를 이용해 블루투스 이어폰으로 도보의 상황을 듣도록 한 저만의 ‘스마트 지팡이’를 제작했습니다."},{"q":"거리조절에 대한 코딩을 했는데 자세하게 말해보라","a":"아두이노 초음파센서를 이용한 자율주행자동차를 제작할 때, 거리조절에 대한 코딩을 했는데, 초음파는 초속 340m 이기에 이를 cm로 바꾸려면 340/10000 이고, 초음파센서는 왕복으로 측정하기 때문에 2로 나누어 주어 대략의 계산값인 58을 거리에 나누어주어 cm 거리 계산을 하였습니다."},{"q":"물체 속에 어떻게 인터넷이 존재할까?","a":""},{"q":"수상 중에 발명이나 노벨 에세이에서 한 것을 자세하게 말해보라","a":""},{"q":"거리 조절에 대한 코딩을 했는데 자세하게 말해보라","a":""},{"q":"리더십을 발휘한 경험을 말해보라","a":""}],"src":"세종특별자치시교육청 「2020 보인다! 면접지도 길라잡이」","year":"2020학년도"},{"univ":"인하대학교","dept":"화학과","jeonhyeong":"학생부 종합(인하미래인재전형)","method":"면접시간 6~7분 / 면접위원 2명","notes":"","qa":[{"q":"수상기록에 글쓰기 관련 대회가 많은데 이유가 있는지","a":"글 쓰는 경험과 연습이 중요하다고 생각해 다수 참여함."},{"q":"글 쓰는 것을 중요하게 생각하는 이유가 뭔지","a":"글쓰기는 생각을 정리하고 논리적으로 제시하는 방법이라 중요하다고 생각함."},{"q":"자소서에 반응속도에 관한 탐구를 진행했다고 돼있는데 반응속도란 무엇인지","a":"개념 제시"},{"q":"탐구 실험 과정은?","a":"반응물의 농도와 온도를 조작하여 반응속도에 미치는 영향을 살펴봄."},{"q":"반응물의 농도와 온도가 반응속도와 어떤 관게인지","a":"비례함."},{"q":"태양전지에 관심이 많은 것 같은데 어떤 종류의 태양전지를 알고 있는지","a":"페로브스카이트, 실리콘, 유기 태양전지"},{"q":"페로브스카이트 태양전지에 대해 설명해보기","a":"페로브스카이트 분자구조로 이루어진 태양전지"},{"q":"페로브스카이트 분자구조에 대해 설명해보기","a":"사면체 두 개가 접해있는 구조"},{"q":"그 구성요소를 알고 있는지","a":"답변하지 못함."}],"src":"세종특별자치시교육청 「2020 보인다! 면접지도 길라잡이」","year":"2020학년도"}],"official":[{"category":"진로탐구역량","jeonhyeong":"","q":"B활동의 주제로 ‘OOOO’를 선정했는데, 해당 주제를 선정한 계기가 무엇인가? 주제 선정에 있어 본인은 어떤 역할을 했는가?","src":"경기도 진학 연구팀(진심) 「2026 면접을 준비하다」"},{"category":"의사소통역량","jeonhyeong":"","q":"1, 2학년 행동특성 및 종합의견을 보면 공통적으로 타인에 대한 배려심이 깊다고 기재되어 있다. 관련된 사례가 있는가?","src":"경기도 진학 연구팀(진심) 「2026 면접을 준비하다」"},{"category":"의사소통역량","jeonhyeong":"","q":"임원활동 전과 후를 비교해보았을 때 자신에게 변화된 점이 있다면 무엇인가? 그 이유는 무엇이라고 생각하는가?","src":"경기도 진학 연구팀(진심) 「2026 면접을 준비하다」"},{"category":"의사소통역량","jeonhyeong":"","q":"(인성관련) 자율활동에 부반장으로 활동하며 특별한 역할의 필요성을 어필하고 직접 수행했다고 기록되어 있는데, 그 역할이 왜 필요하다고 생각했으며, 이를 어떻게 수행했는지 설명해 주세요.","src":"경기도 진학 연구팀(진심) 「2026 면접을 준비하다」"},{"category":"기초학업역량","jeonhyeong":"","q":"이차전지융합학과 구분기재사항수업 시간에 배운 열역학 제2법칙의 열흐름과 같이 시간의 흐름도 엔트로피와 연관이 있세부능력 물리학을지 궁금하여 ‘○○○’을 읽음. 독서 후 주제 탐구 활동으로 '유전자의 변이가 세대를 거및 Ⅰ듭할수록 엔트로피는 어떤 방향으로 흘러가는지'에 대해 조사하여 이해한 내용을 정리함. 특기사항(2학년)보고서를 통해 탐구 능력과 자기 주도적 문제 해결력을 확인함. - 2학년 물리학Ⅰ 세부능력 및 특기사항을 보니 수업시간에 배운 열역학 제2법칙에 관심이 많았던 것 같은데, 열역학 제2법칙이 무엇인지 설명해 주세요.(설명) 기초학업역량에서의 질문은 교과 시간에 배운 간단한 원리나 개념 등을 질문하는 경우가 많습니다. 위 예시와 같이 관심을 갖고 탐구한 주제라면 그 주제에 포함된 개념이나 원리 등에 대해 잘 설명할 수 있어야 합니다. 또, 이런 원리가 어디에 활용되는지 사례를 들어 설명할 수 있다면 더 훌륭한 답변이 될 수 있습니다.","src":"인천광역시교육청 「2026학년도 대입 구술면접자료집」"},{"category":"기초학업역량","jeonhyeong":"","q":"국제통상학과구분기재사항세부능력 미국과 중국의 무역 분쟁으로 우리나라가 더 많은 피해를 보고 있고 이로 인해 경상수지경제및 가 지속적으로 적자인 상황에 주목함. 반도체 경기 불황 등 대외적인 요소가 더 많이 작(2학년)특기사항용하고 있지만 경상수지의 적자가 지속되면 우리 경제에도 큰 타격이 될 수 있다는 점을 강조함. 대외 무역의존도가 높은 우리 경제 상황을 정확히 분석하고 이를 극복하기 위한 방안으로 무역국가의 다변화와 자본, 기술 집약적 산업의 집중육성을 그 해결책으로 제시함.- 2학년 경제 수업시간에 미국과 중국의 무역 분쟁으로 인한 경상수지에 대해 알아본 것 같은데, 경상수지란 무엇인지 설명해 주세요.(설명) 위 지원자는 경제 수업시간에 배운 경상수지와 관련하여 국제 무역분쟁과 우리나라 무역구조의 특징, 문제점과 해결방안 등을 심화 탐구하였습니다. 이처럼 어떠한 주제에 대해 심화학습을 하기 위해서는 다루고 있는 주제에 대한 내용을 정확하게 알고 있어야만 할 것입니다. 평가자는 이를 확인하기 위해 지원자가 수업시간에 배운 기본적인 교과 내용에 대해 질문하는 경우가 많습니다. 이와 같은 질문에서는 장황한 설명보다는 명확하고 간결하게 핵심적인 내용 중심으로 설명하는 것이 좋습니다.","src":"인천광역시교육청 「2026학년도 대입 구술면접자료집」"},{"category":"진로탐구역량","jeonhyeong":"","q":"첨단바이오의약학과구분기재사항자유주제탐구 활동에선 ‘사람도 광합성을 할 수 있을까?’라는 주제로 명반응과 암반응을 통합과학엽록체의 틸라코이드, 스트로마 개념을 도입하여 체계적이면서도 이해하기 쉽게 설명함으(1학년)로써 학급 친구들에게 큰 호응을 받음.세부능력 및 광합성 과정을 자세히 배우며 흥미를 느껴 더 알아보고자 책 '○○○'을 읽음. 홍색황세균생명과학특기사항이 식물의 광합성을 이해하는 데 도움이 됐다는 구절을 읽고 식물 외 생물체도 광합성 하Ⅱ는 사실을 재인식하며 이를 지구온난화 문제에 활용하면 사회에 도움이 되리라 생각한 점(3학년)이 인상적임.생명과학Ⅱ에서 엽록체를 깊이 학습하며 광합성 하는 생물체에 관심을 가지게 되었고, 1창의적 진로학년 때의 활동을 이어 지구온난화 문제를 해결하고자 광합성 세균을 활용한 이산화탄소 체험활동(3학년)흡수체 제조를 목표로 탐구를 진행함- 1학년 때부터 꾸준히 광합성이라는 주제에 관심을 갖고 있는 것 같은데, 이 주제에 관심을 갖게 된 동기는 무엇인가요?(설명) 어떠한 주제에 대해 교과 또는 교과 외 활동을 연계하여 심화 탐구를 한 경험이 있다면 평가자는 이에 대해 확인하곤 합니다. 주제에 대해 관심을 갖게 된 이유는 무엇인지, 또는 탐구의 결과는 무엇인지 등 지원자의 관심과 탐구의 수준에 대해 질문함으로써 지원자가 진로에 대해 얼마나 고민하고 노력했는지에 대해 판단합니다. 다만 답변을 준비할 때에는 너무 장황한 설명이 되지 않도록 주의해야 합니다. 굳이 불필요한 과정과 결과에 대해 시간을 할애해가며 답변하지 않더라도 관심을 갖게 된 이유와 탐구를 통해 알게 된 내용을 간단히 설명해도 충분히 긍정적인 평가를 받을 수 있습니다. 이와 같이 학생부 내용을 바탕으로 지원자가 노력을 기울인 활동에 대해서는 면접에서 진위 여부를 확인하거나, 그 깊이에 대해 질문하는 경우가 많기 때문에 면접 전에 미리 답변을 준비하는 것이 좋습니다.","src":"인천광역시교육청 「2026학년도 대입 구술면접자료집」"},{"category":"진로탐구역량","jeonhyeong":"","q":"문화콘텐츠문화경영학과구분기재사항영어영어로 문제점 해결방안 글쓰기 시간에 미디어 속 혐오 표현의 문제점을 다룬 보고서를 세부능력 독해와작성함. 미디어 속 혐오 콘텐츠가 온라인상에 가볍게 소개되고 있으며 이는 소수집단에 대및 작문한 부정적인 인식을 강화하며 사회적 분열을 야기할 수 있다는 점을 지적함. 또한 미디어 특기사항(3학년)혐오 표현의 빠른 확산 속도와 익명성으로 인한 법률 규제의 어려움을 제시함.학년 특색 사업 활동에 참가하여 미디어 속 사회적 차별과 혐오에 대한 주제로 완성도 높창의적 자율은 영상물을 제작하여 학우들과 공유함. 정보를 올바르게 해석하고 비판적으로 수용할 수 체험활동(2학년)있는 태도의 중요성에 대한 메시지를 전달하였고 독후 활동의 모범 사례라는 평가를 받음. - 2학년 자율활동과 3학년 영어 독해와 작문 내용을 보니 미디어 속 혐오에 대해 고민해 본 것 같은데, 이에 대한 해결방안을 생각해 본 적 있다면 설명해 주세요.(설명) 인문사회계열 모집단위는 개념이나 이론적 학습도 중요하지만 일상생활에서 겪을 수 있는 사회 문제에 대해 생각해 보고, 이에 대한 문제해결 방안을 찾아보는 활동도 중요합니다. 위 지원자는 자신의 관심 분야인 미디어 분야에서 ‘미디어 속 혐오’라는 사회 문제를 주제로 다루고 있습니다. 평가자는 이러한 탐구과정에서 문제 제기 이외에 해결방안까지 고민해 보았는지 활동의 깊이에 대해 질문하고 있습니다. 깊이 있는 탐구 활동이 되기 위해서는 단순히 문제점을 찾아보는 데서 더 나아가 이를 해결하기 위한 본인의 고민이 필요합니다.다만, 여기서의 해결방안이 반드시 문제를 해결할 수 있는 완벽한 방안일 필요는 없습니다. 학생으로서 해결법을 고민해 보고 찾아본 내용이 있다면 이러한 내용으로도 충분한 답변이 될 수 있습니다.","src":"인천광역시교육청 「2026학년도 대입 구술면접자료집」"},{"category":"의사소통역량","jeonhyeong":"","q":"식품영양학과구분기재사항세부능력 교과서 모둠 활동이나 토론 활동 시간에는 진행이 원활하게 될 수 있도록 도움을 주었으영어Ⅰ및 며 시간 내에 활동이 이루어지고 의사소통이 원활히 이루어지도록 협력적인 모습을 자주 (2학년)특기사항보였다는 평가를 동료들로부터 받는 등 공동체 역량이 우수함.- 2학년 영어Ⅰ 과목 세특을 보니 의사소통이 원활히 이루어지도록 협력적인 모습을 자주 보였다는 내용이 기재되어 있는데, 어떤 노력을 했는지 설명해 주세요.(설명) 지원자의 의사소통역량은 교과 세특을 통해서도 확인할 수 있습니다. 위 사례와 같이 수업 시간 내에 친구들과 협력하는 과정에서 나의 역할이 두드러진 부분이 있다면 이에 대해 질문할 수 있습니다. 이러한 질문에 답할 때에는 당시 상황과 구체적인 나의 역할에 대해 간단히 설명할 수 있어야 하고, 협력 과정에서 어려움이 있었다면 어려움을 해결한 방안에 대해서도 구체적인 사례를 통해 덧붙여볼 수 있습니다.","src":"인천광역시교육청 「2026학년도 대입 구술면접자료집」"},{"category":"의사소통역량","jeonhyeong":"","q":"디자인테크놀로지학과 구분기재사항늘 용모가 단정하고 교사들과 주변 친구들에게 예의가 바르고 인사를 잘하며 다방면에서 모범적인 학생임. 친구들의 이야기에 귀 기울여 듣고 공감하는 따뜻한 마음씨를 가지고 있1학년고 힘들어하는 친구가 있으면 그냥 지나치지 않고 자신이 할 수 있는 도움을 주고자 노력하기도 하며 주변을 세심하게 잘 챙김. 행동특성 체육한마당, 축제, 야영 수련 활동 등 학급 친구들이 다 함께 참여하는 행사 때마다 소외및 되는 친구들이 있는지 살피고, 친구들에게 춤을 가르쳐주기도 하고, 주전선수로 뛰면서 활종합의견발한 응원을 끌어내는 등 배려심과 원만한 리더십을 발휘하며 학급 발전에 이바지함. 수업2학년이나 자습 시간에 멘티와 자연스럽게 소통하며 적극적으로 멘티 친구를 도와줌. 가르치는 입장에서도 멘티에게 배울 점을 잊지 않고 자기 성찰적인 모습도 보이며 서로 성장하고 발전할 수 있는 방향으로 나아가는 배려심을 보임.- 1, 2학년 행특을 보니 공통적으로 친구들을 도와주는 모습을 칭찬해주신 것 같은데, 힘들어하는 친구를 도와주었던 사례가 있다면 소개해주세요.(설명) 행특은 각 담임선생님께서 1년간 지원자를 가까이에서 살펴본 바에 대해 직접적으로 기재해주는 내용으로, 지원자의 인성, 소통, 협력 등의 모습을 확인할 수 있는 사항입니다. 위 사례와 같이 공통적으로 유사한 부분에 대해 언급한 내용이 있다면 구체적인 사례에 대해 질문하는 경우가 자주 있습니다. 이럴 때에는 부담 없이 실제 사례를 간단히 설명할 수만 있어도 괜찮습니다. 행특에 기재된 내용이 아니더라도 학생부 전반에 있어 좋은 평가가 있다면 그에 대한 사례를 기억해두고 실제 면접에서 자기소개하듯 편안함 마음으로 언급할 수 있다면 좋습니다.","src":"인천광역시교육청 「2026학년도 대입 구술면접자료집」"},{"category":"기초학업역량 (30%)","jeonhyeong":"인하미래인재","q":"3학년 과학과제연구 과목 대체당 실험에서 실험을 어떻게 설정하였나요?","src":"세종특별자치시교육청 「2027학년도 대입 수시모집 면접 전형 자료집」"},{"category":"기초학업역량 (30%)","jeonhyeong":"인하미래인재","q":"3학년 동아리 활동 중 ‘우주 건축을 위한 자가 치유 및 변형 가능한 지 능형 건축 재료 모색’이 뭔가요?","src":"세종특별자치시교육청 「2027학년도 대입 수시모집 면접 전형 자료집」"},{"category":"기초학업역량 (30%)","jeonhyeong":"인하미래인재","q":"생기부에 다양한 탐구를 진행한 것을 잘 보았습니다. 그러면 지원자는","src":"세종특별자치시교육청 「2027학년도 대입 수시모집 면접 전형 자료집」"},{"category":"진로탐구역량 (50%)","jeonhyeong":"인하미래인재","q":"CAR-T 치료제에 대해 알아보는 활동을 했었는데 CAR-T가 무엇인지 설명해 보세요.","src":"세종특별자치시교육청 「2027학년도 대입 수시모집 면접 전형 자료집」"},{"category":"진로탐구역량 (50%)","jeonhyeong":"인하미래인재","q":"실험할 때 역할 분배를 어떻게 하였는지 말해주세요.","src":"세종특별자치시교육청 「2027학년도 대입 수시모집 면접 전형 자료집」"},{"category":"진로탐구역량 (50%)","jeonhyeong":"인하미래인재","q":"‘긍정적인 분위기를 조성함’과 같이 행특에 좋은 내용이 많이 써져 있네요.","src":"세종특별자치시교육청 「2027학년도 대입 수시모집 면접 전형 자료집」"},{"category":"공동체역량 (20%)","jeonhyeong":"인하미래인재","q":"리더십이 드러나는 활동이 많이 보이는 데 기억이 남는 점은?","src":"세종특별자치시교육청 「2027학년도 대입 수시모집 면접 전형 자료집」"}],"admission":[{"jeonhyeong":"인하미래인재","select":"서류 100% (3.5배수) 1단계 *의예과 (3배수) 2단계 1단계 70% + 면접 30%","type":"서류기반 면접","method":"- 전 모집단위: 면접 위원 2인과 지원자 1인의 개별 면접 - 의예과: 면접위원 2인과 지원자 1인 개별면접, 2개의 면접실 이동하며 진행","schedule":"경영대학, 사범대학(수교과 제외), 사회과학대학, 문과대학, 예술체육대학, 소프트 2026.11.21(토) 웨어융합대학 2026.11.22(일) 공과대학, 자연과학대학, 수학교육과, 의과대학, 간호대학, 바이오시스템융합부","notes":"","areas":[{"area":"기초학업역량 (30%)","questions":["3학년 과학과제연구 과목 대체당 실험에서 실험을 어떻게 설정하였나요?","3학년 동아리 활동 중 ‘우주 건축을 위한 자가 치유 및 변형 가능한 지 능형 건축 재료 모색’이 뭔가요?","생기부에 다양한 탐구를 진행한 것을 잘 보았습니다. 그러면 지원자는"]},{"area":"진로탐구역량 (50%)","questions":["CAR-T 치료제에 대해 알아보는 활동을 했었는데 CAR-T가 무엇인지 설명해 보세요.","실험할 때 역할 분배를 어떻게 하였는지 말해주세요.","‘긍정적인 분위기를 조성함’과 같이 행특에 좋은 내용이 많이 써져 있네요."]},{"area":"공동체역량 (20%)","questions":["리더십이 드러나는 활동이 많이 보이는 데 기억이 남는 점은?"]}]}]};
